```javascript
//
// Implementations of promisify and re-implementations of Promise combinators.
//

const toPromise = (value) => new Promise((resolve) => resolve(value));

export const promisify = (fn) => {
  return (...args) =>
    new Promise((resolve, reject) => {
      fn(...args, (error, data) => {
        if (error) {
          reject(error);
        } else {
          resolve(data);
        }
      });
    });
};

export const all = (promises) => {
  if (!promises) return toPromise(undefined);
  const items = Array.from(promises);
  if (items.length === 0) return toPromise([]);

  return new Promise((resolve, reject) => {
    const results = new Array(items.length);
    let remaining = items.length;

    items.forEach((item, index) => {
      toPromise(item).then((value) => {
        results[index] = value;
        remaining -= 1;
        if (remaining === 0) resolve(results);
      }, reject);
    });
  });
};

export const allSettled = (promises) => {
  if (!promises) return toPromise(undefined);
  const items = Array.from(promises);
  if (items.length === 0) return toPromise([]);

  return new Promise((resolve) => {
    const results = new Array(items.length);
    let remaining = items.length;

    const settle = (index, result) => {
      results[index] = result;
      remaining -= 1;
      if (remaining === 0) resolve(results);
    };

    items.forEach((item, index) => {
      toPromise(item).then(
        (value) => settle(index, value),
        (error) => settle(index, error),
      );
    });
  });
};

export const race = (promises) => {
  if (!promises) return toPromise(undefined);
  const items = Array.from(promises);
  if (items.length === 0) return toPromise([]);

  return new Promise((resolve, reject) => {
    items.forEach((item) => {
      toPromise(item).then(resolve, reject);
    });
  });
};

export const any = (promises) => {
  if (!promises) return toPromise(undefined);
  const items = Array.from(promises);
  if (items.length === 0) return toPromise([]);

  return new Promise((resolve, reject) => {
    const errors = new Array(items.length);
    let remaining = items.length;

    items.forEach((item, index) => {
      toPromise(item).then(resolve, (error) => {
        errors[index] = error;
        remaining -= 1;
        if (remaining === 0) reject(errors);
      });
    });
  });
