//
// Promise helpers: `promisify`, plus hand-written versions of the built-in
// `Promise.all`, `Promise.allSettled`, `Promise.race` and `Promise.any`
// (none of these four built-ins is used below).
//

/**
 * Turns a function relying on the "callback pattern" (an error-first callback
 * given as the last argument) into a function that returns a Promise.
 *
 * The returned function accepts the same arguments as `fn`, minus the callback.
 * The Promise is rejected with `error` when the callback receives one,
 * otherwise it is resolved with `data`.
 */
export const promisify = (fn) =>
  function promisified(...args) {
    return new Promise((resolve, reject) => {
      fn.call(this, ...args, (error, data) => {
        if (error) {
          reject(error);
        } else {
          resolve(data);
        }
      });
    });
  };

/**
 * Shared plumbing of the combinators below.
 *
 * - Called without any argument, a combinator resolves with `undefined`.
 * - Called with an empty list, it resolves with an empty array.
 * - Otherwise `executor` receives the items (each one wrapped in a promise, so
 *   plain values and thenables are accepted too) along with the `resolve` and
 *   `reject` functions of the promise that is returned.
 * - A non-iterable argument makes the returned promise reject with a TypeError.
 */
const combine = (promises, executor) => {
  if (promises === undefined) {
    return Promise.resolve(undefined);
  }

  return new Promise((resolve, reject) => {
    const items = [...promises].map((item) => Promise.resolve(item));

    if (items.length === 0) {
      resolve([]);
    } else {
      executor(items, resolve, reject);
    }
  });
};

/**
 * Resolves with the array of all the values (in the order the promises were
 * given) once every promise is resolved, or rejects as soon as one of them
 * rejects.
 */
export const all = (promises) =>
  combine(promises, (items, resolve, reject) => {
    const values = new Array(items.length);
    let pending = items.length;

    items.forEach((item, index) => {
      item.then((value) => {
        values[index] = value;
        pending -= 1;

        if (pending === 0) {
          resolve(values);
        }
      }, reject);
    });
  });

/**
 * Resolves once every promise is settled (resolved or rejected). The value is
 * an array, in the order the promises were given, holding for each of them
 * either its resolved value or its rejection reason.
 */
export const allSettled = (promises) =>
  combine(promises, (items, resolve) => {
    const outcomes = new Array(items.length);
    let pending = items.length;

    const settle = (index, outcome) => {
      outcomes[index] = outcome;
      pending -= 1;

      if (pending === 0) {
        resolve(outcomes);
      }
    };

    items.forEach((item, index) => {
      item.then(
        (value) => settle(index, value),
        (error) => settle(index, error)
      );
    });
  });

/**
 * Settles the same way as the first promise that settles: it resolves with its
 * value, or rejects with its error.
 */
export const race = (promises) =>
  combine(promises, (items, resolve, reject) => {
    items.forEach((item) => {
      item.then(resolve, reject);
    });
  });

/**
 * Resolves with the value of the first promise that resolves. If all of the
 * promises reject, rejects with the array of their errors (in the order the
 * promises were given).
 */
export const any = (promises) =>
  combine(promises, (items, resolve, reject) => {
    const errors = new Array(items.length);
    let pending = items.length;

    items.forEach((item, index) => {
      item.then(resolve, (error) => {
        errors[index] = error;
        pending -= 1;

        if (pending === 0) {
          reject(errors);
        }
      });
    });
  });
```

