- `allSettled` never rejects. It collects `{status, value}` or `{status, reason}` objects in input order.
- `race` settles with the first promise to settle. Non-promise values are treated as already resolved. An empty input stays pending forever, as the built-in does.
- `any` resolves with the first fulfilled value. If all promises reject, it rejects with an `AggregateError` that holds the errors in input order. An empty input rejects immediately.

The built-in `Promise` methods are not used. Only the `Promise` constructor and `.then` are used, and `Promise.resolve` is replaced by a small `toPromise` helper that wraps each input in a `new Promise`.

promises.js
```javascript
const toPromise = (p) => new Promise((resolve) => resolve(p));

export const promisify = (fn) => {
  return (...args) =>
    new Promise((resolve, reject) => {
      fn(...args, (error, data) => {
        if (error) {
          reject(error);
        } else {
          resolve(data);
        }
      });
    });
};

export const all = (promises) => {
  return new Promise((resolve, reject) => {
    if (!promises || promises.length === 0) {
      resolve([]);
      return;
    }
    const results = new Array(promises.length);
    let remaining = promises.length;
    promises.forEach((p, i) => {
      toPromise(p).then((value) => {
        results[i] = value;
        remaining -= 1;
        if (remaining === 0) resolve(results);
      }, reject);
    });
  });
};

export const allSettled = (promises) => {
  return new Promise((resolve) => {
    if (!promises || promises.length === 0) {
      resolve([]);
      return;
    }
    const results = new Array(promises.length);
    let remaining = promises.length;
    const done = () => {
      remaining -= 1;
      if (remaining === 0) resolve(results);
    };
    promises.forEach((p, i) => {
      toPromise(p).then(
        (value) => {
          results[i] = { status: 'fulfilled', value };
          done();
        },
        (reason) => {
          results[i] = { status: 'rejected', reason };
          done();
        },
      );
    });
  });
};

export const race = (promises) => {
  return new Promise((resolve, reject) => {
    promises.forEach((p) => {
      toPromise(p).then(resolve, reject);
    });
  });
};

export const any = (promises) => {
  return new Promise((resolve, reject) => {
    if (!promises || promises.length === 0) {
      reject(new AggregateError([], 'All promises were rejected'));
      return;
    }
    const errors = new Array(promises.length);
    let remaining = promises.length;
    promises.forEach((p, i) => {
      toPromise(p).then(resolve, (error) => {
        errors[i] = error;
        remaining -= 1;
        if (remaining === 0) {
          reject(new AggregateError(errors, 'All promises were rejected'));
        }
      });
    });
  });
};
