import java.util.stream.IntStream;

class House {

    // The subjects of the rhyme, in the order in which they are introduced.
    private static final String[] SUBJECTS = {
        "house that Jack built",
        "malt",
        "rat",
        "cat",
        "dog",
        "cow with the crumpled horn",
        "maiden all forlorn",
        "man all tattered and torn",
        "priest all shaven and shorn",
        "rooster that crowed in the morn",
        "farmer sowing his corn",
        "horse and the hound and the horn"
    };

    // ACTIONS[i] describes what SUBJECTS[i + 1] did to SUBJECTS[i].
    private static final String[] ACTIONS = {
        "that lay in",
        "that ate",
        "that killed",
        "that worried",
        "that tossed",
        "that milked",
        "that kissed",
        "that married",
        "that woke",
        "that kept",
        "that belonged to"
    };

    String verse(int verse) {
        if (verse < 1 || verse > SUBJECTS.length) {
            throw new IllegalArgumentException(
                    "Verse must be between 1 and " + SUBJECTS.length + " but was " + verse + ".");
        }

        StringBuilder result = new StringBuilder("This is the ").append(SUBJECTS[verse - 1]);
        for (int i = verse - 1; i > 0; i--) {
            result.append('\n')
                  .append(ACTIONS[i - 1])
                  .append(" the ")
                  .append(SUBJECTS[i - 1]);
        }
        return result.append('.').toString();
    }

    String verses(int startVerse, int endVerse) {
        return IntStream.rangeClosed(startVerse, endVerse)
                .mapToObj(this::verse)
                .collect(Collectors.joining("\n\n"));
    }

    String sing() {
        return verses(1, SUBJECTS.length);
    }

