I implemented `Answer` in `wordy.go` as a small left-to-right parser, with no precedence rules.

- It requires the question to start with `What is` and end with `?`, and returns `false` otherwise.
- It splits the body into tokens and handles the operator words `plus`, `minus`, `multiplied by` and `divided by`.
- It reads the first token as a number, then repeatedly reads an operator followed by a number. Any unknown operator, missing operand, or two operators in a row returns `false`.
- Division by zero returns `false`.
- A number followed by another number, or a trailing operator, also returns `false`.
- Negative numbers work through `strconv.Atoi`.

wordy.go
```go
package wordy

import (
	"strconv"
	"strings"
)

func Answer(question string) (int, bool) {
	q := strings.TrimSpace(question)
	if !strings.HasPrefix(q, "What is") || !strings.HasSuffix(q, "?") {
		return 0, false
	}
	q = strings.TrimSuffix(strings.TrimPrefix(q, "What is"), "?")
	tokens := strings.Fields(q)
	if len(tokens) == 0 {
		return 0, false
	}

	result, err := strconv.Atoi(tokens[0])
	if err != nil {
		return 0, false
	}

	i := 1
	for i < len(tokens) {
		op := tokens[i]
		i++
		switch op {
		case "multiplied", "divided":
			if i >= len(tokens) || tokens[i] != "by" {
				return 0, false
			}
			i++
		case "plus", "minus":
		default:
			return 0, false
		}
		if i >= len(tokens) {
			return 0, false
		}
		n, err := strconv.Atoi(tokens[i])
		if err != nil {
			return 0, false
		}
		i++

		switch op {
		case "plus":
			result += n
		case "minus":
			result -= n
		case "multiplied":
			result *= n
		case "divided":
			if n == 0 {
				return 0, false
			}
			result /= n
		}
	}
	return result, true
}
```

