```go
// Package wordy parses and evaluates simple math word problems.
package wordy

import (
	"strconv"
	"strings"
)

// operation applies a binary operator to its operands. The boolean result is
// false if the operation can't be carried out, e.g. when dividing by zero.
type operation func(a, b int) (int, bool)

// operations holds the supported operators, keyed by the words used to write
// them in a question.
var operations = map[string]operation{
	"plus": func(a, b int) (int, bool) {
		return a + b, true
	},
	"minus": func(a, b int) (int, bool) {
		return a - b, true
	},
	"multiplied by": func(a, b int) (int, bool) {
		return a * b, true
	},
	"divided by": func(a, b int) (int, bool) {
		if b == 0 {
			return 0, false
		}
		return a / b, true
	},
}

// Answer evaluates a math word problem such as "What is 5 plus 13?".
//
// Numbers may be negative, and the supported operations are "plus", "minus",
// "multiplied by" and "divided by". Operations can be chained and are
// evaluated strictly from left to right, ignoring the usual order of
// operations, so "What is 3 plus 2 multiplied by 3?" is 15, not 9.
//
// The boolean result reports whether the question could be answered. It is
// false (and the integer 0) for anything that is not a well-formed math
// question: unsupported operations, non-math questions, invalid syntax, and
// calculations that can't be done such as dividing by zero.
func Answer(question string) (int, bool) {
	question = strings.TrimSpace(question)
	if !strings.HasSuffix(question, "?") {
		return 0, false
	}

	words := strings.Fields(strings.TrimSuffix(question, "?"))
	if len(words) < 2 || words[0] != "What" || words[1] != "is" {
		return 0, false
	}

	return evaluate(tokenize(words[2:]))
}

// tokenize groups the words of a problem into tokens. Operators written with
// more than one word, like "multiplied by", are joined into a single token so
// that every token is either a number or an operator.
func tokenize(words []string) []string {
	tokens := make([]string, 0, len(words))
	for i := 0; i < len(words); i++ {
		token := words[i]
		if i+1 < len(words) {
			joined := token + " " + words[i+1]
			if _, ok := operations[joined]; ok {
				token = joined
				i++
			}
		}
		tokens = append(tokens, token)
	}
	return tokens
}

// evaluate computes the value of tokens of the form
//
//	number (operator number)*
//
// working strictly from left to right. It returns false if the tokens don't
// have that form or if an operation can't be performed.
func evaluate(tokens []string) (int, bool) {
	if len(tokens) == 0 {
		return 0, false
	}

	result, err := strconv.Atoi(tokens[0])
	if err != nil {
		return 0, false
	}

	for i := 1; i < len(tokens); i += 2 {
		apply, ok := operations[tokens[i]]
		if !ok {
			// Not a supported operator: unsupported operation or bad syntax,
			// e.g. "52 cubed", "1 2 plus" or "1 plus 2 1".
			return 0, false
		}
		if i+1 >= len(tokens) {
			// The operator has no right-hand operand, e.g. "1 plus".
			return 0, false
		}

		operand, err := strconv.Atoi(tokens[i+1])
		if err != nil {
			// Not a number, e.g. "1 plus plus 2".
			return 0, false
		}

		if result, ok = apply(result, operand); !ok {
			return 0, false
		}
	}

	return result, true
}
