```
#if !defined(BANK_ACCOUNT_H)
#define BANK_ACCOUNT_H

#include <mutex>
#include <stdexcept>

namespace Bankaccount {

// A bank account that can safely be used from multiple threads at once.
//
// Every public operation locks the account for its whole duration, so a
// read-modify-write sequence such as "check the balance, then change it" can
// never be interleaved with another operation on the same account.
//
// Operations that are not allowed (using a closed account, depositing or
// withdrawing a negative amount, overdrawing the account, ...) throw
// std::runtime_error and leave the account unchanged.
class Bankaccount {
   public:
    Bankaccount() = default;

    // An account owns a mutex and has a unique identity, so it can be neither
    // copied nor moved.
    Bankaccount(const Bankaccount&) = delete;
    Bankaccount& operator=(const Bankaccount&) = delete;

    // Opens the account with a zero balance.
    // Throws if the account is already open.
    void open();

    // Closes the account and discards its balance.
    // Throws if the account is not open.
    void close();

    // Adds `amount` to the balance.
    // Throws if the account is not open or `amount` is negative.
    void deposit(int amount);

    // Removes `amount` from the balance.
    // Throws if the account is not open, `amount` is negative, or `amount`
    // is greater than the current balance.
    void withdraw(int amount);

    // Returns the current balance.
    // Throws if the account is not open.
    int balance() const;

   private:
    // Throws if the account is closed. The caller must hold `mutex_`.
    void require_open() const;

    mutable std::mutex mutex_;
    bool open_{false};
    int balance_{0};
};  // class Bankaccount

}  // namespace Bankaccount

#endif  // BANK_ACCOUNT_H
