}

// the cursor is expected to act as if it is at the position of an element
// and it also has to work with and be able to insert into an empty list.
impl<T> Cursor<'_, T> {
    /// Take a mutable reference to the current element
    pub fn peek_mut(&mut self) -> Option<&mut T> {
        // SAFETY: `current` points to a live node owned by the list, which we
        // borrow mutably for the lifetime of `&mut self`.
        self.current
            .map(|node| unsafe { &mut (*node.as_ptr()).elem })
    }

    /// Move one position forward (towards the back) and
    /// return a reference to the new position
    #[allow(clippy::should_implement_trait)]
    pub fn next(&mut self) -> Option<&mut T> {
        let node = self.current?;
        // SAFETY: `node` is a live node of the list.
        let next = unsafe { (*node.as_ptr()).next };
        let next = next?;
        self.current = Some(next);
        self.peek_mut()
    }

    /// Move one position backward (towards the front) and
    /// return a reference to the new position
    pub fn prev(&mut self) -> Option<&mut T> {
        let node = self.current?;
        // SAFETY: `node` is a live node of the list.
        let prev = unsafe { (*node.as_ptr()).prev };
        let prev = prev?;
        self.current = Some(prev);
        self.peek_mut()
    }

    /// Remove and return the element at the current position and move the cursor
    /// to the neighboring element that's closest to the back. This can be
    /// either the next or previous position.
    pub fn take(&mut self) -> Option<T> {
        let node = self.current?;
        // SAFETY: `node` was created by `Box::into_raw`/leak and is still owned
        // by the list; we unlink it first so no other pointer refers to it, then
        // reclaim the box exactly once.
        unsafe {
            let boxed = Box::from_raw(node.as_ptr());
            match boxed.prev {
                Some(prev) => (*prev.as_ptr()).next = boxed.next,
                None => self.list.front = boxed.next,
            }
            match boxed.next {
                Some(next) => (*next.as_ptr()).prev = boxed.prev,
                None => self.list.back = boxed.prev,
            }
            self.list.len -= 1;
            self.current = boxed.next.or(boxed.prev);
            Some(boxed.elem)
        }
    }

    pub fn insert_after(&mut self, element: T) {
        let new = Box::new(Node {
            elem: element,
            prev: self.current,
            next: None,
        });
        let new = NonNull::from(Box::leak(new));
        match self.current {
            None => {
                // empty list
                self.list.front = Some(new);
                self.list.back = Some(new);
                self.current = Some(new);
            }
            Some(cur) => {
                // SAFETY: `cur` is a live node; `next` (if any) is also live.
                unsafe {
                    let next = (*cur.as_ptr()).next;
                    (*new.as_ptr()).next = next;
                    (*cur.as_ptr()).next = Some(new);
                    match next {
                        Some(next) => (*next.as_ptr()).prev = Some(new),
                        None => self.list.back = Some(new),
                    }
                }
            }
        }
        self.list.len += 1;
    }

    pub fn insert_before(&mut self, element: T) {
        let new = Box::new(Node {
            elem: element,
            prev: None,
            next: self.current,
        });
        let new = NonNull::from(Box::leak(new));
        match self.current {
            None => {
                // empty list
                self.list.front = Some(new);
                self.list.back = Some(new);
                self.current = Some(new);
            }
            Some(cur) => {
                // SAFETY: `cur` is a live node; `prev` (if any) is also live.
                unsafe {
                    let prev = (*cur.as_ptr()).prev;
                    (*new.as_ptr()).prev = prev;
                    (*cur.as_ptr()).prev = Some(new);
                    match prev {
                        Some(prev) => (*prev.as_ptr()).next = Some(new),
                        None => self.list.front = Some(new),
                    }
                }
            }
        }
        self.list.len += 1;
    }
}

impl<'a, T> Iterator for Iter<'a, T> {
    type Item = &'a T;

    fn next(&mut self) -> Option<&'a T> {
        let node = self.next?;
        // SAFETY: the iterator borrows the list immutably for 'a, so all nodes
        // stay alive and unmodified for 'a.
        unsafe {
            let node = &*node.as_ptr();
            self.next = node.next;
            Some(&node.elem)
        }
    }
}
