use std::marker::PhantomData;
use std::ptr::NonNull;

// this module adds some functionality based on the required implementations
// here like: `LinkedList::pop_back` or `Clone for LinkedList<T>`
// You are free to use anything in it, but it's mainly for the test framework.
mod pre_implemented;

/// A pointer to a node of a list, or `None` if there is no such node.
type Link<T> = Option<NonNull<Node<T>>>;

/// A heap allocated node of a [`LinkedList`].
struct Node<T> {
    element: T,
    /// The node in front of this one; `None` if this is the front of the list.
    prev: Link<T>,
    /// The node behind this one; `None` if this is the back of the list.
    next: Link<T>,
}

/// A doubly linked list.
///
/// # Invariants
///
/// The `unsafe` code in this module relies on the following invariants. Every
/// operation that touches the nodes has to uphold them:
///
/// 1. Every `Some` link (`front`, `back` and the `prev`/`next` fields of the
///    nodes) points to a live `Node<T>` that was allocated with `Box` and is
///    owned by this list. A node belongs to exactly one list and is freed
///    exactly once, right after it was unlinked from that list.
/// 2. `front` and `back` are `None` if and only if the list is empty
///    (`len == 0`).
/// 3. The nodes form a proper chain: `front` has no `prev`, `back` has no
///    `next`, `a.next == Some(b)` holds if and only if `b.prev == Some(a)`,
///    and following the `next` links from `front` visits exactly `len` nodes
///    and ends at `back`.
/// 4. The nodes are only accessed through the list: shared access to a node
///    requires a `&LinkedList`, mutable access requires a `&mut LinkedList`.
///    Hence the aliasing rules of references also hold for the nodes, even
///    though they are linked with raw pointers.
pub struct LinkedList<T> {
    front: Link<T>,
    back: Link<T>,
    len: usize,
    // The list owns boxed nodes, and thereby values of type `T`. This marker
    // tells the compiler so (which matters for the drop checker). `Box` is
    // covariant over its content, just like `NonNull`, so the list stays
    // covariant over `T`.
    _marker: PhantomData<Box<Node<T>>>,
}

/// A cursor on a [`LinkedList`]. It is positioned on one element of the list,
/// can move over the list, and can insert and remove elements at its position.
///
/// # Invariants
///
/// `current` is `None` if and only if the list is empty, otherwise it points to
/// a node of `list`.
///
/// The cursor holds the only reference to the list for as long as it exists,
/// and only its own methods modify the list. They keep `current` up to date, so
/// the node it points to can't be removed or freed behind the cursor's back.
pub struct Cursor<'a, T> {
    list: &'a mut LinkedList<T>,
    current: Link<T>,
}

/// An iterator over the elements of a [`LinkedList`], from front to back.
///
/// # Invariants
///
/// `next_node` is `None` or points to a node of a list that is borrowed
/// (shared) for `'a`. The list can't be modified or dropped during that time,
/// so the node stays valid and unchanged for the whole of `'a`.
pub struct Iter<'a, T> {
    next_node: Link<T>,
    _marker: PhantomData<&'a T>,
}

// SAFETY: A `LinkedList<T>` uniquely owns its nodes and the elements in them,
// like a `Vec<T>` does, and it shares no state with other lists (the raw
// pointers never point outside of the list). Sending the list to another thread
// is the same as sending all of its `T`s there, which is fine if `T: Send`.
unsafe impl<T: Send> Send for LinkedList<T> {}

// SAFETY: Through a shared reference to the list, elements can only be reached
// by shared references (`iter`) and there is no interior mutability. Doing that
// from several threads at once is fine if `T: Sync`.
unsafe impl<T: Sync> Sync for LinkedList<T> {}

// SAFETY: An `Iter` behaves like a shared reference into the list, and
// `&LinkedList<T>` is `Send` and `Sync` if `T: Sync`.
unsafe impl<T: Sync> Send for Iter<'_, T> {}
unsafe impl<T: Sync> Sync for Iter<'_, T> {}

// SAFETY: A `Cursor` behaves like a `&mut LinkedList<T>`, which is `Send` if
// `T: Send`. The pointer to the current node points into the exclusively
// borrowed list and is only used through the cursor. A `&Cursor` can't be used
// to do anything at all, and `&mut LinkedList<T>` is `Sync` if `T: Sync`.
unsafe impl<T: Send> Send for Cursor<'_, T> {}
unsafe impl<T: Sync> Sync for Cursor<'_, T> {}

impl<T> LinkedList<T> {
    pub fn new() -> Self {
        LinkedList {
            front: None,
            back: None,
            len: 0,
            _marker: PhantomData,
        }
    }

    // You may be wondering why it's necessary to have is_empty()
    // when it can easily be determined from len().
    // It's good custom to have both because len() can be expensive for some types,
    // whereas is_empty() is almost always cheap.
    // (Also ask yourself whether len() is expensive for LinkedList)
    pub fn is_empty(&self) -> bool {
        self.len == 0
    }

    /// The number of elements in the list. This is cheap, since the length is
    /// tracked whenever the list is modified.
    pub fn len(&self) -> usize {
        self.len
    }

    /// Return a cursor positioned on the front element
    pub fn cursor_front(&mut self) -> Cursor<'_, T> {
        Cursor {
            current: self.front,
            list: self,
        }
    }

    /// Return a cursor positioned on the back element
    pub fn cursor_back(&mut self) -> Cursor<'_, T> {
        Cursor {
            current: self.back,
            list: self,
        }
    }

    /// Return an iterator that moves from front to back
    pub fn iter(&self) -> Iter<'_, T> {
        Iter {
            next_node: self.front,
            _marker: PhantomData,
        }
    }
}

// The two primitive operations that all modifications of the list are built
// upon. They are only used by the `Cursor`.
impl<T> LinkedList<T> {
    /// Allocates a node for `element` and links it into the list between
    /// `prev` and `next`. Returns a pointer to the new node.
    ///
    /// # Safety
    ///
    /// `prev` and `next` have to be neighbours in this list, where `None`
    /// stands for the position in front of the front, respectively behind the
    /// back of the list. That means one of the following has to hold:
    ///
    /// - the list is empty and `prev` and `next` are both `None`,
    /// - `prev` is `None` and `next` is the front of the list,
    /// - `next` is `None` and `prev` is the back of the list,
    /// - `prev` and `next` are nodes of this list and `prev.next == Some(next)`.
    unsafe fn link(&mut self, prev: Link<T>, next: Link<T>, element: T) -> NonNull<Node<T>> {
        // The list takes ownership of the allocation (invariant 1). It is
        // reclaimed again in `unlink`.
        let node = NonNull::from(Box::leak(Box::new(Node {
            element,
            prev,
            next,
        })));

        match prev {
            // SAFETY: `prev` is a node of this list (precondition), hence valid
            // (invariant 1), and `&mut self` gives us exclusive access to all
            // nodes of the list (invariant 4).
            Some(mut prev) => unsafe { prev.as_mut().next = Some(node) },
            None => self.front = Some(node),
        }
        match next {
            // SAFETY: same as above, for `next`.
            Some(mut next) => unsafe { next.as_mut().prev = Some(node) },
            None => self.back = Some(node),
        }
        self.len += 1;

        node
    }

    /// Unlinks `node` from the list and hands back ownership of it. The `prev`
    /// and `next` pointers of the returned node still point to its former
    /// neighbours, which are still part of the list.
    ///
    /// # Safety
    ///
    /// `node` has to be a node of this list. The node is freed when the
    /// returned box is dropped, so the caller must not dereference any other
    /// pointer to it after this call.
    unsafe fn unlink(&mut self, node: NonNull<Node<T>>) -> Box<Node<T>> {
        // SAFETY: `node` is a node of this list (precondition), so it was
        // allocated with `Box` and wasn't freed yet (invariant 1). Below it is
        // removed from the chain, and the caller promised not to use other
        // pointers to it, so taking ownership of it here is fine.
        let node = unsafe { Box::from_raw(node.as_ptr()) };

        match node.prev {
            // SAFETY: `prev` is a node of this list other than `node`
            // (invariants 1 and 3) and we have exclusive access to it
            // (invariant 4).
            Some(mut prev) => unsafe { prev.as_mut().next = node.next },
            None => self.front = node.next,
        }
        match node.next {
            // SAFETY: same as above, for `next`.
            Some(mut next) => unsafe { next.as_mut().prev = node.prev },
            None => self.back = node.prev,
        }
        self.len -= 1;

        node
    }
}

// the cursor is expected to act as if it is at the position of an element
// and it also has to work with and be able to insert into an empty list.
impl<T> Cursor<'_, T> {
    /// Take a mutable reference to the current element
    pub fn peek_mut(&mut self) -> Option<&mut T> {
        let mut node = self.current?;
        // SAFETY: `node` points to a node of the list (cursor invariant), so it
        // is valid (list invariant 1). The returned reference borrows the
        // cursor, which has exclusive access to the list, so nothing else can
        // access or free the node while the reference is alive.
        Some(unsafe { &mut node.as_mut().element })
    }

    /// Move one position forward (towards the back) and
    /// return a reference to the new position.
    ///
    /// If the cursor is already on the back element (or the list is empty), it
    /// stays where it is and `None` is returned.
    #[allow(clippy::should_implement_trait)]
    pub fn next(&mut self) -> Option<&mut T> {
        let node = self.current?;
        // SAFETY: `node` points to a valid node of the list (cursor invariant),
        // and we may read it since the cursor has exclusive access to the list.
        let next = unsafe { node.as_ref().next }?;
        // `next` is a node of the list (invariant 1), so the cursor invariant
        // still holds.
        self.current = Some(next);
        self.peek_mut()
    }

    /// Move one position backward (towards the front) and
    /// return a reference to the new position.
    ///
    /// If the cursor is already on the front element (or the list is empty), it
    /// stays where it is and `None` is returned.
    pub fn prev(&mut self) -> Option<&mut T> {
        let node = self.current?;
        // SAFETY: same as in `next`.
        let prev = unsafe { node.as_ref().prev }?;
        // `prev` is a node of the list (invariant 1), so the cursor invariant
        // still holds.
        self.current = Some(prev);
        self.peek_mut()
    }

    /// Remove and return the element at the current position and move the cursor
    /// to the neighboring element that's closest to the back. This can be
    /// either the next or previous position.
    pub fn take(&mut self) -> Option<T> {
        let node = self.current?;
        // SAFETY: `node` is a node of `self.list` (cursor invariant). The
        // cursor's own pointer to it is replaced right below and not used in
        // between, so no pointer to the node is dereferenced afterwards.
        let node = unsafe { self.list.unlink(node) };
        // The former neighbours of the node are still part of the list. Move to
        // the one that's closest to the back: the next one or, if there is none,
        // the previous one. If there is neither, the list is empty now and
        // `current` is `None`, as the cursor invariant demands.
        self.current = node.next.or(node.prev);
        Some(node.element)
    }

    /// Insert `element` after the current position. The cursor stays on the
    /// current element. If the list is empty, the new element becomes its only
    /// element and the cursor is placed on it.
    pub fn insert_after(&mut self, element: T) {
        let (prev, next) = match self.current {
            // SAFETY: `node` is a node of the list (cursor invariant), so it is
            // valid to read it.
            Some(node) => (Some(node), unsafe { node.as_ref().next }),
            // The list is empty.
            None => (None, None),
        };
        // SAFETY: `prev` and `next` are neighbours. Either they are the current
        // node and the node behind it (`None` if the current node is the back,
        // list invariant 3), or the list is empty (cursor invariant) and both
        // are `None`.
        let node = unsafe { self.list.link(prev, next, element) };
        if self.current.is_none() {
            // The list was empty, so the new node is the only one.
            self.current = Some(node);
        }
    }

    /// Insert `element` before the current position. The cursor stays on the
    /// current element. If the list is empty, the new element becomes its only
    /// element and the cursor is placed on it.
    pub fn insert_before(&mut self, element: T) {
        let (prev, next) = match self.current {
            // SAFETY: `node` is a node of the list (cursor invariant), so it is
            // valid to read it.
            Some(node) => (unsafe { node.as_ref().prev }, Some(node)),
            // The list is empty.
            None => (None, None),
        };
        // SAFETY: `prev` and `next` are neighbours. Either they are the node in
        // front of the current node (`None` if the current node is the front,
        // list invariant 3) and the current node, or the list is empty (cursor
        // invariant) and both are `None`.
        let node = unsafe { self.list.link(prev, next, element) };
        if self.current.is_none() {
            // The list was empty, so the new node is the only one.
            self.current = Some(node);
        }
    }
}

impl<'a, T> Iterator for Iter<'a, T> {
    type Item = &'a T;

    fn next(&mut self) -> Option<&'a T> {
        let node = self.next_node?;
        // SAFETY: `node` is a node of a list that is borrowed (shared) for `'a`
        // (struct invariant), so it is valid and can't be mutated or freed
        // during `'a`. That makes it fine to hand out shared references to it.
        let node = unsafe { node.as_ref() };
        self.next_node = node.next;
        Some(&node.element)
    }
}

impl<T> Drop for LinkedList<T> {
    fn drop(&mut self) {
        // Free the nodes one by one, dropping their elements. Looping (rather
        // than recursing) makes sure that dropping a very long list can't
        // overflow the stack.
        while self.cursor_front().take().is_some() {}
    }
}
