I'll implement a doubly linked list with raw pointers (using `NonNull`), a cursor that can sit on an element, and an iterator. The cursor tracks the current node plus the list pointer, so it can operate on empty lists.

Design notes:
- `LinkedList` holds `front`, `back`, `len`, and a `PhantomData<Box<Node<T>>>` marker for covariance and drop-check ownership.
- `Cursor` holds `&mut LinkedList<T>` and `current: Option<NonNull<Node<T>>>`.
- `take` removes the current node and moves to the next (closer to back), else the previous.
- `insert_after`/`insert_before` on an empty list make the new node the sole element and current.
- `Send`/`Sync` are implemented manually.

src/lib.rs
```rust
// this module adds some functionality based on the required implementations
// here like: `LinkedList::pop_back` or `Clone for LinkedList<T>`
// You are free to use anything in it, but it's mainly for the test framework.
mod pre_implemented;

use std::marker::PhantomData;
use std::ptr::NonNull;

struct Node<T> {
    element: T,
    prev: Option<NonNull<Node<T>>>,
    next: Option<NonNull<Node<T>>>,
}

/// Invariants:
/// - `front` and `back` are either both `None` (empty list) or both `Some`,
///   pointing to valid, uniquely owned heap-allocated nodes.
/// - Every node reachable from `front` via `next` is valid, and `prev`/`next`
///   links are mutually consistent.
/// - `len` equals the number of nodes in the chain.
/// - Every node was allocated with `Box` and is owned by the list.
pub struct LinkedList<T> {
    front: Option<NonNull<Node<T>>>,
    back: Option<NonNull<Node<T>>>,
    len: usize,
    // Signals ownership of `Box<Node<T>>` (covariant in T, drop-check aware).
    _marker: PhantomData<Box<Node<T>>>,
}

pub struct Cursor<'a, T> {
    list: &'a mut LinkedList<T>,
    // Invariant: if `Some`, points to a valid node currently in `list`.
    // If the list is non-empty, this is always `Some`.
    current: Option<NonNull<Node<T>>>,
}

pub struct Iter<'a, T> {
    next: Option<NonNull<Node<T>>>,
    _marker: PhantomData<&'a T>,
}

// SAFETY: The list owns its nodes exclusively, just like `Vec<T>`/`Box<T>`,
// so it is safe to send if `T` is Send.
unsafe impl<T: Send> Send for LinkedList<T> {}
// SAFETY: Shared access to the list only gives shared access to `T`.
unsafe impl<T: Sync> Sync for LinkedList<T> {}

// SAFETY: Cursor is equivalent to `&mut LinkedList<T>`.
unsafe impl<T: Send> Send for Cursor<'_, T> {}
unsafe impl<T: Sync> Sync for Cursor<'_, T> {}

// SAFETY: Iter is equivalent to `&T` references.
unsafe impl<T: Sync> Send for Iter<'_, T> {}
unsafe impl<T: Sync> Sync for Iter<'_, T> {}

impl<T> LinkedList<T> {
    pub fn new() -> Self {
        LinkedList {
            front: None,
            back: None,
            len: 0,
            _marker: PhantomData,
        }
    }

    // You may be wondering why it's necessary to have is_empty()
    // when it can easily be determined from len().
    // It's good custom to have both because len() can be expensive for some types,
    // whereas is_empty() is almost always cheap.
    // (Also ask yourself whether len() is expensive for LinkedList)
    pub fn is_empty(&self) -> bool {
        self.len == 0
    }

    pub fn len(&self) -> usize {
        self.len
    }

    /// Return a cursor positioned on the front element
    pub fn cursor_front(&mut self) -> Cursor<'_, T> {
        let current = self.front;
        Cursor {
            list: self,
            current,
        }
    }

    /// Return a cursor positioned on the back element
    pub fn cursor_back(&mut self) -> Cursor<'_, T> {
        let current = self.back;
        Cursor {
            list: self,
            current,
        }
    }

    /// Return an iterator that moves from front to back
    pub fn iter(&self) -> Iter<'_, T> {
        Iter {
            next: self.front,
            _marker: PhantomData,
        }
    }
}

impl<T> Default for LinkedList<T> {
    fn default() -> Self {
        Self::new()
    }
}

impl<T> Drop for LinkedList<T> {
    fn drop(&mut self) {
        let mut cur = self.front.take();
        self.back = None;
        self.len = 0;
        while let Some(ptr) = cur {
            // SAFETY: every node was created via `Box::new` and leaked into a
            // `NonNull`; we own it exclusively and each node is visited once.
            let node = unsafe { Box::from_raw(ptr.as_ptr()) };
            cur = node.next;
            // `node` dropped here, dropping the element.
        }
    }
}

// the cursor is expected to act as if it is at the position of an element
// and it also has to work with and be able to insert into an empty list.
impl<T> Cursor<'_, T> {
    /// Take a mutable reference to the current element
    pub fn peek_mut(&mut self) -> Option<&mut T> {
        // SAFETY: `current` points to a valid node in the list, and we hold
        // `&mut self` which holds `&mut LinkedList`, so access is unique.
        self.current
            .map(|ptr| unsafe { &mut (*ptr.as_ptr()).element })
    }

    /// Move one position forward (towards the back) and
    /// return a reference to the new position
    #[allow(clippy::should_implement_trait)]
    pub fn next(&mut self) -> Option<&mut T> {
        let cur = self.current?;
        // SAFETY: `cur` is a valid node in the list.
        let next = unsafe { (*cur.as_ptr()).next }?;
        self.current = Some(next);
        // SAFETY: `next` is a valid node; access is unique via `&mut self`.
        Some(unsafe { &mut (*next.as_ptr()).element })
    }

    /// Move one position backward (towards the front) and
    /// return a reference to the new position
    pub fn prev(&mut self) -> Option<&mut T> {
        let cur = self.current?;
        // SAFETY: `cur` is a valid node in the list.
        let prev = unsafe { (*cur.as_ptr()).prev }?;
        self.current = Some(prev);
        // SAFETY: `prev` is a valid node; access is unique via `&mut self`.
        Some(unsafe { &mut (*prev.as_ptr()).element })
    }

    /// Remove and return the element at the current position and move the cursor
    /// to the neighboring element that's closest to the back. This can be
    /// either the next or previous position.
    pub fn take(&mut self) -> Option<T> {
        let cur = self.current?;
        // SAFETY: `cur` was allocated via Box and is owned by the list; after
        // unlinking it below nobody else references it.
        let node = unsafe { Box::from_raw(cur.as_ptr()) };
        let prev = node.prev;
        let next = node.next;

        match prev {
            // SAFETY: `p` is a valid node in the list.
            Some(p) => unsafe { (*p.as_ptr()).next = next },
            None => self.list.front = next,
        }
        match next {
            // SAFETY: `n` is a valid node in the list.
            Some(n) => unsafe { (*n.as_ptr()).prev = prev },
            None => self.list.back = prev,
        }
        self.list.len -= 1;
        self.current = next.or(prev);

        Some(node.element)
    }

    pub fn insert_after(&mut self, element: T) {
        let new = Box::new(Node {
            element,
            prev: None,
            next: None,
        });
        // SAFETY: Box::into_raw never returns null.
        let new = unsafe { NonNull::new_unchecked(Box::into_raw(new)) };

        match self.current {
            None => {
                // Empty list.
                self.list.front = Some(new);
                self.list.back = Some(new);
                self.current = Some(new);
            }
            Some(cur) => {
                // SAFETY: `cur` and `next` (if any) are valid nodes in the
                // list; `new` is a fresh unique node.
                unsafe {
                    let next = (*cur.as_ptr()).next;
                    (*new.as_ptr()).prev = Some(cur);
                    (*new.as_ptr()).next = next;
                    (*cur.as_ptr()).next = Some(new);
                    match next {
                        Some(n) => (*n.as_ptr()).prev = Some(new),
                        None => self.list.back = Some(new),
                    }
                }
            }
        }
        self.list.len += 1;
    }

    pub fn insert_before(&mut self, element: T) {
        let new = Box::new(Node {
            element,
            prev: None,
            next: None,
        });
        // SAFETY: Box::into_raw never returns null.
        let new = unsafe { NonNull::new_unchecked(Box::into_raw(new)) };

        match self.current {
            None => {
                self.list.front = Some(new);
                self.list.back = Some(new);
                self.current = Some(new);
            }
            Some(cur) => {
                // SAFETY: `cur` and `prev` (if any) are valid nodes in the
                // list; `new` is a fresh unique node.
                unsafe {
                    let prev = (*cur.as_ptr()).prev;
                    (*new.as_ptr()).next = Some(cur);
                    (*new.as_ptr()).prev = prev;
                    (*cur.as_ptr()).prev = Some(new);
                    match prev {
                        Some(p) => (*p.as_ptr()).next = Some(new),
                        None => self.list.front = Some(new),
                    }
                }
            }
        }
        self.list.len += 1;
    }
}

impl<'a, T> Iterator for Iter<'a, T> {
    type Item = &'a T;

    fn next(&mut self) -> Option<&'a T> {
        let cur = self.next?;
        // SAFETY: the iterator borrows the list immutably for 'a, so all
        // nodes stay valid and unmodified for 'a.
        let node = unsafe { &*cur.as_ptr() };
        self.next = node.next;
        Some(&node.element)
    }
}
