// this module adds some functionality based on the required implementations
// here like: `LinkedList::pop_back` or `Clone for LinkedList<T>`
// You are free to use anything in it, but it's mainly for the test framework.
mod pre_implemented;

use std::marker::PhantomData;
use std::ptr::NonNull;

// # Safety-critical invariants
//
// 1. Every `NonNull<Node<T>>` reachable from a `LinkedList<T>` (through `front`, `back`, or any
//    node's `prev`/`next`) points to a live node that was allocated with `Box` and is owned
//    exclusively by that list.
// 2. For every node `n`: `n.next == Some(m)` if and only if `m.prev == Some(n)`.
// 3. `front` is `None` iff `back` is `None` iff the list is empty iff `len == 0`.
//    `front` has no `prev`, and `back` has no `next`.
// 4. A `Cursor` holds a `&mut LinkedList<T>`, so while it exists nothing else can access the list.
//    Its `current` pointer is `None` iff the list is empty, otherwise it points to a node of that
//    list.
// 5. An `Iter` holds a shared borrow of the list (through its lifetime), so no node can be
//    modified or freed while it exists.

struct Node<T> {
    element: T,
    prev: Option<NonNull<Node<T>>>,
    next: Option<NonNull<Node<T>>>,
}

pub struct LinkedList<T> {
    front: Option<NonNull<Node<T>>>,
    back: Option<NonNull<Node<T>>>,
    len: usize,
    // Signals that we logically own boxed nodes (drop check) and keeps us covariant over `T`.
    _marker: PhantomData<Box<Node<T>>>,
}

pub struct Cursor<'a, T> {
    list: &'a mut LinkedList<T>,
    current: Option<NonNull<Node<T>>>,
}

pub struct Iter<'a, T> {
    next: Option<NonNull<Node<T>>>,
    _marker: PhantomData<&'a T>,
}

// SAFETY: A `LinkedList<T>` uniquely owns all of its `T`s (just like `Vec<T>`), and no
// thread-affine state is shared between lists. Sending the list sends the `T`s.
unsafe impl<T: Send> Send for LinkedList<T> {}
// SAFETY: Shared access to a `LinkedList<T>` only gives out `&T`, so it's sound
// exactly when `&T` can be shared between threads.
unsafe impl<T: Sync> Sync for LinkedList<T> {}

// SAFETY: A `Cursor` is semantically a `&mut LinkedList<T>`.
unsafe impl<T: Send> Send for Cursor<'_, T> {}
// SAFETY: A `Cursor` is semantically a `&mut LinkedList<T>`; a shared reference to it
// gives no more capabilities than a shared reference to the list.
unsafe impl<T: Sync> Sync for Cursor<'_, T> {}

// SAFETY: An `Iter` is semantically a `&'a [T]`-like shared reference to the elements.
unsafe impl<T: Sync> Send for Iter<'_, T> {}
// SAFETY: Same as above.
unsafe impl<T: Sync> Sync for Iter<'_, T> {}

impl<T> LinkedList<T> {
    pub fn new() -> Self {
        LinkedList {
            front: None,
            back: None,
            len: 0,
            _marker: PhantomData,
        }
    }

    // You may be wondering why it's necessary to have is_empty()
    // when it can easily be determined from len().
    // It's good custom to have both because len() can be expensive for some types,
    // whereas is_empty() is almost always cheap.
    // (Also ask yourself whether len() is expensive for LinkedList)
    pub fn is_empty(&self) -> bool {
        self.len == 0
    }

    pub fn len(&self) -> usize {
        self.len
    }

    /// Return a cursor positioned on the front element
    pub fn cursor_front(&mut self) -> Cursor<'_, T> {
        let current = self.front;
        Cursor {
            list: self,
            current,
        }
    }

    /// Return a cursor positioned on the back element
    pub fn cursor_back(&mut self) -> Cursor<'_, T> {
        let current = self.back;
        Cursor {
            list: self,
            current,
        }
    }

    /// Return an iterator that moves from front to back
    pub fn iter(&self) -> Iter<'_, T> {
        Iter {
            next: self.front,
            _marker: PhantomData,
        }
    }
}

impl<T> Drop for LinkedList<T> {
    fn drop(&mut self) {
        // Removing every element through the cursor frees each node exactly once and keeps the
        // list consistent at every step (even if an element's destructor panics).
        let mut cursor = self.cursor_front();
        while cursor.take().is_some() {}
    }
}

impl<T> Cursor<'_, T> {
    /// Allocate a new node on the heap and return a pointer to it.
    /// The returned pointer is owned by the caller, who must link it into the list
    /// (or eventually free it with `Box::from_raw`).
    fn alloc_node(
        element: T,
        prev: Option<NonNull<Node<T>>>,
        next: Option<NonNull<Node<T>>>,
    ) -> NonNull<Node<T>> {
        let boxed = Box::new(Node {
            element,
            prev,
            next,
        });
        NonNull::from(Box::leak(boxed))
    }

    /// Insert the first element into an empty list and put the cursor on it.
    fn insert_into_empty(&mut self, element: T) {
        debug_assert!(self.list.front.is_none() && self.list.back.is_none());
        debug_assert!(self.current.is_none());
        let node = Self::alloc_node(element, None, None);
        self.list.front = Some(node);
        self.list.back = Some(node);
        self.list.len = 1;
        self.current = Some(node);
    }
}

// the cursor is expected to act as if it is at the position of an element
// and it also has to work with and be able to insert into an empty list.
impl<T> Cursor<'_, T> {
    /// Take a mutable reference to the current element
    pub fn peek_mut(&mut self) -> Option<&mut T> {
        let mut node = self.current?;
        // SAFETY: By invariant 4, `current` points to a live node of the list, and since we
        // have `&mut self` (which in turn holds `&mut LinkedList`), no other reference to
        // this node exists. The returned reference borrows from `self`.
        Some(unsafe { &mut node.as_mut().element })
    }

    /// Move one position forward (towards the back) and
    /// return a reference to the new position
    #[allow(clippy::should_implement_trait)]
    pub fn next(&mut self) -> Option<&mut T> {
        let current = self.current?;
        // SAFETY: By invariant 4, `current` points to a live node. We only read its `next`
        // field, which is a `Copy` value.
        let next = unsafe { current.as_ref().next }?;
        // `next` is a live node of the list by invariants 1 and 2.
        self.current = Some(next);
        self.peek_mut()
    }

    /// Move one position backward (towards the front) and
    /// return a reference to the new position
    pub fn prev(&mut self) -> Option<&mut T> {
        let current = self.current?;
        // SAFETY: By invariant 4, `current` points to a live node. We only read its `prev`
        // field, which is a `Copy` value.
        let prev = unsafe { current.as_ref().prev }?;
        // `prev` is a live node of the list by invariants 1 and 2.
        self.current = Some(prev);
        self.peek_mut()
    }

    /// Remove and return the element at the current position and move the cursor
    /// to the neighboring element that's closest to the back. This can be
    /// either the next or previous position.
    pub fn take(&mut self) -> Option<T> {
        let node = self.current?;
        // SAFETY: By invariants 1 and 4, `node` was created by `Box` and is live. After this
        // call we unlink it from the list so that no pointer to it remains, and we never touch
        // the raw pointer again.
        let boxed = unsafe { Box::from_raw(node.as_ptr()) };
        let Node {
            element,
            prev,
            next,
        } = *boxed;

        match prev {
            // SAFETY: `p` is a live node of the list (invariants 1 and 2), distinct from the
            // removed node, and we have exclusive access to the list.
            Some(mut p) => unsafe { p.as_mut().next = next },
            None => self.list.front = next,
        }
        match next {
            // SAFETY: Same as above for `n`.
            Some(mut n) => unsafe { n.as_mut().prev = prev },
            None => self.list.back = prev,
        }
        self.list.len -= 1;

        // Prefer the neighbor closest to the back.
        self.current = next.or(prev);
        Some(element)
    }

    pub fn insert_after(&mut self, element: T) {
        let mut current = match self.current {
            Some(current) => current,
            None => {
                self.insert_into_empty(element);
                return;
            }
        };

        // SAFETY: By invariant 4, `current` points to a live node. We only read `next`.
        let next = unsafe { current.as_ref().next };
        let new = Self::alloc_node(element, Some(current), next);

        // SAFETY: `current` is live and we have exclusive access to the list. We only write
        // the `next` field, restoring invariant 2 together with the update below.
        unsafe { current.as_mut().next = Some(new) };
        match next {
            // SAFETY: `n` is a live node of the list (invariants 1 and 2) and we have
            // exclusive access to the list.
            Some(mut n) => unsafe { n.as_mut().prev = Some(new) },
            None => self.list.back = Some(new),
        }
        self.list.len += 1;
    }

    pub fn insert_before(&mut self, element: T) {
        let mut current = match self.current {
            Some(current) => current,
            None => {
                self.insert_into_empty(element);
                return;
            }
        };

        // SAFETY: By invariant 4, `current` points to a live node. We only read `prev`.
        let prev = unsafe { current.as_ref().prev };
        let new = Self::alloc_node(element, prev, Some(current));

        // SAFETY: `current` is live and we have exclusive access to the list. We only write
        // the `prev` field, restoring invariant 2 together with the update below.
        unsafe { current.as_mut().prev = Some(new) };
        match prev {
            // SAFETY: `p` is a live node of the list (invariants 1 and 2) and we have
            // exclusive access to the list.
            Some(mut p) => unsafe { p.as_mut().next = Some(new) },
            None => self.list.front = Some(new),
        }
        self.list.len += 1;
    }
}

impl<'a, T> Iterator for Iter<'a, T> {
    type Item = &'a T;

    fn next(&mut self) -> Option<&'a T> {
        let node = self.next?;
        // SAFETY: By invariant 5, the list is borrowed for `'a` and cannot be modified, so the
        // node is live and not mutably aliased for all of `'a`.
        let node: &'a Node<T> = unsafe { &*node.as_ptr() };
        self.next = node.next;
        Some(&node.element)
    }
}
```

I've implemented the list with raw `NonNull` pointers, which keeps it covariant over `T`. All modification goes through the cursor.

**Design notes**
- Nodes are heap-allocated with `Box` and tracked via `NonNull<Node<T>>`. The list stores `front`, `back` and `len`.
- `Cursor` holds `&mut LinkedList<T>` plus an optional current node. When the list is empty, the cursor has no current node, and `insert_*` sets the first element.
- `take` removes the current node and moves to the next node. If there is no next node, it moves to the previous one. Otherwise the cursor becomes empty.
- `next` and `prev` return `None` and leave the cursor unchanged when they would move off the end. This matches the usual semantics of this exercise's tests.
- `Drop` pops all nodes via the cursor.
- `Send` and `Sync` are implemented manually for `LinkedList`, `Cursor` and `Iter`.

I've assumed `pre_implemented` only uses the public API (`cursor_front`, `cursor_back`, `insert_*`, `take`, `iter`, `len`, etc.).

