// the cursor is expected to act as if it is at the position of an element
// and it also has to work with and be able to insert into an empty list.
impl<T> Cursor<'_, T> {
    /// Take a mutable reference to the current element
    pub fn peek_mut(&mut self) -> Option<&mut T> {
        // SAFETY: current points to a valid node owned by the list, which we
        // borrow mutably for the lifetime of the returned reference.
        self.current.map(|p| unsafe { &mut (*p.as_ptr()).element })
    }

    /// Move one position forward (towards the back) and
    /// return a reference to the new position
    #[allow(clippy::should_implement_trait)]
    pub fn next(&mut self) -> Option<&mut T> {
        // SAFETY: current is a valid node.
        let next = unsafe { (*self.current?.as_ptr()).next }?;
        self.current = Some(next);
        self.peek_mut()
    }

    /// Move one position backward (towards the front) and
    /// return a reference to the new position
    pub fn prev(&mut self) -> Option<&mut T> {
        // SAFETY: current is a valid node.
        let prev = unsafe { (*self.current?.as_ptr()).prev }?;
        self.current = Some(prev);
        self.peek_mut()
    }

    /// Remove and return the element at the current position and move the cursor
    /// to the neighboring element that's closest to the back. This can be
    /// either the next or previous position.
    pub fn take(&mut self) -> Option<T> {
        let ptr = self.current?;
        // SAFETY: ptr is a valid node created by Box::into_raw and owned by the list.
        // We unlink it fully before reclaiming the Box, so no dangling links remain.
        unsafe {
            let node = Box::from_raw(ptr.as_ptr());
            match node.prev {
                Some(p) => (*p.as_ptr()).next = node.next,
                None => self.list.front = node.next,
            }
            match node.next {
                Some(n) => (*n.as_ptr()).prev = node.prev,
                None => self.list.back = node.prev,
            }
            self.list.len -= 1;
            self.current = node.next.or(node.prev);
            Some(node.element)
        }
    }

    pub fn insert_after(&mut self, element: T) {
        let new = Box::new(Node {
            element,
            prev: self.current,
            next: None,
        });
        // SAFETY: Box::into_raw never returns null; current (if any) and its
        // neighbour are valid nodes of this list.
        unsafe {
            let new = NonNull::new_unchecked(Box::into_raw(new));
            match self.current {
                None => {
                    (*new.as_ptr()).prev = None;
                    self.list.front = Some(new);
                    self.list.back = Some(new);
                    self.current = Some(new);
                }
                Some(cur) => {
                    let next = (*cur.as_ptr()).next;
                    (*new.as_ptr()).next = next;
                    (*cur.as_ptr()).next = Some(new);
                    match next {
                        Some(n) => (*n.as_ptr()).prev = Some(new),
                        None => self.list.back = Some(new),
                    }
                }
            }
        }
        self.list.len += 1;
    }

    pub fn insert_before(&mut self, element: T) {
        let new = Box::new(Node {
            element,
            prev: None,
            next: self.current,
        });
        // SAFETY: same as insert_after.
        unsafe {
            let new = NonNull::new_unchecked(Box::into_raw(new));
            match self.current {
                None => {
                    (*new.as_ptr()).next = None;
                    self.list.front = Some(new);
                    self.list.back = Some(new);
                    self.current = Some(new);
                }
                Some(cur) => {
                    let prev = (*cur.as_ptr()).prev;
                    (*new.as_ptr()).prev = prev;
                    (*cur.as_ptr()).prev = Some(new);
                    match prev {
                        Some(p) => (*p.as_ptr()).next = Some(new),
                        None => self.list.front = Some(new),
                    }
                }
            }
        }
        self.list.len += 1;
    }
}

impl<'a, T> Iterator for Iter<'a, T> {
    type Item = &'a T;

    fn next(&mut self) -> Option<&'a T> {
        let ptr = self.next?;
        // SAFETY: the iterator borrows the list immutably for 'a, so the node
        // stays valid and unmodified for 'a.
        unsafe {
            let node = &*ptr.as_ptr();
            self.next = node.next;
            Some(&node.element)
        }
    }
}
