#[derive(Debug)]
pub struct Error;

pub struct Scale {
    notes: Vec<String>,
}

const SHARPS: [&str; 12] = [
    "A", "A#", "B", "C", "C#", "D", "D#", "E", "F", "F#", "G", "G#",
];
const FLATS: [&str; 12] = [
    "A", "Bb", "B", "C", "Db", "D", "Eb", "E", "F", "Gb", "G", "Ab",
];

fn locate(tonic: &str) -> Result<(usize, bool), Error> {
    let mut chars = tonic.chars();
    let first = chars.next().ok_or(Error)?;
    let rest: String = chars.collect();
    if !first.is_ascii_alphabetic() {
        return Err(Error);
    }
    let minor = first.is_ascii_lowercase();
    let name = format!("{}{}", first.to_ascii_uppercase(), rest);
    let use_flats = if minor {
        matches!(
            name.as_str(),
            "D" | "G" | "C" | "F" | "Bb" | "Eb"
        )
    } else {
        matches!(name.as_str(), "F" | "Bb" | "Eb" | "Ab" | "Db" | "Gb")
    };
    let table = if use_flats { &FLATS } else { &SHARPS };
    let idx = table
        .iter()
        .position(|n| *n == name)
        .or_else(|| SHARPS.iter().position(|n| *n == name))
        .or_else(|| FLATS.iter().position(|n| *n == name))
        .ok_or(Error)?;
    Ok((idx, use_flats))
}

impl Scale {
    pub fn new(tonic: &str, intervals: &str) -> Result<Scale, Error> {
        let (mut idx, flats) = locate(tonic)?;
        let table = if flats { &FLATS } else { &SHARPS };
        let mut notes = vec![table[idx].to_string()];
        for c in intervals.chars() {
            let step = match c {
                'm' => 1,
                'M' => 2,
                'A' => 3,
                _ => return Err(Error),
            };
            idx = (idx + step) % 12;
            notes.push(table[idx].to_string());
        }
        // The final note returns to the tonic; drop it to keep one octave.
        if !intervals.is_empty() {
            notes.pop();
        }
        Ok(Scale { notes })
    }

    pub fn chromatic(tonic: &str) -> Result<Scale, Error> {
        Scale::new(tonic, "mmmmmmmmmmmm")
    }

    pub fn enumerate(&self) -> Vec<String> {
        self.notes.clone()
    }
}
