//! Generate musical scales from a tonic and a pattern of intervals.
//!
//! Scales are built on top of the twelve-note chromatic scale. Depending on
//! the tonic, the notes are spelled either with sharps or with flats.

use std::fmt;

/// The chromatic scale spelled with sharps.
const SHARPS: [&str; 12] = [
    "A", "A#", "B", "C", "C#", "D", "D#", "E", "F", "F#", "G", "G#",
];

/// The chromatic scale spelled with flats.
const FLATS: [&str; 12] = [
    "A", "Bb", "B", "C", "Db", "D", "Eb", "E", "F", "Gb", "G", "Ab",
];

/// Everything that can go wrong while building a [`Scale`].
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Error {
    /// The tonic is not a note of the chromatic scale (e.g. `"H"` or `""`).
    InvalidTonic(String),
    /// The interval pattern contains a character other than `m`, `M` or `A`.
    InvalidInterval(char),
}

impl fmt::Display for Error {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Error::InvalidTonic(tonic) => write!(f, "invalid tonic: {:?}", tonic),
            Error::InvalidInterval(interval) => write!(
                f,
                "invalid interval: {:?} (expected 'm', 'M' or 'A')",
                interval
            ),
        }
    }
}

impl std::error::Error for Error {}

/// A musical scale: an ordered list of notes starting at the tonic.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Scale {
    notes: Vec<&'static str>,
}

impl Scale {
    /// Builds a scale starting at `tonic` and following the `intervals`
    /// pattern, where `m` is a half step, `M` a whole step and `A` an
    /// augmented second (a whole step plus a half step).
    ///
    /// An upper-case tonic denotes a major key and a lower-case tonic a
    /// minor key; this decides whether sharps or flats are used.
    pub fn new(tonic: &str, intervals: &str) -> Result<Scale, Error> {
        let names = note_names(tonic);
        let mut position = tonic_position(tonic, names)?;

        let mut notes = Vec::with_capacity(intervals.len());
        for interval in intervals.chars() {
            notes.push(names[position]);
            position = (position + semitones(interval)?) % names.len();
        }

        Ok(Scale { notes })
    }

    /// Builds the twelve-note chromatic scale starting at `tonic`.
    pub fn chromatic(tonic: &str) -> Result<Scale, Error> {
        Scale::new(tonic, "mmmmmmmmmmmm")
    }

    /// Returns the notes of the scale, starting with the tonic.
    pub fn enumerate(&self) -> Vec<String> {
        self.notes.iter().map(|&note| note.to_string()).collect()
    }
}

/// Chooses between the sharp and the flat spelling for the given tonic.
fn note_names(tonic: &str) -> &'static [&'static str; 12] {
    if uses_flats(tonic) {
        &FLATS
    } else {
        &SHARPS
    }
}

/// Decides whether a scale starting on `tonic` is spelled with flats.
///
/// Flats are used for:
///   * major: F, Bb, Eb, Ab, Db, Gb
///   * minor: d, g, c, f, bb, eb
///
/// Everything else (including C major and a minor, which have no accidentals
/// of their own) is spelled with sharps.
fn uses_flats(tonic: &str) -> bool {
    match tonic.chars().nth(1) {
        // An explicit accidental in the tonic dictates the spelling.
        Some('b') => true,
        Some('#') => false,
        // Natural tonics: only F major and d, g, c, f minor use flats.
        _ => matches!(tonic, "F" | "d" | "g" | "c" | "f"),
    }
}

/// Finds the index of the tonic within the chosen set of note names.
fn tonic_position(tonic: &str, names: &[&str]) -> Result<usize, Error> {
    // Minor tonics are written in lower case, note names are capitalised.
    let note = capitalize(tonic);

    names
        .iter()
        .position(|&name| name == note)
        .ok_or_else(|| Error::InvalidTonic(tonic.to_string()))
}

/// Upper-cases the first character of `s`, leaving the rest untouched.
fn capitalize(s: &str) -> String {
    let mut chars = s.chars();
    match chars.next() {
        Some(first) => first.to_ascii_uppercase().to_string() + chars.as_str(),
        None => String::new(),
    }
}

/// The number of semitones spanned by an interval.
fn semitones(interval: char) -> Result<usize, Error> {
    match interval {
        // Minor second / half step.
        'm' => Ok(1),
        // Major second / whole step.
        'M' => Ok(2),
        // Augmented second: a whole step plus a half step.
        'A' => Ok(3),
        other => Err(Error::InvalidInterval(other)),
    }
}
