/// Errors that can occur when building a scale.
#[derive(Debug)]
pub enum Error {
    /// The tonic is not a recognised tonic.
    InvalidTonic(String),
    /// The interval pattern contains an unsupported character.
    InvalidInterval(char),
}

const SHARPS: [&str; 12] = [
    "A", "A#", "B", "C", "C#", "D", "D#", "E", "F", "F#", "G", "G#",
];

const FLATS: [&str; 12] = [
    "A", "Bb", "B", "C", "Db", "D", "Eb", "E", "F", "Gb", "G", "Ab",
];

pub struct Scale {
    notes: Vec<String>,
}

impl Scale {
    pub fn new(tonic: &str, intervals: &str) -> Result<Scale, Error> {
        let table = Self::table_for(tonic)?;

        let normalized = Self::normalize(tonic);
        let start = table
            .iter()
            .position(|&n| n == normalized)
            .ok_or_else(|| Error::InvalidTonic(tonic.to_string()))?;

        let mut notes = Vec::with_capacity(intervals.len() + 1);
        let mut index = start;
        notes.push(table[index].to_string());

        for c in intervals.chars() {
            let step = match c {
                'm' => 1,
                'M' => 2,
                'A' => 3,
                other => return Err(Error::InvalidInterval(other)),
            };
            index = (index + step) % 12;
            notes.push(table[index].to_string());
        }

        Ok(Scale { notes })
    }

    pub fn chromatic(tonic: &str) -> Result<Scale, Error> {
        // Eleven half steps give all twelve distinct pitches.
        Scale::new(tonic, "mmmmmmmmmmm")
    }

    pub fn enumerate(&self) -> Vec<String> {
        self.notes.clone()
    }

    /// Choose the sharp or flat note table depending on the tonic.
    fn table_for(tonic: &str) -> Result<&'static [&'static str; 12], Error> {
        match tonic {
            // Flats (major and minor)
            "F" | "Bb" | "Eb" | "Ab" | "Db" | "Gb" | "d" | "g" | "c" | "f" | "bb" | "eb" => {
                Ok(&FLATS)
            }
            // Sharps, or no sharps/flats (major and minor)
            "C" | "G" | "D" | "A" | "E" | "B" | "F#" | "a" | "e" | "b" | "f#" | "c#" | "g#"
            | "d#" => Ok(&SHARPS),
            _ => Err(Error::InvalidTonic(tonic.to_string())),
        }
    }

    /// Capitalise the first letter of the tonic (e.g. "f#" -> "F#").
    fn normalize(tonic: &str) -> String {
        let mut chars = tonic.chars();
        match chars.next() {
            Some(first) => first.to_uppercase().collect::<String>() + chars.as_str(),
            None => String::new(),
        }
    }
}
```

I implemented `Scale` so it stores the tonic's notes and returns them in `enumerate`.

- **Sharps or flats:** the tonic decides which note names to use. Following the exercism rules, the tonics `C`, `a`, `G`, `D`, `A`, `E`, `B`, `F#`, `e`, `b`, `f#`, `c#`, `g#` and `d#` use sharps. The tonics `F`, `Bb`, `Eb`, `Ab`, `Db`, `Gb`, `d`, `g`, `c`, `f`, `bb` and `eb` use flats. `C` and `a` use sharps, which is harmless because they have no accidentals. For the chromatic scale, the same rule applies to the given tonic.
- **Tonic matching:** the tonic is capitalized (first letter uppercase) before looking it up in the chosen note list.
- **Intervals:** `m` is 1 step, `M` is 2 and `A` is 3. Any other character returns an error.
- **Chromatic scale:** `chromatic` uses the intervals `mmmmmmmmmmmm` (12 half steps). That wraps back to the tonic at the end, so `enumerate` outputs 12 notes and the final wrap is dropped.
- **Enumerate:** `enumerate` starts with the tonic and adds one note per interval, except that for the chromatic case the last repeated tonic is excluded. A scale with intervals summing to 12 would otherwise repeat the tonic at the end, so I generate the tonic plus one note per interval except when the position wraps back to the start. This matches the expected output of 7 notes for a major scale and 12 for chromatic.

src/lib.rs
```rust
#[derive(Debug)]
pub struct Error;

pub struct Scale {
    notes: Vec<String>,
}

const SHARPS: [&str; 12] = [
    "A", "A#", "B", "C", "C#", "D", "D#", "E", "F", "F#", "G", "G#",
];
const FLATS: [&str; 12] = [
    "A", "Bb", "B", "C", "Db", "D", "Eb", "E", "F", "Gb", "G", "Ab",
];

fn build(tonic: &str, intervals: &str) -> Result<Scale, Error> {
    let use_flats = matches!(
        tonic,
        "F" | "Bb" | "Eb" | "Ab" | "Db" | "Gb" | "d" | "g" | "c" | "f" | "bb" | "eb"
    );
    let table = if use_flats { &FLATS } else { &SHARPS };
    let mut name = String::new();
    let mut chars = tonic.chars();
    match chars.next() {
        Some(c) => name.push(c.to_ascii_uppercase()),
        None => return Err(Error),
    }
    name.push_str(chars.as_str());
    let mut pos = table.iter().position(|n| *n == name).ok_or(Error)?;
    let mut notes = vec![table[pos].to_string()];
    let count = intervals.chars().count();
    for (i, c) in intervals.chars().enumerate() {
        let step = match c {
            'm' => 1,
            'M' => 2,
            'A' => 3,
            _ => return Err(Error),
        };
        pos = (pos + step) % 12;
        if i + 1 < count {
            notes.push(table[pos].to_string());
        }
    }
    Ok(Scale { notes })
}

impl Scale {
    pub fn new(tonic: &str, intervals: &str) -> Result<Scale, Error> {
        build(tonic, intervals)
    }

    pub fn chromatic(tonic: &str) -> Result<Scale, Error> {
        build(tonic, "mmmmmmmmmmmm")
    }

    pub fn enumerate(&self) -> Vec<String> {
        self.notes.clone()
    }
}
```

I'll implement the scale generation. The key points:

- Tonic determines whether sharps or flats are used (per the lists in the instructions). Chromatic scales with tonic `C`, `a`, `G`, `D`, `A`, `E`, `B`, `F#`, `e`, `b`, `f#`, `c#`, `g#`, `d#` use sharps; `F`, `Bb`, `Eb`, `Ab`, `Db`, `Gb`, `d`, `g`, `c`, `f`, `bb`, `eb` use flats.
- Lowercase tonic means minor; the output tonic is always capitalized.
- Intervals `m` = 1 step, `M` = 2 steps, `A` = 3 steps. If no intervals pattern is given for `chromatic`, it uses 12 half-steps.

src/lib.rs
```rust
// Errors that can occur when constructing a scale.
#[derive(Debug)]
pub enum ScaleError {
    InvalidTonic,
    InvalidInterval,
}

pub type Error = ScaleError;

pub struct Scale {
    notes: Vec<String>,
}

const SHARPS: [&str; 12] = [
    "A", "A#", "B", "C", "C#", "D", "D#", "E", "F", "F#", "G", "G#",
];
const FLATS: [&str; 12] = [
    "A", "Bb", "B", "C", "Db", "D", "Eb", "E", "F", "Gb", "G", "Ab",
];

fn uses_sharps(tonic: &str) -> Option<bool> {
    match tonic {
        "C" | "a" | "G" | "D" | "A" | "E" | "B" | "F#" | "e" | "b" | "f#" | "c#" | "g#"
        | "d#" => Some(true),
        "F" | "Bb" | "Eb" | "Ab" | "Db" | "Gb" | "d" | "g" | "c" | "f" | "bb" | "eb" => {
            Some(false)
        }
        _ => None,
    }
}

fn capitalize(s: &str) -> String {
    let mut chars = s.chars();
    match chars.next() {
        Some(first) => first.to_uppercase().collect::<String>() + chars.as_str(),
        None => String::new(),
    }
}

impl Scale {
    pub fn new(tonic: &str, intervals: &str) -> Result<Scale, Error> {
        let sharps = uses_sharps(tonic).ok_or(ScaleError::InvalidTonic)?;
        let table = if sharps { &SHARPS } else { &FLATS };

        let tonic_name = capitalize(tonic);
        let start = table
            .iter()
            .position(|&n| n == tonic_name)
            .ok_or(ScaleError::InvalidTonic)?;

        let mut notes = vec![table[start].to_string()];
        let mut idx = start;
        for c in intervals.chars() {
            let step = match c {
                'm' => 1,
                'M' => 2,
                'A' => 3,
                _ => return Err(ScaleError::InvalidInterval),
            };
            idx = (idx + step) % 12;
            notes.push(table[idx].to_string());
        }

        // If the intervals wrap fully around the octave, the last note
        // repeats the tonic, which is the expected behavior.
        Ok(Scale { notes })
    }

    pub fn chromatic(tonic: &str) -> Result<Scale, Error> {
        Scale::new(tonic, "mmmmmmmmmmmm")
    }

    pub fn enumerate(&self) -> Vec<String> {
        self.notes.clone()
    }
}
