OPERATIONS = {
    "plus": lambda a, b: a + b,
    "minus": lambda a, b: a - b,
    "multiplied": lambda a, b: a * b,
    "divided": lambda a, b: _divide(a, b),
}


def _divide(a, b):
    if b == 0:
        raise ValueError("division by zero")
    return a // b


def _parse_number(token):
    try:
        return int(token)
    except ValueError:
        return None


def answer(question):
    text = question.strip()
    if text.endswith("?"):
        text = text[:-1]

    text = text.replace("multiplied by", "multiplied")
    text = text.replace("divided by", "divided")

    tokens = text.split()

    if tokens[:2] != ["What", "is"]:
        raise ValueError("unknown operation")

    tokens = tokens[2:]

    if not tokens:
        raise ValueError("syntax error")

    result = _parse_number(tokens[0])
    if result is None:
        if tokens[0] in OPERATIONS:
            raise ValueError("syntax error")
        raise ValueError("unknown operation")

    index = 1
    while index < len(tokens):
        operator = tokens[index]

        if operator not in OPERATIONS:
            if _parse_number(operator) is not None:
                raise ValueError("syntax error")
            raise ValueError("unknown operation")

        index += 1
        if index >= len(tokens):
            raise ValueError("syntax error")

        operand = _parse_number(tokens[index])
        if operand is None:
            raise ValueError("syntax error")

        result = OPERATIONS[operator](result, operand)
        index += 1

    return result
