I've implemented the three functions in `beer_song.go`.

- `Verse(n)` returns one verse for `n` in 0..99, and an error otherwise. It handles the special cases for 2, 1 and 0 bottles.
- `Verses(start, stop)` returns verses from `start` down to `stop`, each followed by a blank line. It returns an error if either number is out of range or if `start < stop`.
- `Song()` is `Verses(99, 0)`.

beer_song.go
```
package beer

import (
	"errors"
	"fmt"
	"strings"
)

// bottles returns the phrase describing the given number of bottles.
func bottles(n int) string {
	switch n {
	case 0:
		return "no more bottles"
	case 1:
		return "1 bottle"
	default:
		return fmt.Sprintf("%d bottles", n)
	}
}

// Song returns the complete lyrics of the song.
func Song() string {
	s, _ := Verses(99, 0)
	return s
}

// Verses returns the verses from start down to stop, inclusive,
// separated by blank lines.
func Verses(start, stop int) (string, error) {
	if start < stop {
		return "", errors.New("start must be greater than or equal to stop")
	}
	if start > 99 || start < 0 || stop > 99 || stop < 0 {
		return "", errors.New("verse numbers must be between 0 and 99")
	}
	var sb strings.Builder
	for i := start; i >= stop; i-- {
		v, err := Verse(i)
		if err != nil {
			return "", err
		}
		sb.WriteString(v)
		sb.WriteString("\n")
	}
	return sb.String(), nil
}

// Verse returns a single verse of the song.
func Verse(n int) (string, error) {
	if n < 0 || n > 99 {
		return "", fmt.Errorf("verse number %d out of range (0-99)", n)
	}
	switch n {
	case 0:
		return "No more bottles of beer on the wall, no more bottles of beer.\n" +
			"Go to the store and buy some more, 99 bottles of beer on the wall.\n", nil
	case 1:
		return "1 bottle of beer on the wall, 1 bottle of beer.\n" +
			"Take it down and pass it around, no more bottles of beer on the wall.\n", nil
	default:
		return fmt.Sprintf("%s of beer on the wall, %s of beer.\n"+
			"Take one down and pass it around, %s of beer on the wall.\n",
			bottles(n), bottles(n), bottles(n-1)), nil
	}
}
```

I implemented all three functions in `beer_song.go`:

- **`Verse(n)`** returns an error unless `n` is between 0 and 99. Otherwise it builds the verse from small helpers that handle the special cases (1 bottle, "no more" bottles, "Take it down", and "Go to the store" for verse 0).
- **`Verses(start, stop)`** returns an error if either number is out of range or `start < stop`. Otherwise it joins the verses from `start` down to `stop`. Every verse ends with `\n`, so joining with `"\n"` gives a blank line between verses and a single trailing newline.
- **`Song()`** is the same join over 99 down to 0. It uses the unvalidated internal helper, so there is no error to handle.

beer_song.go
```
package beer

import (
	"fmt"
	"strings"
)

const (
	maxBottles = 99
	minBottles = 0
)

// Song returns the lyrics of the entire song, from the verse with 99 bottles
// down to the verse with no more bottles.
func Song() string {
	return versesText(maxBottles, minBottles)
}

// Verses returns the verses from start down to stop (both inclusive), with a
// blank line between consecutive verses. Both numbers must be between 0 and
// 99, and start must not be lower than stop.
func Verses(start, stop int) (string, error) {
	if err := checkVerseNumber(start); err != nil {
		return "", err
	}
	if err := checkVerseNumber(stop); err != nil {
		return "", err
	}
	if start < stop {
		return "", fmt.Errorf("start verse (%d) must not be lower than stop verse (%d)", start, stop)
	}
	return versesText(start, stop), nil
}

// Verse returns the verse for n bottles of beer on the wall. n must be
// between 0 and 99.
func Verse(n int) (string, error) {
	if err := checkVerseNumber(n); err != nil {
		return "", err
	}
	return verseText(n), nil
}

// checkVerseNumber reports an error if n is not a valid verse number.
func checkVerseNumber(n int) error {
	if n < minBottles || n > maxBottles {
		return fmt.Errorf("verse number %d is out of range: must be between %d and %d", n, minBottles, maxBottles)
	}
	return nil
}

// versesText joins the verses from start down to stop (both inclusive),
// separating them with a blank line. It assumes the arguments are valid.
func versesText(start, stop int) string {
	verses := make([]string, 0, start-stop+1)
	for n := start; n >= stop; n-- {
		verses = append(verses, verseText(n))
	}
	// Every verse already ends with a newline, so joining with a single
	// newline produces a blank line between verses.
	return strings.Join(verses, "\n")
}

// verseText returns the verse for n bottles. It assumes n is valid.
func verseText(n int) string {
	return fmt.Sprintf("%s on the wall, %s.\n%s, %s on the wall.\n",
		capitalize(bottlesOfBeer(n)), bottlesOfBeer(n),
		actionFor(n), bottlesOfBeer(bottlesAfter(n)))
}

// bottlesOfBeer describes n bottles of beer, e.g. "2 bottles of beer".
func bottlesOfBeer(n int) string {
	switch n {
	case 0:
		return "no more bottles of beer"
	case 1:
		return "1 bottle of beer"
	default:
		return fmt.Sprintf("%d bottles of beer", n)
	}
}

// actionFor returns the action sung in the second line of the verse for n
// bottles.
func actionFor(n int) string {
	switch n {
	case 0:
		return "Go to the store and buy some more"
	case 1:
		return "Take it down and pass it around"
	default:
		return "Take one down and pass it around"
	}
}

// bottlesAfter returns how many bottles are on the wall once the verse for n
// bottles has been sung.
func bottlesAfter(n int) int {
	if n == minBottles {
		return maxBottles
	}
	return n - 1
}

// capitalize upper-cases the first letter of s.
func capitalize(s string) string {
	if s == "" {
		return s
	}
	return strings.ToUpper(s[:1]) + s[1:]
}
```

