A small `bottles` helper handles the "no more bottles" / "1 bottle" / "N bottles" wording to avoid duplication.

beer_song.go
```go
package beer

import (
	"errors"
	"fmt"
	"strings"
)

// bottles returns the phrase describing n bottles, e.g. "no more bottles",
// "1 bottle" or "5 bottles".
func bottles(n int) string {
	switch n {
	case 0:
		return "no more bottles"
	case 1:
		return "1 bottle"
	default:
		return fmt.Sprintf("%d bottles", n)
	}
}

// capitalize upper-cases the first character of an ASCII string.
func capitalize(s string) string {
	if s == "" {
		return s
	}
	return strings.ToUpper(s[:1]) + s[1:]
}

// Song returns the entire song, from 99 bottles down to no more bottles.
func Song() string {
	song, _ := Verses(99, 0)
	return song
}

// Verses returns the verses from start down to stop (inclusive), separated
// by a blank line.
func Verses(start, stop int) (string, error) {
	if start < 0 || start > 99 {
		return "", errors.New("start must be between 0 and 99")
	}
	if stop < 0 || stop > 99 {
		return "", errors.New("stop must be between 0 and 99")
	}
	if start < stop {
		return "", errors.New("start must not be less than stop")
	}

	verses := make([]string, 0, start-stop+1)
	for i := start; i >= stop; i-- {
		v, err := Verse(i)
		if err != nil {
			return "", err
		}
