    //! An internal DSL for describing graphs, inspired by the Graphviz DOT language.
    //!
    //! The DOT description
    //!
    //! ```text
    //! graph {
    //!     graph [bgcolor="yellow"]
    //!     a [color="red"]
    //!     b [color="blue"]
    //!     a -- b [color="green"]
    //! }
    //! ```
    //!
    //! is written with the builders of this module as
    //!
    //! ```text
    //! let graph = Graph::new()
    //!     .with_attrs(&[("bgcolor", "yellow")])
    //!     .with_nodes(&[
    //!         Node::new("a").with_attrs(&[("color", "red")]),
    //!         Node::new("b").with_attrs(&[("color", "blue")]),
    //!     ])
    //!     .with_edges(&[Edge::new("a", "b").with_attrs(&[("color", "green")])]);
    //! ```

    use std::collections::HashMap;

    use self::graph_items::edge::Edge;
    use self::graph_items::node::Node;

    /// A graph: a list of nodes, a list of edges and a set of graph-wide attributes.
    ///
    /// Graphs are created with [`Graph::new`] and described with the builder methods
    /// [`with_nodes`](Graph::with_nodes), [`with_edges`](Graph::with_edges) and
    /// [`with_attrs`](Graph::with_attrs). Each of them consumes the graph and returns it
    /// again, so the calls can be chained.
    #[derive(Debug, Clone, Default, PartialEq, Eq)]
    pub struct Graph {
        /// The nodes of the graph, in the order they were added.
        pub nodes: Vec<Node>,
        /// The edges of the graph, in the order they were added.
        pub edges: Vec<Edge>,
        /// The attributes of the graph as a whole.
        pub attrs: HashMap<String, String>,
    }

    impl Graph {
        /// Creates an empty graph: no nodes, no edges and no attributes.
        pub fn new() -> Self {
            Self::default()
        }

        /// Adds `nodes` to the graph, keeping their order.
        pub fn with_nodes(mut self, nodes: &[Node]) -> Self {
            self.nodes.extend_from_slice(nodes);
            self
        }

        /// Adds `edges` to the graph, keeping their order.
        pub fn with_edges(mut self, edges: &[Edge]) -> Self {
            self.edges.extend_from_slice(edges);
            self
        }

        /// Sets the given `(key, value)` attributes on the graph.
        ///
        /// An attribute that is already present is overwritten.
        pub fn with_attrs(mut self, attrs: &[(&str, &str)]) -> Self {
            self.attrs.extend(
                attrs
                    .iter()
                    .map(|&(key, value)| (key.to_string(), value.to_string())),
            );
            self
        }

        /// Returns the first node called `name`, if there is one.
        pub fn node(&self, name: &str) -> Option<&Node> {
            self.nodes.iter().find(|node| node.name == name)
        }

        /// Alias of [`Graph::node`].
        pub fn get_node(&self, name: &str) -> Option<&Node> {
            self.node(name)
        }

        /// Returns the value of the graph attribute `key`, if it is set.
        pub fn attr(&self, key: &str) -> Option<&str> {
            self.attrs.get(key).map(String::as_str)
        }

        /// Alias of [`Graph::attr`].
        pub fn get_attr(&self, key: &str) -> Option<&str> {
            self.attr(key)
        }
    }

    pub mod graph_items {
        pub mod edge {
            use std::collections::HashMap;

            /// A connection between two nodes, which are referred to by name.
            #[derive(Debug, Clone, PartialEq, Eq)]
            pub struct Edge {
                /// The name of the node the edge starts at.
                pub src: String,
                /// The name of the node the edge ends at.
                pub dst: String,
                /// The attributes of the edge.
                pub attrs: HashMap<String, String>,
            }

            impl Edge {
                /// Creates an edge from the node called `src` to the node called `dst`,
                /// without any attributes.
                pub fn new(src: &str, dst: &str) -> Self {
                    Self {
                        src: src.to_string(),
                        dst: dst.to_string(),
                        attrs: HashMap::new(),
                    }
                }

                /// Sets the given `(key, value)` attributes on the edge.
                ///
                /// An attribute that is already present is overwritten.
                pub fn with_attrs(mut self, attrs: &[(&str, &str)]) -> Self {
                    self.attrs.extend(
                        attrs
                            .iter()
                            .map(|&(key, value)| (key.to_string(), value.to_string())),
                    );
                    self
                }

                /// Returns the value of the edge attribute `key`, if it is set.
                pub fn attr(&self, key: &str) -> Option<&str> {
                    self.attrs.get(key).map(String::as_str)
                }

                /// Alias of [`Edge::attr`].
                pub fn get_attr(&self, key: &str) -> Option<&str> {
                    self.attr(key)
                }
            }
        }

        pub mod node {
            use std::collections::HashMap;

            /// A node of a graph, identified by its name.
            #[derive(Debug, Clone, PartialEq, Eq)]
            pub struct Node {
                /// The name of the node.
                pub name: String,
                /// The attributes of the node.
                pub attrs: HashMap<String, String>,
            }

            impl Node {
                /// Creates a node called `name` without any attributes.
                pub fn new(name: &str) -> Self {
                    Self {
                        name: name.to_string(),
                        attrs: HashMap::new(),
                    }
                }

                /// Sets the given `(key, value)` attributes on the node.
                ///
                /// An attribute that is already present is overwritten.
                pub fn with_attrs(mut self, attrs: &[(&str, &str)]) -> Self {
                    self.attrs.extend(
                        attrs
                            .iter()
                            .map(|&(key, value)| (key.to_string(), value.to_string())),
                    );
                    self
                }

                /// Returns the value of the node attribute `key`, if it is set.
                pub fn attr(&self, key: &str) -> Option<&str> {
                    self.attrs.get(key).map(String::as_str)
                }

                /// Alias of [`Node::attr`].
                pub fn get_attr(&self, key: &str) -> Option<&str> {
                    self.attr(key)
                }
            }
        }
    }
}
