I implemented the triplet class and its builder in `PythagoreanTriplet.java`.

- **Triplet class:** it stores `a`, `b` and `c`, and I added `equals`, `hashCode` and `toString`. Tests compare lists of triplets, so value equality is required.
- **Builder:** `thatSumTo` and `withFactorsLessThanOrEqualTo` record optional constraints and return the builder, so they can be chained in any order.
- **Sum given (the main case):** substituting `c = N - a - b` into `a^2 + b^2 = c^2` gives `b = N * (N - 2a) / (2 * (N - a))`. So each `a` has at most one candidate `b`, and `build()` loops over `a < N/3` in O(N). A candidate is kept when the division is exact, `a < b`, and `c <= maxFactor`. Since `c` is the largest factor, `c <= maxFactor` is the same as all factors being `<= maxFactor`. Results come out ordered by `a`, which matches the usual expected order (for example, 840 gives 40, 56, 105, ...).
- **Only a max factor given:** all triplets with `c <= maxFactor` are generated with Euclid's formula, scaled by every multiple, then sorted by `a` and `b`.
- **Neither given:** `build()` throws `IllegalStateException`, because there would be infinitely many triplets.

src/main/java/PythagoreanTriplet.java
```java
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Objects;

class PythagoreanTriplet {

    private final int a;
    private final int b;
    private final int c;

    PythagoreanTriplet(int a, int b, int c) {
        this.a = a;
        this.b = b;
        this.c = c;
    }

    static TripletListBuilder makeTripletsList() {
        return new TripletListBuilder();
    }

    @Override
    public boolean equals(Object other) {
        if (this == other) {
            return true;
        }
        if (other == null || getClass() != other.getClass()) {
            return false;
        }
        PythagoreanTriplet that = (PythagoreanTriplet) other;
        return a == that.a && b == that.b && c == that.c;
    }

    @Override
    public int hashCode() {
        return Objects.hash(a, b, c);
    }

    @Override
    public String toString() {
        return "PythagoreanTriplet{a=" + a + ", b=" + b + ", c=" + c + "}";
    }

    static class TripletListBuilder {

        // null means that the constraint has not been specified
        private Integer sum;
        private Integer maxFactor;

        TripletListBuilder thatSumTo(int sum) {
            this.sum = sum;
            return this;
        }

        TripletListBuilder withFactorsLessThanOrEqualTo(int maxFactor) {
            this.maxFactor = maxFactor;
            return this;
        }

        // Returns every triplet (a < b < c) matching the constraints,
        // ordered by a and then by b.
        List<PythagoreanTriplet> build() {
            if (sum != null) {
                long limit = (maxFactor != null) ? maxFactor : Long.MAX_VALUE;
                return tripletsThatSumTo(sum, limit);
            }
            if (maxFactor != null) {
                return tripletsWithFactorsUpTo(maxFactor);
            }
            throw new IllegalStateException(
                    "A sum and/or a maximum factor is required, otherwise there are infinitely many triplets.");
        }

        private static List<PythagoreanTriplet> tripletsThatSumTo(long sum, long limit) {
            List<PythagoreanTriplet> triplets = new ArrayList<>();

            // Since a < b < c, a is always smaller than a third of the sum.
            for (long a = 1; 3 * a < sum; a++) {
                // Replacing c with (sum - a - b) in a^2 + b^2 = c^2 and solving for b gives
                //     b = sum * (sum - 2a) / (2 * (sum - a)),
                // so for every a there is at most one candidate for b.
                long numerator = sum * (sum - 2 * a);
                long denominator = 2 * (sum - a);
                if (numerator % denominator != 0) {
                    continue;
                }

                long b = numerator / denominator;
                long c = sum - a - b;
                if (a < b && c <= limit) {
                    triplets.add(new PythagoreanTriplet((int) a, (int) b, (int) c));
                }
            }

            return triplets;
        }

        private static List<PythagoreanTriplet> tripletsWithFactorsUpTo(long limit) {
            List<PythagoreanTriplet> triplets = new ArrayList<>();

            // Euclid's formula: for coprime m > n > 0 of opposite parity,
            // (m^2 - n^2, 2mn, m^2 + n^2) is a primitive triplet, and every
            // triplet is a multiple of exactly one primitive triplet.
            for (long m = 2; m * m + 1 <= limit; m++) {
                for (long n = 1; n < m && m * m + n * n <= limit; n++) {
                    if ((m - n) % 2 == 0 || greatestCommonDivisor(m, n) != 1) {
                        continue;
                    }

                    long leg1 = m * m - n * n;
                    long leg2 = 2 * m * n;
                    long hypotenuse = m * m + n * n;
                    long a = Math.min(leg1, leg2);
                    long b = Math.max(leg1, leg2);

                    for (long k = 1; k * hypotenuse <= limit; k++) {
                        triplets.add(new PythagoreanTriplet((int) (k * a), (int) (k * b), (int) (k * hypotenuse)));
                    }
                }
            }

            triplets.sort(Comparator.comparingInt((PythagoreanTriplet t) -> t.a).thenComparingInt(t -> t.b));
            return triplets;
        }

        private static long greatestCommonDivisor(long x, long y) {
            while (y != 0) {
                long remainder = x % y;
                x = y;
                y = remainder;
            }
            return x;
        }

    }

}
