import java.util.ArrayList;
import java.util.List;

class PythagoreanTriplet {

    private final int a;
    private final int b;
    private final int c;

    PythagoreanTriplet(int a, int b, int c) {
        this.a = a;
        this.b = b;
        this.c = c;
    }

    static TripletListBuilder makeTripletsList() {
        return new TripletListBuilder();
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) {
            return true;
        }
        if (!(o instanceof PythagoreanTriplet)) {
            return false;
        }
        PythagoreanTriplet t = (PythagoreanTriplet) o;
        return a == t.a && b == t.b && c == t.c;
    }

    @Override
    public int hashCode() {
        return 31 * (31 * a + b) + c;
    }

    @Override
    public String toString() {
        return "{" + a + ", " + b + ", " + c + "}";
    }

    static class TripletListBuilder {

        private Integer sum = null;
        private Integer maxFactor = null;

        TripletListBuilder thatSumTo(int sum) {
            this.sum = sum;
            return this;
        }

        TripletListBuilder withFactorsLessThanOrEqualTo(int maxFactor) {
            this.maxFactor = maxFactor;
            return this;
        }

        List<PythagoreanTriplet> build() {
            List<PythagoreanTriplet> result = new ArrayList<>();
            if (sum == null && maxFactor == null) {
                throw new IllegalStateException("Specify a sum or a maximum factor.");
            }
            int limit = maxFactor != null ? maxFactor : sum;
            if (sum != null) {
                for (int a = 1; a < sum; a++) {
                    for (int b = a + 1; b < sum; b++) {
                        int c = sum - a - b;
                        if (c <= b) {
                            break;
                        }
                        if (c > limit) {
                            continue;
                        }
                        if (a * a + b * b == c * c) {
                            result.add(new PythagoreanTriplet(a, b, c));
                        }
                    }
                }
            } else {
                for (int a = 1; a <= limit; a++) {
                    for (int b = a + 1; b <= limit; b++) {
                        long cc = (long) a * a + (long) b * b;
                        int c = (int) Math.round(Math.sqrt((double) cc));
                        if (c <= limit && (long) c * c == cc && c > b) {
                            result.add(new PythagoreanTriplet(a, b, c));
                        }
                    }
                }
            }
            return result;
        }

    }

}
