The implementation is a backtracking search:
- An empty input returns an empty list.
- Otherwise, try each domino as the start, in both orientations.
- Extend the chain with any unused domino that matches the current end, flipping it if needed.
- When all dominoes are used, accept the chain only if its last number equals its first.
- If no ordering works, throw `ChainNotFoundException`.

Dominoes.java
```java
import java.util.ArrayList;
import java.util.List;

class Dominoes {

    List<Domino> formChain(List<Domino> inputDominoes) throws ChainNotFoundException {
        if (inputDominoes == null || inputDominoes.isEmpty()) {
            return new ArrayList<>();
        }
        int n = inputDominoes.size();
        for (int i = 0; i < n; i++) {
            Domino d = inputDominoes.get(i);
            for (int flip = 0; flip < 2; flip++) {
                Domino first = flip == 0 ? d : new Domino(d.getRight(), d.getLeft());
                boolean[] used = new boolean[n];
                used[i] = true;
                List<Domino> chain = new ArrayList<>();
                chain.add(first);
                if (search(inputDominoes, used, chain, 1)) {
                    return chain;
                }
            }
        }
        throw new ChainNotFoundException("No domino chain found.");
    }

    private boolean search(List<Domino> all, boolean[] used, List<Domino> chain, int count) {
        if (count == all.size()) {
            return chain.get(0).getLeft() == chain.get(chain.size() - 1).getRight();
        }
        int end = chain.get(chain.size() - 1).getRight();
        for (int i = 0; i < all.size(); i++) {
            if (used[i]) {
                continue;
            }
            Domino d = all.get(i);
            for (int flip = 0; flip < 2; flip++) {
                Domino candidate = flip == 0 ? d : new Domino(d.getRight(), d.getLeft());
                if (flip == 1 && d.getLeft() == d.getRight()) {
                    continue;
                }
                if (candidate.getLeft() == end) {
                    used[i] = true;
