import java.util.ArrayList;
import java.util.List;

class Dominoes {

    List<Domino> formChain(List<Domino> inputDominoes) throws ChainNotFoundException {
        if (inputDominoes == null || inputDominoes.isEmpty()) {
            return new ArrayList<>();
        }
        int n = inputDominoes.size();
        for (int i = 0; i < n; i++) {
            Domino d = inputDominoes.get(i);
            boolean[] used = new boolean[n];
            used[i] = true;
            for (int flip = 0; flip < 2; flip++) {
                Domino first = flip == 0 ? d : new Domino(d.getRight(), d.getLeft());
                if (flip == 1 && d.getLeft() == d.getRight()) {
                    break;
                }
                List<Domino> chain = new ArrayList<>();
                chain.add(first);
                if (extend(inputDominoes, used, chain, 1)) {
                    return chain;
                }
            }
        }
        throw new ChainNotFoundException("No domino chain found.");
    }

    private boolean extend(List<Domino> dominoes, boolean[] used, List<Domino> chain, int count) {
        int n = dominoes.size();
        if (count == n) {
            return chain.get(0).getLeft() == chain.get(n - 1).getRight();
        }
        int end = chain.get(chain.size() - 1).getRight();
        for (int i = 0; i < n; i++) {
            if (used[i]) {
                continue;
            }
            Domino d = dominoes.get(i);
            for (int flip = 0; flip < 2; flip++) {
                int l = flip == 0 ? d.getLeft() : d.getRight();
                int r = flip == 0 ? d.getRight() : d.getLeft();
                if (flip == 1 && l == r) {
                    break;
