                if (l == end) {
                    used[i] = true;
                    chain.add(new Domino(l, r));
                    if (extend(dominoes, used, chain, count + 1)) {
                        return true;
                    }
                    chain.remove(chain.size() - 1);
                    used[i] = false;
                }
            }
        }
        return false;
    }

