import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Deque;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

class Dominoes {

    private static final String NO_CHAIN_FOUND = "No domino chain found.";

    List<Domino> formChain(List<Domino> inputDominoes) throws ChainNotFoundException {
        if (inputDominoes.isEmpty()) {
            return new ArrayList<>();
        }

        // Model the dominoes as a graph: every number of dots is a vertex and every domino is an
        // edge between its two numbers. A valid chain is an Eulerian circuit of that graph, i.e. a
        // closed walk which uses every edge exactly once.
        Map<Integer, List<Integer>> dominoesByNumber = new HashMap<>();
        for (int i = 0; i < inputDominoes.size(); i++) {
            Domino domino = inputDominoes.get(i);
            dominoesByNumber.computeIfAbsent(domino.getLeft(), number -> new ArrayList<>()).add(i);
            dominoesByNumber.computeIfAbsent(domino.getRight(), number -> new ArrayList<>()).add(i);
        }

        // Every number must be used an even number of times (a double like [3|3] counts twice),
        // otherwise a closed walk could not enter and leave that number equally often.
        for (List<Integer> indices : dominoesByNumber.values()) {
            if (indices.size() % 2 != 0) {
                throw new ChainNotFoundException(NO_CHAIN_FOUND);
            }
        }

        List<Domino> chain = findCircuit(inputDominoes, dominoesByNumber);

        // The walk only reaches dominoes connected to the starting one. If some dominoes were not
        // reached, the set falls apart into separate groups and can't form a single chain.
        if (chain.size() != inputDominoes.size()) {
            throw new ChainNotFoundException(NO_CHAIN_FOUND);
        }

        return chain;
    }

    /**
     * Hierholzer's algorithm: walks along unused dominoes until stuck, then backtracks and
     * splices in any detours that are still possible. Every domino in the result is oriented
     * in the direction of the walk, so the right side of each domino matches the left side of
     * the next one, and the right side of the last domino matches the left side of the first.
     */
    private static List<Domino> findCircuit(List<Domino> dominoes, Map<Integer, List<Integer>> dominoesByNumber) {
        boolean[] used = new boolean[dominoes.size()];
        Map<Integer, Integer> nextCandidate = new HashMap<>();
        Deque<Domino> walk = new ArrayDeque<>();
        List<Domino> circuit = new ArrayList<>();

        int current = dominoes.get(0).getLeft();
        while (true) {
            List<Integer> indices = dominoesByNumber.get(current);
            int position = nextCandidate.getOrDefault(current, 0);
            while (position < indices.size() && used[indices.get(position)]) {
                position++;
            }
            nextCandidate.put(current, position);

            if (position < indices.size()) {
                // Extend the walk with an unused domino, turned so that it starts with the current number.
                int index = indices.get(position);
                used[index] = true;
                Domino domino = dominoes.get(index);
                Domino oriented = domino.getLeft() == current
                        ? domino
                        : new Domino(domino.getRight(), domino.getLeft());
                walk.push(oriented);
                current = oriented.getRight();
            } else if (!walk.isEmpty()) {
                // Dead end: this domino is final, so move it to the circuit and step back.
                Domino oriented = walk.pop();
                circuit.add(oriented);
                current = oriented.getLeft();
            } else {
                break;
            }
        }

        // The dominoes were collected back to front.
        Collections.reverse(circuit);
        return circuit;
    }

}
