const isPalindrome = (n) => {
  const s = String(n);
  let i = 0;
  let j = s.length - 1;
  while (i < j) {
    if (s[i] !== s[j]) return false;
    i++;
    j--;
  }
  return true;
};

export class Palindromes {
  constructor(minFactor, maxFactor) {
    this.minFactor = minFactor;
    this.maxFactor = maxFactor;
    this._smallest = undefined;
    this._largest = undefined;
  }

  static generate({ maxFactor, minFactor } = {}) {
    if (minFactor > maxFactor) {
      throw new Error('min must be <= max');
    }
    return new Palindromes(minFactor, maxFactor);
  }

  get smallest() {
    if (this._smallest === undefined) {
      this._smallest = this._findSmallest();
    }
    return this._smallest;
  }

  get largest() {
    if (this._largest === undefined) {
      this._largest = this._findLargest();
    }
    return this._largest;
  }

  _factorsOf(value) {
    const factors = [];
    for (let a = this.minFactor; a <= this.maxFactor && a * a <= value; a++) {
      if (a !== 0 ? value % a === 0 : value === 0) {
        const b = a !== 0 ? value / a : null;
        if (b !== null && b >= a && b <= this.maxFactor && b >= this.minFactor) {
          factors.push([a, b]);
        }
      }
    }
    return factors;
  }

  _findSmallest() {
    let best = null;
    for (let a = this.minFactor; a <= this.maxFactor; a++) {
      for (let b = a; b <= this.maxFactor; b++) {
        const product = a * b;
        if (best !== null && product > best) break;
        if (isPalindrome(product) && (best === null || product < best)) {
          best = product;
        }
      }
    }
    if (best === null) {
      return { value: null, factors: [] };
    }
    return { value: best, factors: this._factorsOf(best) };
  }

  _findLargest() {
    let best = null;
    for (let a = this.maxFactor; a >= this.minFactor; a--) {
      for (let b = this.maxFactor; b >= a; b--) {
        const product = a * b;
        if (best !== null && product < best) break;
        if (isPalindrome(product) && (best === null || product > best)) {
          best = product;
        }
      }
    }
    if (best === null) {
      return { value: null, factors: [] };
    }
    return { value: best, factors: this._factorsOf(best) };
  }
}
