//
// Palindrome Products
//
// Finds the smallest and the largest palindromic product of two factors taken
// from a range, together with every pair of factors (from that range) that
// produces each of them.
//

// A number is palindromic when its decimal digits read the same in both
// directions: 121 is, 112 is not.
const isPalindrome = (number) => {
  const digits = String(number);
  const last = digits.length - 1;
  for (let i = 0; i < last - i; i += 1) {
    if (digits[i] !== digits[last - i]) {
      return false;
    }
  }
  return true;
};

// Value of the smallest palindromic product a * b with min <= a <= b <= max,
// or null when there is none.
//
// The first factor `a` is walked upwards. For a fixed `a` the products grow
// with `b`, so the first palindrome met is the best one for that `a`, and the
// scan can stop as soon as a product reaches the best value found so far.
// Once even a * a (the smallest product still to come) cannot beat the best
// value, no remaining pair can and the whole search is over.
const findSmallest = (min, max) => {
  let best = null;
  for (let a = min; a <= max; a += 1) {
    if (best !== null && a * a >= best) {
      break;
    }
    for (let b = a; b <= max; b += 1) {
      const product = a * b;
      if (best !== null && product >= best) {
        break;
      }
      if (isPalindrome(product)) {
        best = product;
        break;
      }
    }
  }
  return best;
};

// Value of the largest palindromic product a * b with min <= a <= b <= max,
// or null when there is none.
//
// Mirror image of `findSmallest`: the factors are walked downwards and the
// search is over once even a * max cannot beat the best value found so far.
const findLargest = (min, max) => {
  let best = null;
  for (let a = max; a >= min; a -= 1) {
    if (best !== null && a * max <= best) {
      break;
    }
    for (let b = max; b >= a; b -= 1) {
      const product = a * b;
      if (best !== null && product <= best) {
        break;
      }
      if (isPalindrome(product)) {
        best = product;
        break;
      }
    }
  }
  return best;
};

// Every pair [a, b] with min <= a <= b <= max and a * b === value,
// ordered by their first factor.
const findFactorPairs = (value, min, max) => {
  if (value === 0) {
    // Zero is only reachable through the factor 0, i.e. when min is 0.
    return Array.from({ length: max + 1 }, (_, b) => [0, b]);
  }

  const pairs = [];
  // a >= value / max keeps b = value / a within the range,
  // and a * a <= value keeps a <= b.
  const first = Math.max(min, Math.ceil(value / max));
  for (let a = first; a * a <= value; a += 1) {
    if (value % a === 0) {
      pairs.push([a, value / a]);
    }
  }
  return pairs;
};

// Runs the given search over the range and attaches all factor pairs of the
// value it found (no value means no factors).
const buildResult = (find, min, max) => {
  const value = find(min, max);
  return {
    value,
    factors: value === null ? [] : findFactorPairs(value, min, max),
  };
};

const assertValidRange = (min, max) => {
  if (!Number.isInteger(min) || !Number.isInteger(max)) {
    throw new TypeError('minFactor and maxFactor must be integers');
  }
  if (min > max) {
    throw new Error('min must be <= max');
  }
  if (min < 0) {
    throw new RangeError('factors must not be negative');
  }
  if (!Number.isSafeInteger(max * max)) {
    throw new RangeError('maxFactor is too large for exact products');
  }
};

export class Palindromes {
  constructor(smallest, largest) {
    this.smallest = smallest;
    this.largest = largest;
  }

  static generate({ maxFactor, minFactor = 1 } = {}) {
    assertValidRange(minFactor, maxFactor);

    return new Palindromes(
      buildResult(findSmallest, minFactor, maxFactor),
      buildResult(findLargest, minFactor, maxFactor)
    );
  }
}
