```
#include "perfect_numbers.h"

#include <stdexcept>

namespace perfect_numbers {

namespace {

// Sum of all positive divisors of `number`, excluding `number` itself.
// A 64-bit accumulator is used so the sum cannot overflow for any positive int.
long long aliquot_sum(int number) {
    if (number == 1) {
        return 0;  // 1 has no divisors other than itself
    }

    long long sum = 1;  // 1 divides every number greater than 1
    for (long long divisor = 2; divisor * divisor <= number; ++divisor) {
        if (number % divisor == 0) {
            sum += divisor;

            const long long paired_divisor = number / divisor;
            if (paired_divisor != divisor) {  // don't count a square root twice
                sum += paired_divisor;
            }
        }
    }
    return sum;
}

}  // namespace

classification classify(int number) {
    if (number < 1) {
        throw std::domain_error("Only positive integers can be classified");
    }

    const long long sum = aliquot_sum(number);

    if (sum == number) {
        return classification::perfect;
    }
    if (sum > number) {
        return classification::abundant;
    }
    return classification::deficient;
}

}  // namespace perfect_numbers
```

