```go
package beer

import (
	"fmt"
	"strings"
)

// bottles returns the phrase describing n bottles, e.g. "2 bottles of beer".
func bottles(n int) string {
	switch n {
	case 0:
		return "no more bottles of beer"
	case 1:
		return "1 bottle of beer"
	default:
		return fmt.Sprintf("%d bottles of beer", n)
	}
}

// capitalize upper-cases the first letter of s.
func capitalize(s string) string {
	if s == "" {
		return s
	}
	return strings.ToUpper(s[:1]) + s[1:]
}

// Song returns the full lyrics of the song.
func Song() string {
	s, _ := Verses(99, 0)
	return s
}

// Verses returns the verses from start down to stop, inclusive.
func Verses(start, stop int) (string, error) {
	if start < 0 || start > 99 {
		return "", fmt.Errorf("start value %d is out of range (0-99)", start)
	}
	if stop < 0 || stop > 99 {
		return "", fmt.Errorf("stop value %d is out of range (0-99)", stop)
	}
	if start < stop {
		return "", fmt.Errorf("start value %d is less than stop value %d", start, stop)
	}

	var sb strings.Builder
	for i := start; i >= stop; i-- {
		v, err := Verse(i)
		if err != nil {
			return "", err
		}
		sb.WriteString(v)
		sb.WriteString("\n")
	}
	return sb.String(), nil
}

// Verse returns a single verse of the song.
func Verse(n int) (string, error) {
	if n < 0 || n > 99 {
		return "", fmt.Errorf("verse number %d is out of range (0-99)", n)
	}

	var action, next string
	switch n {
	case 0:
		action = "Go to the store and buy some more"
		next = bottles(99)
	case 1:
		action = "Take it down and pass it around"
		next = bottles(0)
	default:
		action = "Take one down and pass it around"
		next = bottles(n - 1)
	}

	return fmt.Sprintf("%s on the wall, %s.\n%s, %s on the wall.\n",
		capitalize(bottles(n)), bottles(n), action, next), nil
}
```

