- `Verses(start, stop)` returns an error if either number is outside 0–99 or if `start < stop`. It joins the verses from `start` down to `stop` with a blank line between them.
- `Song()` is `Verses(99, 0)`.

The trailing-newline and blank-line format is what I recall the standard Exercism beer-song tests expecting, so check it against your test file.

beer_song.go
```go
package beer

import (
	"fmt"
	"strings"
)

// bottles returns the phrase describing n bottles, e.g. "2 bottles of beer".
func bottles(n int) string {
	switch n {
	case 0:
		return "no more bottles of beer"
	case 1:
		return "1 bottle of beer"
	default:
		return fmt.Sprintf("%d bottles of beer", n)
	}
}

func capitalize(s string) string {
	if s == "" {
		return s
	}
	return strings.ToUpper(s[:1]) + s[1:]
}

// Song returns the whole song, from 99 bottles down to none.
func Song() string {
	s, _ := Verses(99, 0)
	return s
}

// Verses returns the verses from start down to stop, separated by blank lines.
func Verses(start, stop int) (string, error) {
	if start < 0 || start > 99 {
		return "", fmt.Errorf("start value %d is out of range", start)
	}
	if stop < 0 || stop > 99 {
		return "", fmt.Errorf("stop value %d is out of range", stop)
	}
	if start < stop {
		return "", fmt.Errorf("start value %d is less than stop value %d", start, stop)
	}
	var parts []string
	for i := start; i >= stop; i-- {
		v, err := Verse(i)
		if err != nil {
			return "", err
		}
		parts = append(parts, v)
	}
	return strings.Join(parts, "\n"), nil
}

// Verse returns a single verse of the song.
func Verse(n int) (string, error) {
	if n < 0 || n > 99 {
		return "", fmt.Errorf("verse number %d is out of range", n)
	}
	var action string
	switch n {
	case 0:
		action = "Go to the store and buy some more, " + bottles(99)
	case 1:
		action = "Take it down and pass it around, " + bottles(0)
	default:
		action = "Take one down and pass it around, " + bottles(n-1)
	}
	return fmt.Sprintf("%s on the wall, %s.\n%s on the wall.\n",
		capitalize(bottles(n)), bottles(n), action), nil
}
