package beer

import (
	"errors"
	"fmt"
	"strings"
)

// Song returns the full lyrics of the song, from 99 bottles down to none.
func Song() string {
	s, _ := Verses(99, 0)
	return s
}

// Verses returns the verses from start down to stop, inclusive,
// each verse followed by a blank line separator.
func Verses(start, stop int) (string, error) {
	if start < 0 || start > 99 {
		return "", errors.New("start must be between 0 and 99")
	}
	if stop < 0 || stop > 99 {
		return "", errors.New("stop must be between 0 and 99")
	}
	if start < stop {
		return "", errors.New("start must not be less than stop")
	}

	var sb strings.Builder
	for i := start; i >= stop; i-- {
		v, err := Verse(i)
		if err != nil {
			return "", err
		}
		sb.WriteString(v)
		sb.WriteString("\n")
	}
	return sb.String(), nil
}

// Verse returns a single verse of the song.
func Verse(n int) (string, error) {
	switch {
	case n < 0 || n > 99:
		return "", errors.New("verse number must be between 0 and 99")
	case n == 0:
		return "No more bottles of beer on the wall, no more bottles of beer.\n" +
			"Go to the store and buy some more, 99 bottles of beer on the wall.\n", nil
	case n == 1:
		return "1 bottle of beer on the wall, 1 bottle of beer.\n" +
			"Take it down and pass it around, no more bottles of beer on the wall.\n", nil
	default:
		return fmt.Sprintf("%s on the wall, %s.\nTake one down and pass it around, %s on the wall.\n",
			bottles(n), bottles(n), bottles(n-1)), nil
	}
}

// bottles returns a phrase like "2 bottles of beer" or "1 bottle of beer".
func bottles(n int) string {
	switch n {
	case 0:
		return "no more bottles of beer"
	case 1:
		return "1 bottle of beer"
	default:
		return fmt.Sprintf("%d bottles of beer", n)
	}
}
