package beer

import (
	"fmt"
	"strings"
)

// bottles returns the phrase describing n bottles of beer.
func bottles(n int) string {
	switch n {
	case 0:
		return "no more bottles"
	case 1:
		return "1 bottle"
	default:
		return fmt.Sprintf("%d bottles", n)
	}
}

// capitalize upper-cases the first letter of s.
func capitalize(s string) string {
	if s == "" {
		return s
	}
	return strings.ToUpper(s[:1]) + s[1:]
}

// Song returns the whole song, from 99 bottles down to no more bottles.
func Song() string {
	s, _ := Verses(99, 0)
	return s
}

// Verses returns the verses from start down to stop, separated by blank lines.
func Verses(start, stop int) (string, error) {
	if start < 0 || start > 99 {
		return "", fmt.Errorf("start value[%d] is not a valid verse", start)
	}
	if stop < 0 || stop > 99 {
		return "", fmt.Errorf("stop value[%d] is not a valid verse", stop)
	}
	if start < stop {
		return "", fmt.Errorf("start value[%d] is less than stop value[%d]", start, stop)
	}

	var sb strings.Builder
	for i := start; i >= stop; i-- {
		v, err := Verse(i)
		if err != nil {
			return "", err
		}
		sb.WriteString(v)
		sb.WriteString("\n")
	}
	return sb.String(), nil
}

// Verse returns a single verse of the song.
func Verse(n int) (string, error) {
	if n < 0 || n > 99 {
		return "", fmt.Errorf("%d is not a valid verse", n)
	}

	var action string
	var next int
	switch n {
	case 0:
		action = "Go to the store and buy some more"
		next = 99
	case 1:
		action = "Take it down and pass it around"
		next = 0
	default:
		action = "Take one down and pass it around"
		next = n - 1
	}

	return fmt.Sprintf("%s of beer on the wall, %s of beer.\n%s, %s of beer on the wall.\n",
		capitalize(bottles(n)), bottles(n), action, bottles(next)), nil
}
