/// An internal DSL for describing graphs, in the spirit of the Graphviz DOT language.
///
/// Instead of parsing a textual description, a graph is declared directly in Rust by
/// chaining builder calls. The DOT graph
///
/// ```text
/// graph {
///     graph [bgcolor="yellow"]
///     a [color="red"]
///     b [color="blue"]
///     a -- b [color="green"]
/// }
/// ```
///
/// is declared as
///
/// ```text
/// let graph = Graph::new()
///     .with_attrs(&[("bgcolor", "yellow")])
///     .with_nodes(&[
///         Node::new("a").with_attrs(&[("color", "red")]),
///         Node::new("b").with_attrs(&[("color", "blue")]),
///     ])
///     .with_edges(&[Edge::new("a", "b").with_attrs(&[("color", "green")])]);
/// ```
pub mod graph {
    use self::graph_items::edge::Edge;
    use self::graph_items::node::Node;
    use std::collections::HashMap;

    /// A graph made of nodes, edges and graph-wide attributes.
    #[derive(Clone, Debug, Default, PartialEq, Eq)]
    pub struct Graph {
        /// The nodes of the graph, in declaration order.
        pub nodes: Vec<Node>,
        /// The edges of the graph, in declaration order.
        pub edges: Vec<Edge>,
        /// The attributes that apply to the graph as a whole.
        pub attrs: HashMap<String, String>,
    }

    impl Graph {
        /// Creates an empty graph: no nodes, no edges and no attributes.
        pub fn new() -> Self {
            Self::default()
        }

        /// Adds the given nodes to the graph.
        pub fn with_nodes(mut self, nodes: &[Node]) -> Self {
            self.nodes.extend_from_slice(nodes);
            self
        }

        /// Adds the given edges to the graph.
        pub fn with_edges(mut self, edges: &[Edge]) -> Self {
            self.edges.extend_from_slice(edges);
            self
        }

        /// Sets the given attributes on the graph, overwriting any attribute
        /// that was already set under the same name.
        pub fn with_attrs(mut self, attrs: &[(&str, &str)]) -> Self {
            graph_items::merge_attrs(&mut self.attrs, attrs);
            self
        }

        /// Returns the first node with the given name, if any.
        pub fn node(&self, name: &str) -> Option<&Node> {
            self.nodes.iter().find(|node| node.name == name)
        }

        /// Returns the value of the graph attribute with the given name, if it is set.
        pub fn attr(&self, name: &str) -> Option<&str> {
            self.attrs.get(name).map(String::as_str)
        }
    }

    pub mod graph_items {
        use std::collections::HashMap;

        /// Copies `attrs` into `target`, overwriting attributes that are already present.
        pub(super) fn merge_attrs(target: &mut HashMap<String, String>, attrs: &[(&str, &str)]) {
            target.extend(
                attrs
                    .iter()
                    .map(|&(key, value)| (key.to_string(), value.to_string())),
            );
        }

        pub mod edge {
            use super::merge_attrs;
            use std::collections::HashMap;

            /// An edge connecting two nodes of a graph.
            #[derive(Clone, Debug, PartialEq, Eq)]
            pub struct Edge {
                /// The name of the node the edge starts from.
                pub src: String,
                /// The name of the node the edge ends at.
                pub dst: String,
                /// The attributes of the edge.
                pub attrs: HashMap<String, String>,
            }

            impl Edge {
                /// Creates an edge from `src` to `dst`, without any attribute.
                pub fn new(src: &str, dst: &str) -> Self {
                    Self {
                        src: src.to_string(),
                        dst: dst.to_string(),
                        attrs: HashMap::new(),
                    }
                }

                /// Sets the given attributes on the edge, overwriting any attribute
                /// that was already set under the same name.
                pub fn with_attrs(mut self, attrs: &[(&str, &str)]) -> Self {
                    merge_attrs(&mut self.attrs, attrs);
                    self
                }

                /// Returns the value of the edge attribute with the given name, if it is set.
                pub fn attr(&self, name: &str) -> Option<&str> {
                    self.attrs.get(name).map(String::as_str)
                }
            }
        }

        pub mod node {
            use super::merge_attrs;
            use std::collections::HashMap;

            /// A node of a graph, identified by its name.
            #[derive(Clone, Debug, PartialEq, Eq)]
            pub struct Node {
                /// The name identifying the node.
                pub name: String,
                /// The attributes of the node.
                pub attrs: HashMap<String, String>,
            }

            impl Node {
                /// Creates a node with the given name, without any attribute.
                pub fn new(name: &str) -> Self {
                    Self {
                        name: name.to_string(),
                        attrs: HashMap::new(),
                    }
                }

                /// Sets the given attributes on the node, overwriting any attribute
                /// that was already set under the same name.
                pub fn with_attrs(mut self, attrs: &[(&str, &str)]) -> Self {
                    merge_attrs(&mut self.attrs, attrs);
                    self
                }

                /// Returns the value of the node attribute with the given name, if it is set.
                pub fn attr(&self, name: &str) -> Option<&str> {
                    self.attrs.get(name).map(String::as_str)
                }
            }
        }
    }
}
