I'll implement a tokenizer-based parser that evaluates left to right.

Key behaviors:
- Strip the `What is` prefix and trailing `?`; anything else is a "unknown operation" error (non-math questions).
- Tokenize, supporting multi-word operators ("multiplied by", "divided by").
- Expect alternating number/operator tokens; otherwise raise `syntax error`.
- Unknown words in operator position raise `unknown operation`.
- Integer division is used for "divided by" (the results are expected as integers); division by zero raises `ValueError("division by zero")`.

wordy.py
```python
import re

_OPERATIONS = {
    "plus": lambda a, b: a + b,
    "minus": lambda a, b: a - b,
    "multiplied by": lambda a, b: a * b,
    "divided by": lambda a, b: a // b if a % b == 0 else a / b,
}


def _parse_int(token):
    if re.fullmatch(r"[+-]?\d+", token):
        return int(token)
    return None


def answer(question):
    match = re.fullmatch(r"\s*what is\b(.*?)\??\s*", question, re.IGNORECASE)
    if not match:
        raise ValueError("unknown operation")

    body = match.group(1).strip()
    if not body:
        raise ValueError("syntax error")

    # Normalize multi-word operators into single tokens.
    body = re.sub(r"\bmultiplied\s+by\b", "multiplied_by", body)
    body = re.sub(r"\bdivided\s+by\b", "divided_by", body)
    tokens = body.split()

    def to_op(token):
        return token.replace("_", " ")

    # First token must be a number.
    result = _parse_int(tokens[0])
    if result is None:
        if to_op(tokens[0]) in _OPERATIONS:
            raise ValueError("syntax error")
        raise ValueError("unknown operation")

    index = 1
    while index < len(tokens):
        op = to_op(tokens[index])
        if op not in _OPERATIONS:
            if _parse_int(tokens[index]) is not None:
                raise ValueError("syntax error")
            raise ValueError("unknown operation")
        if index + 1 >= len(tokens):
            raise ValueError("syntax error")
        operand = _parse_int(tokens[index + 1])
        if operand is None:
            raise ValueError("syntax error")
        if op == "divided by" and operand == 0:
            raise ValueError("division by zero")
        result = _OPERATIONS[op](result, operand)
        index += 2

    return result
