def answer(question):
    prefix = "what is"
    text = question.strip()
    if not text.lower().startswith(prefix):
        raise ValueError("unknown operation")

    text = text[len(prefix):]
    if text.endswith("?"):
        text = text[:-1]
    text = text.strip().lower()
    text = text.replace("multiplied by", "multiplied").replace("divided by", "divided")

    tokens = text.split()
    if not tokens:
        raise ValueError("syntax error")

    operations = {
        "plus": lambda a, b: a + b,
        "minus": lambda a, b: a - b,
        "multiplied": lambda a, b: a * b,
        "divided": lambda a, b: a // b,
    }

    def parse_number(token):
        try:
            return int(token)
        except ValueError:
            return None

    result = parse_number(tokens[0])
    if result is None:
        if tokens[0] in operations:
            raise ValueError("syntax error")
        raise ValueError("unknown operation")

    index = 1
    while index < len(tokens):
        op = tokens[index]
        if op not in operations:
            if parse_number(op) is not None:
                raise ValueError("syntax error")
            raise ValueError("unknown operation")
        if index + 1 >= len(tokens):
            raise ValueError("syntax error")
        operand = parse_number(tokens[index + 1])
        if operand is None:
            if tokens[index + 1] in operations:
                raise ValueError("syntax error")
            raise ValueError("unknown operation")
        if op == "divided" and operand == 0:
            raise ValueError("division by zero")
        result = operations[op](result, operand)
        index += 2

    return result
