PythagoreanTriplet.java
```java
import java.util.ArrayList;
import java.util.List;
import java.util.Objects;

class PythagoreanTriplet {

    private final int a;
    private final int b;
    private final int c;

    PythagoreanTriplet(int a, int b, int c) {
        this.a = a;
        this.b = b;
        this.c = c;
    }

    static TripletListBuilder makeTripletsList() {
        return new TripletListBuilder();
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) {
            return true;
        }
        if (o == null || getClass() != o.getClass()) {
            return false;
        }
        PythagoreanTriplet other = (PythagoreanTriplet) o;
        return a == other.a && b == other.b && c == other.c;
    }

    @Override
    public int hashCode() {
        return Objects.hash(a, b, c);
    }

    @Override
    public String toString() {
        return "PythagoreanTriplet{" + a + ", " + b + ", " + c + "}";
    }

    static class TripletListBuilder {

        private Integer sum = null;
        private Integer maxFactor = null;

        TripletListBuilder thatSumTo(int sum) {
            this.sum = sum;
            return this;
        }

        TripletListBuilder withFactorsLessThanOrEqualTo(int maxFactor) {
            this.maxFactor = maxFactor;
            return this;
        }

        List<PythagoreanTriplet> build() {
            if (sum == null && maxFactor == null) {
                throw new IllegalStateException(
                        "Either a sum or a maximum factor must be specified.");
            }

            List<PythagoreanTriplet> result = new ArrayList<>();

            int limit = maxFactor != null ? maxFactor : sum;

            if (sum != null) {
                int n = sum;
                for (int a = 1; a < n; a++) {
                    for (int b = a + 1; b < n; b++) {
                        int c = n - a - b;
                        if (c <= b) {
                            break;
                        }
                        if (c > limit) {
                            continue;
                        }
                        if ((long) a * a + (long) b * b == (long) c * c) {
                            result.add(new PythagoreanTriplet(a, b, c));
                        }
                    }
                }
            } else {
                for (int a = 1; a <= limit; a++) {
                    for (int b = a + 1; b <= limit; b++) {
                        long cSquared = (long) a * a + (long) b * b;
                        long c = (long) Math.sqrt((double) cSquared);
                        while (c * c < cSquared) {
                            c++;
                        }
                        while (c * c > cSquared) {
                            c--;
                        }
                        if (c * c == cSquared && c > b && c <= limit) {
                            result.add(new PythagoreanTriplet(a, b, (int) c));
                        }
                    }
                }
            }

            return result;
        }

    }

}
