```java
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Objects;

class PythagoreanTriplet {

    private final int a;
    private final int b;
    private final int c;

    PythagoreanTriplet(int a, int b, int c) {
        this.a = a;
        this.b = b;
        this.c = c;
    }

    static TripletListBuilder makeTripletsList() {
        return new TripletListBuilder();
    }

    @Override
    public boolean equals(Object other) {
        if (this == other) {
            return true;
        }
        if (other == null || getClass() != other.getClass()) {
            return false;
        }
        PythagoreanTriplet that = (PythagoreanTriplet) other;
        return a == that.a && b == that.b && c == that.c;
    }

    @Override
    public int hashCode() {
        return Objects.hash(a, b, c);
    }

    @Override
    public String toString() {
        return "PythagoreanTriplet{a=" + a + ", b=" + b + ", c=" + c + "}";
    }

    static class TripletListBuilder {

        // A null value means that the corresponding restriction has not been requested.
        private Integer sum;
        private Integer maxFactor;

        TripletListBuilder thatSumTo(int sum) {
            this.sum = sum;
            return this;
        }

        TripletListBuilder withFactorsLessThanOrEqualTo(int maxFactor) {
            this.maxFactor = maxFactor;
            return this;
        }

        // Builds all triplets (a < b < c, a^2 + b^2 = c^2) matching the requested restrictions,
        // ordered by ascending a (and then ascending b).
        List<PythagoreanTriplet> build() {
            if (sum != null) {
                return tripletsThatSumTo(sum);
            }
            if (maxFactor != null) {
                return tripletsWithFactorsUpTo(maxFactor);
            }
            throw new IllegalStateException(
                    "A sum and/or a maximum factor is required, otherwise there are infinitely many triplets.");
        }

        /*
         * Substituting c = sum - a - b into a^2 + b^2 = c^2 and simplifying gives
         *
         *     b = sum * (sum - 2a) / (2 * (sum - a))
         *
         * so every candidate a determines at most one b. Because a < b < c, a is smaller
         * than sum / 3. Candidates are visited in ascending order of a, which yields the
         * required ordering of the result.
         */
        private List<PythagoreanTriplet> tripletsThatSumTo(long targetSum) {
            List<PythagoreanTriplet> triplets = new ArrayList<>();

            for (long a = 1; 3 * a < targetSum; a++) {
                long numerator = targetSum * (targetSum - 2 * a);
                long denominator = 2 * (targetSum - a);
                if (numerator % denominator != 0) {
                    continue;
                }

                long b = numerator / denominator;
                long c = targetSum - a - b;

                // For a close to sum / 3 the formula yields b < a. That is a triplet which has
                // already been found with the roles of a and b swapped, so it must be skipped.
                if (a < b && b < c && isWithinMaxFactor(c)) {
                    triplets.add(new PythagoreanTriplet((int) a, (int) b, (int) c));
                }
            }

            return triplets;
        }

        private boolean isWithinMaxFactor(long factor) {
            return maxFactor == null || factor <= maxFactor;
        }

        /*
         * Euclid's formula: for m > n > 0 with m and n coprime and m - n odd,
         * (m^2 - n^2, 2mn, m^2 + n^2) is a primitive triplet, and every triplet is an
         * integer multiple of exactly one primitive triplet.
         */
        private static List<PythagoreanTriplet> tripletsWithFactorsUpTo(long limit) {
            List<PythagoreanTriplet> triplets = new ArrayList<>();

            // For a given m the smallest hypotenuse is obtained with n = 1: m^2 + 1.
            for (long m = 2; m * m + 1 <= limit; m++) {
                for (long n = 1; n < m; n++) {
                    long primitiveC = m * m + n * n;
                    if (primitiveC > limit) {
                        break;
                    }
                    if ((m - n) % 2 == 0 || gcd(m, n) != 1) {
                        continue;
                    }

                    long legOne = m * m - n * n;
                    long legTwo = 2 * m * n;
                    long primitiveA = Math.min(legOne, legTwo);
                    long primitiveB = Math.max(legOne, legTwo);

                    for (long k = 1; k * primitiveC <= limit; k++) {
                        triplets.add(new PythagoreanTriplet(
                                (int) (k * primitiveA),
                                (int) (k * primitiveB),
                                (int) (k * primitiveC)));
                    }
                }
            }

            triplets.sort(Comparator.comparingInt((PythagoreanTriplet t) -> t.a).thenComparingInt(t -> t.b));
            return triplets;
        }

        private static long gcd(long x, long y) {
            return y == 0 ? x : gcd(y, x % y);
        }

    }

}
```

