        if (!(o instanceof PythagoreanTriplet)) return false;
        PythagoreanTriplet t = (PythagoreanTriplet) o;
        return a == t.a && b == t.b && c == t.c;
    }

    @Override
    public int hashCode() {
        return 31 * (31 * a + b) + c;
    }

