            this.maxFactor = maxFactor;
            return this;
        }

        List<PythagoreanTriplet> build() {
            List<PythagoreanTriplet> result = new ArrayList<>();
            int limit;
            if (maxFactor != null) {
                limit = maxFactor;
            } else if (sum != null) {
                limit = sum;
            } else {
                throw new IllegalStateException("Need a sum or a max factor.");
            }
            for (int a = 1; a <= limit; a++) {
                for (int b = a + 1; b <= limit; b++) {
                    int c;
                    if (sum != null) {
                        c = sum - a - b;
                        if (c <= b) break;
                        if (c > limit) continue;
                    } else {
                        long c2 = (long) a * a + (long) b * b;
                        c = (int) Math.round(Math.sqrt((double) c2));
