- **Triplet class:** It stores `a`, `b` and `c`. It also has `equals`, `hashCode` and `toString`, so triplets can be compared in lists.
- **Builder:** `thatSumTo` and `withFactorsLessThanOrEqualTo` set optional constraints. `build()` returns triplets ordered by `a`, then `b`.
- **Sum set:** `build()` loops over `a` and `b`, derives `c = sum - a - b`, and keeps the triplet if `a² + b² = c²` and `c` is within the factor limit.
- **Only a factor limit set:** `build()` loops over `a` and `b` up to the limit and checks whether `a² + b²` is a perfect square no larger than the limit.
- **Neither set:** `build()` throws `IllegalStateException`, since the result would be unbounded.

```java
import java.util.ArrayList;
import java.util.List;

class PythagoreanTriplet {

    private final int a;
    private final int b;
    private final int c;

    PythagoreanTriplet(int a, int b, int c) {
        this.a = a;
        this.b = b;
        this.c = c;
    }

    static TripletListBuilder makeTripletsList() {
        return new TripletListBuilder();
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) {
            return true;
        }
        if (!(o instanceof PythagoreanTriplet)) {
            return false;
        }
        PythagoreanTriplet other = (PythagoreanTriplet) o;
        return a == other.a && b == other.b && c == other.c;
    }

    @Override
    public int hashCode() {
        int result = a;
        result = 31 * result + b;
        result = 31 * result + c;
        return result;
    }

    @Override
    public String toString() {
        return "{" + a + ", " + b + ", " + c + "}";
    }

    static class TripletListBuilder {

        private Integer sum = null;
        private int maxFactor = Integer.MAX_VALUE;
        private boolean maxFactorSet = false;

        TripletListBuilder thatSumTo(int sum) {
            this.sum = sum;
            return this;
        }

        TripletListBuilder withFactorsLessThanOrEqualTo(int maxFactor) {
            this.maxFactor = maxFactor;
            this.maxFactorSet = true;
            return this;
        }

        List<PythagoreanTriplet> build() {
            List<PythagoreanTriplet> result = new ArrayList<>();

            if (sum != null) {
                int n = sum;
                for (int a = 1; a < n / 3 + 1; a++) {
                    for (int b = a + 1; b <= (n - a) / 2; b++) {
                        int c = n - a - b;
                        if (c <= b || c > maxFactor) {
                            continue;
                        }
                        if ((long) a * a + (long) b * b == (long) c * c) {
                            result.add(new PythagoreanTriplet(a, b, c));
                        }
                    }
                }
            } else if (maxFactorSet) {
                for (int a = 1; a <= maxFactor; a++) {
                    for (int b = a + 1; b <= maxFactor; b++) {
                        long sq = (long) a * a + (long) b * b;
                        long c = (long) Math.sqrt((double) sq);
                        while (c * c < sq) {
                            c++;
                        }
                        while (c * c > sq) {
                            c--;
                        }
                        if (c * c == sq && c > b && c <= maxFactor) {
                            result.add(new PythagoreanTriplet(a, b, (int) c));
                        }
                    }
                }
            } else {
                throw new IllegalStateException("Either a sum or a maximum factor must be specified.");
            }

            return result;
        }

    }

