        List<String> result = new ArrayList<>();
        for (int i = startVerse; i <= endVerse; i++) {
            result.add(verse(i));
        }
        return String.join("\n\n", result);
    }

    String sing() {
        return verses(1, SUBJECTS.length - 1);
    }

