```java
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Deque;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

class Dominoes {

    private static final String NO_CHAIN_MESSAGE = "No domino chain found.";

    List<Domino> formChain(List<Domino> inputDominoes) throws ChainNotFoundException {
        if (inputDominoes.isEmpty()) {
            return new ArrayList<>();
        }

        List<Domino> dominoes = new ArrayList<>(inputDominoes);

        // Model the dominoes as a graph: every number of dots is a vertex and every domino is an edge
        // between the numbers on its two halves. A valid chain is a closed walk that uses every edge
        // exactly once (an Eulerian circuit).
        Map<Integer, Deque<Integer>> adjacency = buildAdjacency(dominoes);

        // Every time the walk enters a vertex it has to leave it again, so each vertex needs an even degree.
        if (hasVertexWithOddDegree(adjacency)) {
            throw new ChainNotFoundException(NO_CHAIN_MESSAGE);
        }

        List<Domino> chain = findCircuit(dominoes, adjacency);

        // The circuit only contains the dominoes that are connected to the first one.
        if (chain.size() != dominoes.size()) {
            throw new ChainNotFoundException(NO_CHAIN_MESSAGE);
        }

        return chain;
    }

    /**
     * Maps every number of dots to the indices of the dominoes having that number on one of their halves.
     * A domino with the same number on both halves is listed twice, so the size of each list equals the
     * degree of the corresponding vertex.
     */
    private static Map<Integer, Deque<Integer>> buildAdjacency(List<Domino> dominoes) {
        Map<Integer, Deque<Integer>> adjacency = new HashMap<>();
        for (int index = 0; index < dominoes.size(); index++) {
            Domino domino = dominoes.get(index);
            adjacency.computeIfAbsent(domino.getLeft(), dots -> new ArrayDeque<>()).add(index);
            adjacency.computeIfAbsent(domino.getRight(), dots -> new ArrayDeque<>()).add(index);
        }
        return adjacency;
    }

    private static boolean hasVertexWithOddDegree(Map<Integer, Deque<Integer>> adjacency) {
        return adjacency.values().stream().anyMatch(edges -> edges.size() % 2 != 0);
    }

    /**
     * Hierholzer's algorithm: walk along unused dominoes until stuck, then backtrack, splicing in any
     * further loops found on the way. Returns the dominoes (flipped where necessary) in chain order.
     * Only the dominoes connected to the first one are included.
     */
    private static List<Domino> findCircuit(List<Domino> dominoes, Map<Integer, Deque<Integer>> adjacency) {
        boolean[] used = new boolean[dominoes.size()];

        // The walk so far: the vertices visited, and the (possibly flipped) dominoes used to get from
        // each vertex to the next one. There is always one domino less than there are vertices.
        Deque<Integer> vertices = new ArrayDeque<>();
        Deque<Domino> walk = new ArrayDeque<>();

        // Dominoes in the order in which they are finalised, which is the reverse of the chain order.
        List<Domino> reversedChain = new ArrayList<>(dominoes.size());

        // Starting on the left half of the first domino makes that domino the first one of the chain.
        vertices.push(dominoes.get(0).getLeft());

        while (!vertices.isEmpty()) {
            int vertex = vertices.peek();
            int next = takeUnusedDomino(adjacency.get(vertex), used);

            if (next >= 0) {
                used[next] = true;
                Domino oriented = orient(dominoes.get(next), vertex);
                walk.push(oriented);
                vertices.push(oriented.getRight());
            } else {
                // Dead end: the last domino of the walk is final, so move it over to the result.
                vertices.pop();
                if (!walk.isEmpty()) {
                    reversedChain.add(walk.pop());
                }
            }
        }

        Collections.reverse(reversedChain);
        return reversedChain;
    }

    /**
     * Removes and returns the index of the next domino in the candidates that has not been used yet,
     * or -1 if there is none left.
     */
    private static int takeUnusedDomino(Deque<Integer> candidates, boolean[] used) {
        while (!candidates.isEmpty()) {
            int index = candidates.poll();
            if (!used[index]) {
                return index;
            }
        }
        return -1;
    }

    /**
     * Returns the domino as is if its left half shows the given number of dots, otherwise a flipped copy.
     */
    private static Domino orient(Domino domino, int leftDots) {
        return domino.getLeft() == leftDots ? domino : new Domino(domino.getRight(), domino.getLeft());
    }

}
