        // valid nodes of this list.
        unsafe {
            let new = NonNull::new_unchecked(Box::into_raw(new));
            match self.current {
                Some(cur) => {
                    let next = (*cur.as_ptr()).next;
                    (*new.as_ptr()).next = next;
                    (*cur.as_ptr()).next = Some(new);
                    match next {
