                None => {
                    self.list.front = Some(new);
                    self.list.back = Some(new);
                    self.current = Some(new);
                }
            }
        }
        self.list.len += 1;
    }

    pub fn insert_before(&mut self, element: T) {
        let new = Box::new(Node {
            elem: element,
            prev: None,
            next: self.current,
        });
        // SAFETY: Box::into_raw never returns null; the neighbouring nodes are
        // valid nodes of this list.
