use std::marker::PhantomData;
use std::ptr::NonNull;

// Safety invariants of this module:
// * Every `NonNull<Node<T>>` reachable from a `LinkedList` (via `head`, `tail`,
//   or any node's `prev`/`next`) points to a live node allocated with `Box`
