impl<T> Drop for LinkedList<T> {
    fn drop(&mut self) {
        let mut cur = self.head;
        self.head = None;
        self.tail = None;
        self.len = 0;
        while let Some(node) = cur {
            // Safety: by the list invariants `node` is a live, uniquely owned
            // Box allocation; we free each node exactly once, reading `next`
            // before the node is dropped.
            let boxed = unsafe { Box::from_raw(node.as_ptr()) };
            cur = boxed.next;
            drop(boxed);
        }
    }
}

// the cursor is expected to act as if it is at the position of an element
// and it also has to work with and be able to insert into an empty list.
impl<T> Cursor<'_, T> {
    /// Take a mutable reference to the current element
    pub fn peek_mut(&mut self) -> Option<&mut T> {
        // Safety: `current` points to a live node of the list we mutably
        // borrow; the returned reference is tied to `&mut self`.
        self.current
            .map(|node| unsafe { &mut (*node.as_ptr()).element })
    }

    /// Move one position forward (towards the back) and
    /// return a reference to the new position
    #[allow(clippy::should_implement_trait)]
    pub fn next(&mut self) -> Option<&mut T> {
        let cur = self.current?;
        // Safety: `cur` is a live node of the list.
        let next = unsafe { (*cur.as_ptr()).next };
        if next.is_some() {
            self.current = next;
        }
        // At the end of the list we stay in place and report `None`.
        if next.is_some() {
            self.peek_mut()
        } else {
            None
        }
    }

    /// Move one position backward (towards the front) and
    /// return a reference to the new position
    pub fn prev(&mut self) -> Option<&mut T> {
        let cur = self.current?;
        // Safety: `cur` is a live node of the list.
        let prev = unsafe { (*cur.as_ptr()).prev };
        if prev.is_some() {
            self.current = prev;
            self.peek_mut()
        } else {
            None
        }
    }

    /// Remove and return the element at the current position and move the cursor
    /// to the neighboring element that's closest to the back. This can be
    /// either the next or previous position.
    pub fn take(&mut self) -> Option<T> {
        let cur = self.current?;
        // Safety: `cur` is a live node owned by the list. We unlink it from
        // its neighbours (which are live nodes too) and then take back
        // ownership of the allocation exactly once.
        unsafe {
            let boxed = Box::from_raw(cur.as_ptr());
            match boxed.prev {
                Some(prev) => (*prev.as_ptr()).next = boxed.next,
                None => self.list.head = boxed.next,
            }
            match boxed.next {
                Some(next) => (*next.as_ptr()).prev = boxed.prev,
                None => self.list.tail = boxed.prev,
            }
            self.list.len -= 1;
            self.current = boxed.next.or(boxed.prev);
            let node = *boxed;
            Some(node.element)
        }
    }

    pub fn insert_after(&mut self, _element: T) {
        let element = _element;
        match self.current {
            None => self.insert_into_empty(element),
            Some(cur) => {
                // Safety: `cur` and its `next` (if any) are live nodes of the
                // list; the new node is freshly allocated and non-null.
                unsafe {
                    let next = (*cur.as_ptr()).next;
                    let new = Self::alloc(Node {
                        element,
                        prev: Some(cur),
                        next,
                    });
                    match next {
                        Some(n) => (*n.as_ptr()).prev = Some(new),
                        None => self.list.tail = Some(new),
                    }
                    (*cur.as_ptr()).next = Some(new);
                }
                self.list.len += 1;
            }
        }
    }

    pub fn insert_before(&mut self, _element: T) {
        let element = _element;
        match self.current {
            None => self.insert_into_empty(element),
            Some(cur) => {
                // Safety: `cur` and its `prev` (if any) are live nodes of the
                // list; the new node is freshly allocated and non-null.
                unsafe {
                    let prev = (*cur.as_ptr()).prev;
                    let new = Self::alloc(Node {
                        element,
                        prev,
                        next: Some(cur),
                    });
                    match prev {
                        Some(p) => (*p.as_ptr()).next = Some(new),
                        None => self.list.head = Some(new),
                    }
                    (*cur.as_ptr()).prev = Some(new);
                }
                self.list.len += 1;
            }
        }
    }

    fn alloc(node: Node<T>) -> NonNull<Node<T>> {
        // Box::into_raw never returns null.
        NonNull::from(Box::leak(Box::new(node)))
    }

    /// Insert the first element into an empty list and point the cursor at it.
    fn insert_into_empty(&mut self, element: T) {
        debug_assert!(self.list.head.is_none() && self.list.tail.is_none());
        let new = Self::alloc(Node {
            element,
            prev: None,
            next: None,
        });
        self.list.head = Some(new);
        self.list.tail = Some(new);
        self.list.len = 1;
        self.current = Some(new);
    }
}

impl<'a, T> Iterator for Iter<'a, T> {
    type Item = &'a T;

    fn next(&mut self) -> Option<&'a T> {
        self.next.map(|node| {
            // Safety: the node is live for as long as the list is borrowed
            // (lifetime 'a), and no mutation can happen during that time.
            let node = unsafe { &*node.as_ptr() };
            self.next = node.next;
            &node.element
        })
    }
}
