// this module adds some functionality based on the required implementations
// here like: `LinkedList::pop_back` or `Clone for LinkedList<T>`
// You are free to use anything in it, but it's mainly for the test framework.
mod pre_implemented;

use std::marker::PhantomData;
use std::ptr::NonNull;

// # Safety-critical invariants
//
// The following invariants hold for every `LinkedList<T>` whenever control
// is outside of a method of this module:
//
// 1. Every node reachable from `front` (following `next`) was created by
//    `Box::new` + `Box::leak` and is owned exclusively by the list.
//    No node is shared with any other list.
// 2. `front` is `None` iff `back` is `None` iff `len == 0`.
// 3. `front.prev == None` and `back.next == None`.
// 4. For every node `n` with `n.next == Some(m)`, `m.prev == Some(n)` and
//    vice versa.
// 5. Following `next` from `front` visits exactly `len` nodes and ends at `back`.
//
// A `Cursor` additionally upholds:
//
// 6. `current` is `None` only if the list is empty; otherwise it points to a
//    node that is currently part of the list.
//
// Since a `Cursor` holds a `&mut LinkedList<T>` and an `Iter` holds a shared
// borrow of the list, the borrow checker guarantees that the nodes cannot be
// modified from elsewhere while those are alive.

struct Node<T> {
    element: T,
    prev: Option<NonNull<Node<T>>>,
    next: Option<NonNull<Node<T>>>,
}

impl<T> Node<T> {
    /// Allocate a new node on the heap and return a pointer to it.
    /// The caller becomes responsible for eventually reclaiming the allocation
    /// with `Box::from_raw`.
    fn alloc(
        element: T,
        prev: Option<NonNull<Node<T>>>,
        next: Option<NonNull<Node<T>>>,
    ) -> NonNull<Node<T>> {
        let boxed = Box::new(Node {
            element,
            prev,
            next,
        });
        NonNull::from(Box::leak(boxed))
    }
}

pub struct LinkedList<T> {
    front: Option<NonNull<Node<T>>>,
    back: Option<NonNull<Node<T>>>,
    len: usize,
    // Signals to the compiler (drop check, variance) that we own `Node<T>`s.
    // `Box<Node<T>>` is covariant in `T`, so the list is covariant too.
    _marker: PhantomData<Box<Node<T>>>,
}

pub struct Cursor<'a, T> {
    list: &'a mut LinkedList<T>,
    current: Option<NonNull<Node<T>>>,
}

pub struct Iter<'a, T> {
    next: Option<NonNull<Node<T>>>,
    _marker: PhantomData<&'a T>,
}

// SAFETY: A `LinkedList<T>` owns its elements exclusively (like a `Vec<T>` or
// `Box<T>`), so sending it to another thread is the same as sending the `T`s.
unsafe impl<T: Send> Send for LinkedList<T> {}
// SAFETY: Shared access to a `LinkedList<T>` only hands out `&T`.
unsafe impl<T: Sync> Sync for LinkedList<T> {}

// SAFETY: A `Cursor` is semantically a `&mut LinkedList<T>`, which is `Send`
// iff the list is `Send`, i.e. iff `T: Send`.
unsafe impl<T: Send> Send for Cursor<'_, T> {}
// SAFETY: A `&Cursor` exposes no access to the elements at all; the bound
// mirrors that of `&mut LinkedList<T>`.
unsafe impl<T: Sync> Sync for Cursor<'_, T> {}

// SAFETY: An `Iter` is semantically a `&'a LinkedList<T>`/`&'a [T]`, which is
// `Send` iff `T: Sync`.
unsafe impl<T: Sync> Send for Iter<'_, T> {}
// SAFETY: Same as above, an `Iter` only hands out `&T`.
unsafe impl<T: Sync> Sync for Iter<'_, T> {}

impl<T> LinkedList<T> {
    pub fn new() -> Self {
        LinkedList {
            front: None,
            back: None,
            len: 0,
            _marker: PhantomData,
        }
    }

    // You may be wondering why it's necessary to have is_empty()
    // when it can easily be determined from len().
    // It's good custom to have both because len() can be expensive for some types,
    // whereas is_empty() is almost always cheap.
    // (Also ask yourself whether len() is expensive for LinkedList)
    pub fn is_empty(&self) -> bool {
        self.len == 0
    }

    pub fn len(&self) -> usize {
        self.len
    }

    /// Return a cursor positioned on the front element
    pub fn cursor_front(&mut self) -> Cursor<'_, T> {
        // Invariant 6: `front` is `None` only if the list is empty.
        Cursor {
            current: self.front,
            list: self,
        }
    }

    /// Return a cursor positioned on the back element
    pub fn cursor_back(&mut self) -> Cursor<'_, T> {
        // Invariant 6: `back` is `None` only if the list is empty.
        Cursor {
            current: self.back,
            list: self,
        }
    }

    /// Return an iterator that moves from front to back
    pub fn iter(&self) -> Iter<'_, T> {
        Iter {
            next: self.front,
            _marker: PhantomData,
        }
    }
}

impl<T> Drop for LinkedList<T> {
    fn drop(&mut self) {
        // Removing every element through the cursor frees each node exactly
        // once. The list stays consistent after every removal, so even if an
        // element's destructor panics nothing is freed twice.
        let mut cursor = self.cursor_front();
        while cursor.take().is_some() {}
    }
}

// the cursor is expected to act as if it is at the position of an element
// and it also has to work with and be able to insert into an empty list.
impl<T> Cursor<'_, T> {
    /// Take a mutable reference to the current element
    pub fn peek_mut(&mut self) -> Option<&mut T> {
        let node = self.current?;
        // SAFETY: By invariant 6 `node` points to a live node of the list.
        // We hold `&mut LinkedList<T>` (and `&mut self`), so there is no other
        // access to this node, and the returned reference is bound to the
        // lifetime of `&mut self`, so the cursor can't be used to create
        // aliasing references while it is alive.
        Some(unsafe { &mut (*node.as_ptr()).element })
    }

    /// Move one position forward (towards the back) and
    /// return a reference to the new position
    #[allow(clippy::should_implement_trait)]
    pub fn next(&mut self) -> Option<&mut T> {
        let current = self.current?;
        // SAFETY: By invariant 6 `current` points to a live node of the list,
        // and we have exclusive access to the list.
        let next = unsafe { (*current.as_ptr()).next }?;
        // `next` is a node of the list by invariant 4.
        self.current = Some(next);
        self.peek_mut()
    }

    /// Move one position backward (towards the front) and
    /// return a reference to the new position
    pub fn prev(&mut self) -> Option<&mut T> {
        let current = self.current?;
        // SAFETY: By invariant 6 `current` points to a live node of the list,
        // and we have exclusive access to the list.
        let prev = unsafe { (*current.as_ptr()).prev }?;
        // `prev` is a node of the list by invariant 4.
        self.current = Some(prev);
        self.peek_mut()
    }

    /// Remove and return the element at the current position and move the cursor
    /// to the neighboring element that's closest to the back. This can be
    /// either the next or previous position.
    pub fn take(&mut self) -> Option<T> {
        let node_ptr = self.current?;

        // SAFETY: By invariant 1 and 6 the node was allocated via `Box` and is
        // owned by the list. We unlink it from the list below, so after this
        // function nobody holds a pointer to it any more; thus taking back
        // ownership here is sound and happens exactly once.
        let node = unsafe { Box::from_raw(node_ptr.as_ptr()) };
        let Node {
            element,
            prev,
            next,
        } = *node;

        // Fix up the neighbours (invariants 3 and 4).
        match prev {
            // SAFETY: `p` is a live node of the list (invariant 4) and we have
            // exclusive access to the list.
            Some(p) => unsafe { (*p.as_ptr()).next = next },
            None => self.list.front = next,
        }
        match next {
            // SAFETY: `n` is a live node of the list (invariant 4) and we have
            // exclusive access to the list.
            Some(n) => unsafe { (*n.as_ptr()).prev = prev },
            None => self.list.back = prev,
        }
        self.list.len -= 1;

        // Prefer the neighbour closest to the back. If both are `None`, the
        // list is now empty (invariant 2) and the cursor has no position.
        self.current = next.or(prev);

        Some(element)
    }

    pub fn insert_after(&mut self, element: T) {
        match self.current {
            None => self.insert_into_empty(element),
            Some(current) => {
                // SAFETY: By invariant 6 `current` points to a live node of
                // the list and we have exclusive access to the list.
                let next = unsafe { (*current.as_ptr()).next };
                let new = Node::alloc(element, Some(current), next);

                // SAFETY: Same as above for `current`.
                unsafe { (*current.as_ptr()).next = Some(new) };
                match next {
                    // SAFETY: `n` is a live node of the list (invariant 4).
                    Some(n) => unsafe { (*n.as_ptr()).prev = Some(new) },
                    None => self.list.back = Some(new),
                }
                self.list.len += 1;
            }
        }
    }

    pub fn insert_before(&mut self, element: T) {
        match self.current {
            None => self.insert_into_empty(element),
            Some(current) => {
                // SAFETY: By invariant 6 `current` points to a live node of
                // the list and we have exclusive access to the list.
                let prev = unsafe { (*current.as_ptr()).prev };
                let new = Node::alloc(element, prev, Some(current));

                // SAFETY: Same as above for `current`.
                unsafe { (*current.as_ptr()).prev = Some(new) };
                match prev {
                    // SAFETY: `p` is a live node of the list (invariant 4).
                    Some(p) => unsafe { (*p.as_ptr()).next = Some(new) },
                    None => self.list.front = Some(new),
                }
                self.list.len += 1;
            }
        }
    }

    /// Insert the first element into an empty list and put the cursor on it.
    fn insert_into_empty(&mut self, element: T) {
        // By invariant 6, `current == None` implies the list is empty.
        debug_assert!(self.list.is_empty());
        let new = Node::alloc(element, None, None);
        self.list.front = Some(new);
        self.list.back = Some(new);
        self.list.len = 1;
        self.current = Some(new);
    }
}

impl<'a, T> Iterator for Iter<'a, T> {
    type Item = &'a T;

    fn next(&mut self) -> Option<&'a T> {
        let node = self.next?;
        // SAFETY: `Iter<'a, T>` was created from a `&'a LinkedList<T>`, so the
        // list can't be mutated or dropped for the lifetime `'a`. `node` is a
        // live node of that list (invariants 1, 4), and only shared references
        // to it exist during `'a`.
        let node_ref: &'a Node<T> = unsafe { &*node.as_ptr() };
        self.next = node_ref.next;
        Some(&node_ref.element)
    }
}
