// this module adds some functionality based on the required implementations
// here like: `LinkedList::pop_back` or `Clone for LinkedList<T>`
// You are free to use anything in it, but it's mainly for the test framework.
mod pre_implemented;

use std::marker::PhantomData;
use std::mem;
use std::ptr::NonNull;

// # Safety-critical invariants
//
// A `LinkedList<T>` is a chain of heap-allocated `Node<T>`s that point at each other through
// raw pointers, so the borrow checker can't verify anything about them. Instead, the code in
// this file upholds the invariants below. They hold whenever control is handed back to the
// user, and every `unsafe` block relies on nothing but them and on the documented contracts of
// the private `unsafe fn`s (`LinkedList::link_between` and `LinkedList::unlink_node`).
//
// 1. Ownership: Every node is allocated by `Box::new` (in `link_between`) and is owned by
//    exactly one list. It is freed exactly once, by turning it back into a `Box` (in
//    `unlink_node`) at the very moment it is removed from its list. A pointer to a node that
//    isn't (or isn't any more) linked into a list is never dereferenced.
// 2. Structure: `front` and `back` are `None` if and only if `len == 0`. Otherwise, `front` is
//    the first and `back` the last node. Following the `next` links from `front` visits `len`
//    different nodes and ends at `back`; following the `prev` links from `back` visits the same
//    nodes in reverse order and ends at `front`. In particular, `front.prev` and `back.next`
//    are `None`, and `a.next == Some(b)` if and only if `b.prev == Some(a)`.
// 3. Cursor: `Cursor::current` is `None` if and only if the list is empty, otherwise it is a
//    node of `Cursor::list`. The cursor holds the only (mutable) borrow of its list, so nobody
//    else can modify the list, or unlink and free that node, while the cursor exists.
// 4. Iter: `Iter::next_node` is `None` or a node of the list that the iterator borrows
//    (immutably) for `'a`, and `Iter::remaining` is the number of nodes reachable from it.
//    Nobody can modify the list during `'a`, so these nodes stay alive and unchanged.
//
// To respect the aliasing rules, nodes are only accessed through raw pointers
// (`(*ptr).field`). The only references we create are `&mut` references to single elements
// (which are tied to the borrow of the cursor) and, in `Iter` (where the whole list is borrowed
// immutably), shared references to nodes.

/// A doubly linked list.
///
/// It can be inspected with an [`Iter`] (see [`LinkedList::iter`]) and modified with a
/// [`Cursor`] (see [`LinkedList::cursor_front`] and [`LinkedList::cursor_back`]).
pub struct LinkedList<T> {
    /// The first node, `None` if the list is empty.
    front: Link<T>,
    /// The last node, `None` if the list is empty.
    back: Link<T>,
    /// The number of nodes in the list.
    len: usize,
    // The list owns its nodes (and thereby its elements), which this tells the drop checker.
    // `Box<Node<T>>` is covariant over `T`, just like the `NonNull`s above, so the list is too.
    _owns_nodes: PhantomData<Box<Node<T>>>,
}

/// A link to another node, `None` marks the end of the chain.
type Link<T> = Option<NonNull<Node<T>>>;

/// A heap-allocated node of a `LinkedList`, owned by the list it is linked into.
struct Node<T> {
    element: T,
    /// The node before this one (closer to the front).
    prev: Link<T>,
    /// The node after this one (closer to the back).
    next: Link<T>,
}

/// A cursor into a [`LinkedList`], used to modify it.
///
/// The cursor always sits *on* an element (or on nothing, if the list is empty), it never moves
/// beyond the ends of the list. As long as it exists, it has exclusive access to the list.
pub struct Cursor<'a, T> {
    /// The list the cursor works on. Being a `&mut` also makes the cursor invariant over `T`.
    list: &'a mut LinkedList<T>,
    /// The node the cursor sits on, `None` if the list is empty.
    current: Link<T>,
}

/// An iterator over the elements of a [`LinkedList`], from front to back.
///
/// It borrows the list, so the list can't be modified while the iterator (or any element
/// reference it returned) is alive.
pub struct Iter<'a, T> {
    /// The node that is yielded next, `None` once the iterator is exhausted.
    next_node: Link<T>,
    /// The number of elements that are yet to be yielded.
    remaining: usize,
    // Ties the iterator to the borrow of the list (and its elements) for `'a`, and makes it
    // covariant over `'a` and `T`.
    _borrows_list: PhantomData<&'a T>,
}

// SAFETY: A `LinkedList<T>` exclusively owns its nodes and thereby its elements (just like a
// `Vec<T>` does) and shares no state with any other list. Sending the list to another thread
// therefore just sends its elements there, which is fine if `T: Send`.
unsafe impl<T: Send> Send for LinkedList<T> {}

// SAFETY: Through a shared reference, a list only gives out shared references to its elements
// and it contains no interior mutability itself. So sharing the list between threads just
// shares `&T`s, which is fine if `T: Sync`.
unsafe impl<T: Sync> Sync for LinkedList<T> {}

// SAFETY: A `Cursor` is nothing but a `&mut LinkedList<T>` together with a position in that
// list, so it can be sent / shared under the same conditions as such a reference:
// `T: Send` / `T: Sync`.
unsafe impl<T: Send> Send for Cursor<'_, T> {}
unsafe impl<T: Sync> Sync for Cursor<'_, T> {}

// SAFETY: An `Iter` is nothing but a `&LinkedList<T>` together with a position in that list,
// so it can be sent / shared under the same conditions as such a reference: `T: Sync`.
unsafe impl<T: Sync> Send for Iter<'_, T> {}
unsafe impl<T: Sync> Sync for Iter<'_, T> {}

impl<T> LinkedList<T> {
    pub fn new() -> Self {
        LinkedList {
            front: None,
            back: None,
            len: 0,
            _owns_nodes: PhantomData,
        }
    }

    // You may be wondering why it's necessary to have is_empty()
    // when it can easily be determined from len().
    // It's good custom to have both because len() can be expensive for some types,
    // whereas is_empty() is almost always cheap.
    // (Also ask yourself whether len() is expensive for LinkedList)
    pub fn is_empty(&self) -> bool {
        self.len == 0
    }

    pub fn len(&self) -> usize {
        // The length is kept up to date by every insertion and removal, so this is O(1).
        self.len
    }

    /// Return a cursor positioned on the front element
    pub fn cursor_front(&mut self) -> Cursor<'_, T> {
        let current = self.front;
        Cursor {
            list: self,
            current,
        }
    }

    /// Return a cursor positioned on the back element
    pub fn cursor_back(&mut self) -> Cursor<'_, T> {
        let current = self.back;
        Cursor {
            list: self,
            current,
        }
    }

    /// Return an iterator that moves from front to back
    pub fn iter(&self) -> Iter<'_, T> {
        Iter {
            next_node: self.front,
            remaining: self.len,
            _borrows_list: PhantomData,
        }
    }
}

// The primitives all modifications of the list are built from. They are only called by the
// methods of `Cursor`.
impl<T> LinkedList<T> {
    /// Allocates a new node holding `element`, links it in between `prev` and `next` and
    /// returns a pointer to it.
    ///
    /// `prev == None` inserts the node at the very front of the list, `next == None` at the
    /// very back.
    ///
    /// # Safety
    ///
    /// `prev` and `next` must be neighbors in `self`. That is:
    /// * if `prev` is `Some`, it points to a node of `self` whose `next` link is `next`,
    /// * if `next` is `Some`, it points to a node of `self` whose `prev` link is `prev`,
    /// * if both are `None`, `self` must be empty.
    unsafe fn link_between(
        &mut self,
        prev: Link<T>,
        next: Link<T>,
        element: T,
    ) -> NonNull<Node<T>> {
        // Ownership of the allocation is handed over to the list (invariant 1).
        let node = NonNull::from(Box::leak(Box::new(Node {
            element,
            prev,
            next,
        })));

        match prev {
            // SAFETY: By the contract of this function, `prev` is a node of `self`, so it is
            // alive. It is not `node`, which has just been allocated. We hold `&mut self`, so
            // nobody else is accessing it.
            Some(prev) => unsafe { (*prev.as_ptr()).next = Some(node) },
            // There is no node in front of the new one, so it becomes the new front.
            None => self.front = Some(node),
        }
        match next {
            // SAFETY: Same as above, for `next`.
            Some(next) => unsafe { (*next.as_ptr()).prev = Some(node) },
            // There is no node behind the new one, so it becomes the new back.
            None => self.back = Some(node),
        }

        self.len += 1;
        node
    }

    /// Removes `node` from `self` and returns it, which hands the ownership of its allocation
    /// to the caller. The links of the returned node are stale, but they still point to its
    /// former neighbors, which remain linked into the list.
    ///
    /// # Safety
    ///
    /// `node` must point to a node that is currently linked into `self`.
    unsafe fn unlink_node(&mut self, node: NonNull<Node<T>>) -> Box<Node<T>> {
        // SAFETY: By the contract of this function, `node` is linked into `self` and thereby
        // alive, and it was allocated by a `Box` in `link_between`. The list is its only owner
        // and the node is unlinked below, so the list never touches this pointer again and the
        // new `Box` is the sole owner from now on (invariant 1).
        let boxed = unsafe { Box::from_raw(node.as_ptr()) };

        match boxed.prev {
            // SAFETY: `prev` is a node of `self` (invariant 2), so it is alive, and it is not
            // `node` itself. We hold `&mut self`, so nobody else is accessing it.
            Some(prev) => unsafe { (*prev.as_ptr()).next = boxed.next },
            // The removed node was the front, so its successor becomes the new front.
            None => self.front = boxed.next,
        }
        match boxed.next {
            // SAFETY: Same as above, for `next`.
            Some(next) => unsafe { (*next.as_ptr()).prev = boxed.prev },
            // The removed node was the back, so its predecessor becomes the new back.
            None => self.back = boxed.prev,
        }

        self.len -= 1;
        boxed
    }
}

impl<T> Drop for LinkedList<T> {
    fn drop(&mut self) {
        // If the destructor of an element panics, this guard drops the remaining elements while
        // unwinding, instead of leaking them.
        struct DropGuard<'a, T>(&'a mut LinkedList<T>);

        impl<T> Drop for DropGuard<'_, T> {
            fn drop(&mut self) {
                // This only runs after a panic, so if another destructor panics now, the whole
                // process aborts.
                while self.0.cursor_front().take().is_some() {}
            }
        }

        let guard = DropGuard(self);
        // Remove the elements one by one, from front to back, and drop them. This is a loop
        // instead of a recursion, so even very long lists can't overflow the stack.
        while guard.0.cursor_front().take().is_some() {}
        // The list is empty now, so there is nothing left for the guard to do.
        mem::forget(guard);
    }
}

// the cursor is expected to act as if it is at the position of an element
// and it also has to work with and be able to insert into an empty list.
impl<T> Cursor<'_, T> {
    /// Take a mutable reference to the current element
    ///
    /// Returns `None` if the list is empty.
    pub fn peek_mut(&mut self) -> Option<&mut T> {
        let node = self.current?;
        // SAFETY: `node` is a node of `self.list` (invariant 3), so it is alive. The returned
        // reference borrows the cursor, and with it the list, mutably for as long as it lives.
        // So the node can't be unlinked or accessed in any other way during that time, which
        // makes the reference unique.
        Some(unsafe { &mut (*node.as_ptr()).element })
    }

    /// Move one position forward (towards the back) and
    /// return a reference to the new position
    ///
    /// If the cursor already is at the back, it stays where it is and `None` is returned.
    #[allow(clippy::should_implement_trait)]
    pub fn next(&mut self) -> Option<&mut T> {
        let (_, next) = self.neighbors()?;
        // `next` is a node of the list as well (invariant 2).
        self.current = Some(next?);
        self.peek_mut()
    }

    /// Move one position backward (towards the front) and
    /// return a reference to the new position
    ///
    /// If the cursor already is at the front, it stays where it is and `None` is returned.
    pub fn prev(&mut self) -> Option<&mut T> {
        let (prev, _) = self.neighbors()?;
        // `prev` is a node of the list as well (invariant 2).
        self.current = Some(prev?);
        self.peek_mut()
    }

    /// Remove and return the element at the current position and move the cursor
    /// to the neighboring element that's closest to the back. This can be
    /// either the next or previous position.
    ///
    /// Returns `None` if the list is empty.
    pub fn take(&mut self) -> Option<T> {
        let current = self.current?;
        // SAFETY: `current` is a node of `self.list` (invariant 3).
        let node = unsafe { self.list.unlink_node(current) };
        // The neighbors of the removed node are still linked into the list, so the cursor can
        // move onto one of them. If there is none, the list is empty now, and so is the cursor.
        self.current = node.next.or(node.prev);
        Some(node.element)
    }

    /// Insert a new element after the current one.
    ///
    /// The cursor stays on its current element, unless the list was empty: Then the cursor
    /// moves onto the new element.
    pub fn insert_after(&mut self, element: T) {
        let (prev, next) = match self.neighbors() {
            Some((_, next)) => (self.current, next),
            None => (None, None),
        };
        // SAFETY: If the list isn't empty, `prev` is the current node (a node of `self.list`
        // by invariant 3) and `next` is its `next` link, so they are neighbors. Otherwise, the
        // list is empty (invariant 3) and both are `None`.
        let node = unsafe { self.list.link_between(prev, next, element) };
        if self.current.is_none() {
            // The new node is the only one in the list, so the cursor moves onto it
            // (invariant 3).
            self.current = Some(node);
        }
    }

    /// Insert a new element before the current one.
    ///
    /// The cursor stays on its current element, unless the list was empty: Then the cursor
    /// moves onto the new element.
    pub fn insert_before(&mut self, element: T) {
        let (prev, next) = match self.neighbors() {
            Some((prev, _)) => (prev, self.current),
            None => (None, None),
        };
        // SAFETY: If the list isn't empty, `next` is the current node (a node of `self.list`
        // by invariant 3) and `prev` is its `prev` link, so they are neighbors. Otherwise, the
        // list is empty (invariant 3) and both are `None`.
        let node = unsafe { self.list.link_between(prev, next, element) };
        if self.current.is_none() {
            // The new node is the only one in the list, so the cursor moves onto it
            // (invariant 3).
            self.current = Some(node);
        }
    }
}

impl<T> Cursor<'_, T> {
    /// Returns the `prev` and `next` links of the current node, or `None` if the list is empty.
    fn neighbors(&self) -> Option<(Link<T>, Link<T>)> {
        let node = self.current?;
        // SAFETY: `node` is a node of `self.list` (invariant 3), so it is alive, and nobody can
        // be modifying it concurrently, as the cursor holds the only borrow of the list. We just
        // copy the two links out of it.
        Some(unsafe { ((*node.as_ptr()).prev, (*node.as_ptr()).next) })
    }
}

impl<'a, T> Iterator for Iter<'a, T> {
    type Item = &'a T;

    fn next(&mut self) -> Option<&'a T> {
        let node = self.next_node?;
        // SAFETY: `node` is a node of the list that this iterator borrows immutably for `'a`
        // (invariant 4). That list can't be modified or dropped during `'a`, so the node stays
        // alive and unchanged, which makes it fine to create a shared reference to it that
        // lives for `'a`.
        let node: &'a Node<T> = unsafe { &*node.as_ptr() };
        self.next_node = node.next;
        self.remaining -= 1;
        Some(&node.element)
    }

    fn size_hint(&self) -> (usize, Option<usize>) {
        (self.remaining, Some(self.remaining))
    }
}
