// this module adds some functionality based on the required implementations
// here like: `LinkedList::pop_back` or `Clone for LinkedList<T>`
// You are free to use anything in it, but it's mainly for the test framework.
mod pre_implemented;

use std::marker::PhantomData;
use std::ptr::NonNull;

struct Node<T> {
    element: T,
    prev: Option<NonNull<Node<T>>>,
    next: Option<NonNull<Node<T>>>,
}

/// Invariants:
/// - `front` and `back` are both `None` iff the list is empty (`len == 0`).
/// - Every node pointer reachable from `front` via `next` was created by
///   `Box::into_raw` (through `Box::leak`) and is owned exclusively by this list.
/// - For every node `n`, `n.next.prev == n` and `n.prev.next == n`.
/// - `front.prev == None` and `back.next == None`.
/// - `len` equals the number of nodes in the list.
pub struct LinkedList<T> {
    front: Option<NonNull<Node<T>>>,
    back: Option<NonNull<Node<T>>>,
    len: usize,
    // Signals ownership of `Node<T>` values (for drop check) and makes the
    // list covariant over `T`.
    _marker: PhantomData<Box<Node<T>>>,
}

/// Invariant: `current` is either `None` (only possible when the list is empty,
/// or ... never otherwise) or points to a valid node owned by `list`.
/// If the list is non-empty, `current` is always `Some`.
pub struct Cursor<'a, T> {
    list: &'a mut LinkedList<T>,
    current: Option<NonNull<Node<T>>>,
}

pub struct Iter<'a, T> {
    next: Option<NonNull<Node<T>>>,
    _marker: PhantomData<&'a T>,
}

impl<T> LinkedList<T> {
    pub fn new() -> Self {
        LinkedList {
            front: None,
            back: None,
            len: 0,
            _marker: PhantomData,
        }
    }

    // You may be wondering why it's necessary to have is_empty()
    // when it can easily be determined from len().
    // It's good custom to have both because len() can be expensive for some types,
    // whereas is_empty() is almost always cheap.
    // (Also ask yourself whether len() is expensive for LinkedList)
    pub fn is_empty(&self) -> bool {
        self.len == 0
    }

    pub fn len(&self) -> usize {
        self.len
    }

    /// Return a cursor positioned on the front element
    pub fn cursor_front(&mut self) -> Cursor<'_, T> {
        let current = self.front;
        Cursor {
            list: self,
            current,
        }
    }

    /// Return a cursor positioned on the back element
    pub fn cursor_back(&mut self) -> Cursor<'_, T> {
        let current = self.back;
        Cursor {
            list: self,
            current,
        }
    }

    /// Return an iterator that moves from front to back
    pub fn iter(&self) -> Iter<'_, T> {
        Iter {
            next: self.front,
            _marker: PhantomData,
        }
    }
}

impl<T> Default for LinkedList<T> {
    fn default() -> Self {
        Self::new()
    }
}

impl<T> Drop for LinkedList<T> {
    fn drop(&mut self) {
        let mut cursor = self.cursor_front();
        // `take` removes and returns each element, dropping it here.
        while cursor.take().is_some() {}
    }
}

// SAFETY: The list owns its elements exclusively (like a `Vec<T>`), and exposes
// no interior mutability, so sending the list sends the owned `T`s.
unsafe impl<T: Send> Send for LinkedList<T> {}
// SAFETY: Shared references to the list only give shared references to `T`.
unsafe impl<T: Sync> Sync for LinkedList<T> {}

// SAFETY: A cursor is a unique borrow of the list; equivalent to `&mut LinkedList<T>`.
unsafe impl<T: Send> Send for Cursor<'_, T> {}
unsafe impl<T: Sync> Sync for Cursor<'_, T> {}

// SAFETY: An iterator only hands out `&T`, equivalent to `&LinkedList<T>`.
unsafe impl<T: Sync> Send for Iter<'_, T> {}
unsafe impl<T: Sync> Sync for Iter<'_, T> {}

// the cursor is expected to act as if it is at the position of an element
// and it also has to work with and be able to insert into an empty list.
impl<T> Cursor<'_, T> {
    /// Take a mutable reference to the current element
    pub fn peek_mut(&mut self) -> Option<&mut T> {
        // SAFETY: `current` points to a valid node owned by the list, and we hold
        // a unique borrow of the list through `&mut self`, so no aliasing occurs.
        self.current
            .map(|mut node| unsafe { &mut node.as_mut().element })
    }

    /// Move one position forward (towards the back) and
    /// return a reference to the new position
    #[allow(clippy::should_implement_trait)]
    pub fn next(&mut self) -> Option<&mut T> {
        // SAFETY: `current` is a valid node; its `next` pointer is either None
        // or a valid node of the same list.
        let next = unsafe { self.current?.as_ref().next }?;
        self.current = Some(next);
        self.peek_mut()
    }

    /// Move one position backward (towards the front) and
    /// return a reference to the new position
    pub fn prev(&mut self) -> Option<&mut T> {
        // SAFETY: same as in `next`.
        let prev = unsafe { self.current?.as_ref().prev }?;
        self.current = Some(prev);
        self.peek_mut()
    }

    /// Remove and return the element at the current position and move the cursor
    /// to the neighboring element that's closest to the back. This can be
    /// either the next or previous position.
    pub fn take(&mut self) -> Option<T> {
        let node_ptr = self.current?;
        // SAFETY: `node_ptr` was created by `Box::leak` in an insert method and
        // is still owned by the list; we are about to unlink it, so reclaiming
        // the box is sound and happens exactly once.
        let node = unsafe { Box::from_raw(node_ptr.as_ptr()) };

        // SAFETY: neighbors (if any) are valid nodes of this list, distinct
        // from `node_ptr`, and we have unique access to the list.
        unsafe {
            match node.prev {
                Some(mut prev) => prev.as_mut().next = node.next,
                None => self.list.front = node.next,
            }
            match node.next {
                Some(mut next) => next.as_mut().prev = node.prev,
                None => self.list.back = node.prev,
            }
        }

        self.list.len -= 1;
        self.current = node.next.or(node.prev);
        Some(node.element)
    }

    pub fn insert_after(&mut self, element: T) {
        let new = Box::new(Node {
            element,
            prev: self.current,
            next: None,
        });
        let new_ptr = NonNull::from(Box::leak(new));

        match self.current {
            None => {
                // Empty list: the new node becomes everything.
                self.list.front = Some(new_ptr);
                self.list.back = Some(new_ptr);
                self.current = Some(new_ptr);
            }
            Some(mut cur) => {
                // SAFETY: `cur` is a valid node of this list; `next` (if any)
                // is also valid. We have unique access to the list.
                unsafe {
                    let next = cur.as_ref().next;
                    (*new_ptr.as_ptr()).next = next;
                    cur.as_mut().next = Some(new_ptr);
                    match next {
                        Some(mut next) => next.as_mut().prev = Some(new_ptr),
                        None => self.list.back = Some(new_ptr),
                    }
                }
            }
        }
        self.list.len += 1;
    }

    pub fn insert_before(&mut self, element: T) {
        let new = Box::new(Node {
            element,
            prev: None,
            next: self.current,
        });
        let new_ptr = NonNull::from(Box::leak(new));

        match self.current {
            None => {
                self.list.front = Some(new_ptr);
                self.list.back = Some(new_ptr);
                self.current = Some(new_ptr);
            }
            Some(mut cur) => {
                // SAFETY: `cur` is a valid node of this list; `prev` (if any)
                // is also valid. We have unique access to the list.
                unsafe {
                    let prev = cur.as_ref().prev;
                    (*new_ptr.as_ptr()).prev = prev;
                    cur.as_mut().prev = Some(new_ptr);
                    match prev {
                        Some(mut prev) => prev.as_mut().next = Some(new_ptr),
                        None => self.list.front = Some(new_ptr),
                    }
                }
            }
        }
        self.list.len += 1;
    }
}

impl<'a, T> Iterator for Iter<'a, T> {
    type Item = &'a T;

    fn next(&mut self) -> Option<&'a T> {
        self.next.map(|node| {
            // SAFETY: the node is valid for as long as the list is borrowed
            // (lifetime `'a`), and the list cannot be mutated during that time.
            let node = unsafe { &*node.as_ptr() };
            self.next = node.next;
            &node.element
        })
    }
}
