            _marker: PhantomData,
        }
    }

    // You may be wondering why it's necessary to have is_empty()
    // when it can easily be determined from len().
    // It's good custom to have both because len() can be expensive for some types,
    // whereas is_empty() is almost always cheap.
    // (Also ask yourself whether len() is expensive for LinkedList)
    pub fn is_empty(&self) -> bool {
        self.len == 0
    }

    pub fn len(&self) -> usize {
        self.len
    }

    /// Return a cursor positioned on the front element
    pub fn cursor_front(&mut self) -> Cursor<'_, T> {
        let current = self.front;
        Cursor {
            list: self,
            current,
        }
    }

    /// Return a cursor positioned on the back element
    pub fn cursor_back(&mut self) -> Cursor<'_, T> {
        let current = self.back;
        Cursor {
            list: self,
            current,
        }
    }

    /// Return an iterator that moves from front to back
    pub fn iter(&self) -> Iter<'_, T> {
        Iter {
            next: self.front,
            _marker: PhantomData,
        }
    }
}

impl<T> Default for LinkedList<T> {
    fn default() -> Self {
        Self::new()
    }
}

impl<T> Drop for LinkedList<T> {
    fn drop(&mut self) {
        let mut cur = self.front;
        while let Some(ptr) = cur {
            // SAFETY: every node was created by `Box::into_raw` and is owned
            // solely by this list; we visit each exactly once and never
            // touch it again after reconstituting the Box.
            let node = unsafe { Box::from_raw(ptr.as_ptr()) };
            cur = node.next;
        }
        self.front = None;
        self.back = None;
        self.len = 0;
    }
}

// the cursor is expected to act as if it is at the position of an element
// and it also has to work with and be able to insert into an empty list.
impl<T> Cursor<'_, T> {
    /// Take a mutable reference to the current element
    pub fn peek_mut(&mut self) -> Option<&mut T> {
        // SAFETY: `current` points to a live node owned by the list, which we
        // borrow mutably through `self`.
        self.current
            .map(|ptr| unsafe { &mut (*ptr.as_ptr()).element })
    }

    /// Move one position forward (towards the back) and
    /// return a reference to the new position
    #[allow(clippy::should_implement_trait)]
    pub fn next(&mut self) -> Option<&mut T> {
        let cur = self.current?;
        // SAFETY: `cur` is a live node in the list.
        let next = unsafe { (*cur.as_ptr()).next }?;
        self.current = Some(next);
        // SAFETY: `next` is a live node in the list.
        Some(unsafe { &mut (*next.as_ptr()).element })
    }

    /// Move one position backward (towards the front) and
    /// return a reference to the new position
    pub fn prev(&mut self) -> Option<&mut T> {
        let cur = self.current?;
        // SAFETY: `cur` is a live node in the list.
        let prev = unsafe { (*cur.as_ptr()).prev }?;
        self.current = Some(prev);
        // SAFETY: `prev` is a live node in the list.
        Some(unsafe { &mut (*prev.as_ptr()).element })
    }

    /// Remove and return the element at the current position and move the cursor
    /// to the neighboring element that's closest to the back. This can be
    /// either the next or previous position.
    pub fn take(&mut self) -> Option<T> {
        let cur = self.current?;
        // SAFETY: `cur` was created by `Box::into_raw` and is owned by the
        // list; we unlink it below so that no other pointer to it remains,
        // then reclaim the allocation exactly once.
        let node = unsafe { Box::from_raw(cur.as_ptr()) };
        match node.prev {
            // SAFETY: `prev` is a live node in the list.
            Some(prev) => unsafe { (*prev.as_ptr()).next = node.next },
            None => self.list.front = node.next,
        }
        match node.next {
            // SAFETY: `next` is a live node in the list.
            Some(next) => unsafe { (*next.as_ptr()).prev = node.prev },
            None => self.list.back = node.prev,
        }
        self.list.len -= 1;
        self.current = node.next.or(node.prev);
        Some(node.element)
    }

    pub fn insert_after(&mut self, element: T) {
        let new = Box::new(Node {
            element,
            prev: self.current,
            next: None,
        });
        // SAFETY: Box::into_raw never returns null.
        let new_ptr = unsafe { NonNull::new_unchecked(Box::into_raw(new)) };
        match self.current {
            None => {
                self.list.front = Some(new_ptr);
                self.list.back = Some(new_ptr);
                self.current = Some(new_ptr);
            }
            Some(cur) => {
                // SAFETY: `cur` and its `next` (if any) are live nodes in the
                // list; `new_ptr` is a freshly allocated, unaliased node.
                unsafe {
                    let next = (*cur.as_ptr()).next;
                    (*new_ptr.as_ptr()).next = next;
                    (*cur.as_ptr()).next = Some(new_ptr);
                    match next {
                        Some(next) => (*next.as_ptr()).prev = Some(new_ptr),
                        None => self.list.back = Some(new_ptr),
                    }
                }
            }
        }
        self.list.len += 1;
    }

    pub fn insert_before(&mut self, element: T) {
        let new = Box::new(Node {
            element,
            prev: None,
            next: self.current,
        });
        // SAFETY: Box::into_raw never returns null.
        let new_ptr = unsafe { NonNull::new_unchecked(Box::into_raw(new)) };
        match self.current {
            None => {
                self.list.front = Some(new_ptr);
                self.list.back = Some(new_ptr);
                self.current = Some(new_ptr);
            }
            Some(cur) => {
                // SAFETY: `cur` and its `prev` (if any) are live nodes in the
                // list; `new_ptr` is a freshly allocated, unaliased node.
                unsafe {
                    let prev = (*cur.as_ptr()).prev;
                    (*new_ptr.as_ptr()).prev = prev;
                    (*cur.as_ptr()).prev = Some(new_ptr);
                    match prev {
                        Some(prev) => (*prev.as_ptr()).next = Some(new_ptr),
                        None => self.list.front = Some(new_ptr),
                    }
                }
            }
        }
        self.list.len += 1;
    }
}

impl<'a, T> Iterator for Iter<'a, T> {
    type Item = &'a T;

    fn next(&mut self) -> Option<&'a T> {
        let cur = self.next?;
        // SAFETY: the iterator borrows the list for 'a, so all nodes stay
        // alive and unmodified for that lifetime.
        unsafe {
            self.next = (*cur.as_ptr()).next;
            Some(&(*cur.as_ptr()).element)
        }
    }
}
