```
//
// Re-implementation of a few `Promise` helpers.
//
// `all`, `allSettled`, `race` and `any` mimic the built-in `Promise` methods of
// the same names but, as requested, do NOT rely on them: they are only built
// on top of the `Promise` constructor and of `.then()`.
//

/**
 * Turns a function using the "callback pattern" into a function returning a
 * promise.
 *
 * `fn` must expect a node style callback, `(error, data) => {}`, as its last
 * argument. The returned function takes the same arguments as `fn` except for
 * that callback, and returns a promise which is rejected with `error` when the
 * callback receives one, or resolved with `data` otherwise.
 *
 * @param {Function} fn function expecting a node style callback as last argument
 * @returns {Function} the promise returning version of `fn`
 */
export const promisify = (fn) =>
  function promisified(...args) {
    return new Promise((resolve, reject) => {
      // `this` is forwarded so that methods can be promisified as well.
      fn.call(this, ...args, (error, data) => {
        if (error) {
          reject(error);
        } else {
          resolve(data);
        }
      });
    });
  };

/**
 * Tells whether nothing at all was given (no argument, or `null`).
 */
const isMissing = (value) => value === undefined || value === null;

/**
 * Bookkeeping shared by the helpers that wait for several promises.
 *
 * Returns a `record(index, value)` function that stores `value` at position
 * `index` and, as soon as a value has been recorded for each of the `count`
 * positions, calls `onDone` with the array of all the recorded values. That
 * array is ordered by position, whatever the order the values were recorded in.
 *
 * If `count` is 0 there is nothing to wait for: `onDone` is called right away.
 */
const gather = (count, onDone) => {
  const values = new Array(count);
  let missing = count;

  if (missing === 0) {
    onDone(values);
  }

  return (index, value) => {
    values[index] = value;
    missing -= 1;

    if (missing === 0) {
      onDone(values);
    }
  };
};

/**
 * Resolves with the array of the values of all the given promises, in the order
 * the promises were given, once every one of them is resolved. Rejects with the
 * reason of the first promise that rejects.
 *
 * Plain values are accepted as well and are treated as already resolved
 * promises. With no promise to wait for (`all([])`) it resolves with an empty
 * array, and when called without any argument it resolves with `undefined`.
 *
 * @param {Iterable} [promises]
 * @returns {Promise<Array>}
 */
export const all = (promises) =>
  new Promise((resolve, reject) => {
    if (isMissing(promises)) {
      resolve(undefined);
      return;
    }

    const items = [...promises];
    const record = gather(items.length, resolve);

    items.forEach((item, index) => {
      Promise.resolve(item).then((value) => record(index, value), reject);
    });
  });

/**
 * Resolves once every given promise is settled (resolved or rejected), with an
 * array, in the order the promises were given, describing how each one ended:
 * `{ status: 'fulfilled', value }` or `{ status: 'rejected', reason }`.
 *
 * It never rejects. As for `all`, `allSettled([])` resolves with an empty array
 * and calling it without any argument resolves with `undefined`.
 *
 * @param {Iterable} [promises]
 * @returns {Promise<Array>}
 */
export const allSettled = (promises) =>
  new Promise((resolve) => {
    if (isMissing(promises)) {
      resolve(undefined);
      return;
    }

    const items = [...promises];
    const record = gather(items.length, resolve);

    items.forEach((item, index) => {
      Promise.resolve(item).then(
        (value) => record(index, { status: 'fulfilled', value }),
        (reason) => record(index, { status: 'rejected', reason }),
      );
    });
  });

/**
 * Settles the same way as the first of the given promises that settles:
 * resolved with its value, or rejected with its reason.
 *
 * With no promise at all (`race([])`) nothing can ever settle, so the returned
 * promise stays pending forever (like the built-in one).
 *
 * @param {Iterable} promises
 * @returns {Promise}
 */
export const race = (promises) =>
  new Promise((resolve, reject) => {
    [...promises].forEach((item) => {
      Promise.resolve(item).then(resolve, reject);
    });
  });

/**
 * Resolves with the value of the first given promise that resolves. Rejects
 * only when all of them reject, with the array of their reasons (in the order
 * the promises were given).
 *
 * With no promise at all (`any([])`) nothing can resolve, so it rejects right
 * away with an empty array.
 *
 * @param {Iterable} promises
 * @returns {Promise}
 */
export const any = (promises) =>
  new Promise((resolve, reject) => {
    const items = [...promises];
    // The reasons are gathered by position and only used if all of them reject.
    const record = gather(items.length, reject);

    items.forEach((item, index) => {
      Promise.resolve(item).then(resolve, (reason) => record(index, reason));
    });
  });
```

