//
// Implementation of promisify and re-implementations of Promise combinators.
//

export const promisify = (fn) => {
  return (...args) =>
    new Promise((resolve, reject) => {
      fn(...args, (error, data) => {
        if (error) {
          reject(error);
        } else {
          resolve(data);
        }
      });
    });
};

const toPromise = (value) => new Promise((resolve) => resolve(value));

export const all = (promises) => {
  return new Promise((resolve, reject) => {
    if (!promises || promises.length === 0) {
      resolve([]);
      return;
    }

    const results = new Array(promises.length);
    let remaining = promises.length;

    promises.forEach((p, index) => {
      toPromise(p).then((value) => {
        results[index] = value;
        remaining -= 1;
        if (remaining === 0) {
          resolve(results);
        }
      }, reject);
    });
  });
};

export const allSettled = (promises) => {
  return new Promise((resolve) => {
    if (!promises || promises.length === 0) {
      resolve([]);
      return;
    }

    const results = new Array(promises.length);
    let remaining = promises.length;

    const settle = (index, result) => {
      results[index] = result;
      remaining -= 1;
      if (remaining === 0) {
        resolve(results);
      }
    };

    promises.forEach((p, index) => {
      toPromise(p).then(
        (value) => settle(index, { status: 'fulfilled', value }),
        (reason) => settle(index, { status: 'rejected', reason }),
      );
    });
  });
};

export const race = (promises) => {
  return new Promise((resolve, reject) => {
    if (!promises) return;
    promises.forEach((p) => {
      toPromise(p).then(resolve, reject);
    });
  });
};

export const any = (promises) => {
  return new Promise((resolve, reject) => {
    if (!promises || promises.length === 0) {
      reject(new AggregateError([], 'All promises were rejected'));
      return;
    }

    const errors = new Array(promises.length);
    let remaining = promises.length;

    promises.forEach((p, index) => {
      toPromise(p).then(resolve, (error) => {
        errors[index] = error;
        remaining -= 1;
        if (remaining === 0) {
          reject(new AggregateError(errors, 'All promises were rejected'));
        }
      });
    });
  });
};
