package wordy

import (
	"strconv"
	"strings"
)

// Answer parses and evaluates a simple math word problem.
// Operations are evaluated strictly from left to right.
// The boolean result is false if the question could not be parsed or evaluated.
func Answer(question string) (int, bool) {
	question = strings.TrimSpace(question)
	if !strings.HasSuffix(question, "?") {
		return 0, false
	}
	question = strings.TrimSuffix(question, "?")

	tokens := strings.Fields(question)
	if len(tokens) < 3 || tokens[0] != "What" || tokens[1] != "is" {
		return 0, false
	}
	tokens = tokens[2:]

	result, err := strconv.Atoi(tokens[0])
	if err != nil {
		return 0, false
	}

	i := 1
	for i < len(tokens) {
		op := tokens[i]
		i++

		switch op {
		case "multiplied", "divided":
			if i >= len(tokens) || tokens[i] != "by" {
				return 0, false
			}
			i++
		case "plus", "minus":
		default:
			return 0, false
		}

		if i >= len(tokens) {
			return 0, false
		}
		n, err := strconv.Atoi(tokens[i])
		if err != nil {
			return 0, false
		}
		i++

		switch op {
		case "plus":
			result += n
		case "minus":
			result -= n
		case "multiplied":
			result *= n
		case "divided":
			if n == 0 {
				return 0, false
			}
			result /= n
		}
	}

	return result, true
}
