// Package wordy evaluates simple math word problems.
package wordy

import (
	"strconv"
	"strings"
)

// operation applies an operator to its left and right operands. The boolean
// result is false when the operation cannot be evaluated, for example when
// dividing by zero.
type operation func(left, right int) (int, bool)

// operations maps every supported operator, spelled the way it appears in a
// question, to the operation that evaluates it.
var operations = map[string]operation{
	"plus":          add,
	"minus":         subtract,
	"multiplied by": multiply,
	"divided by":    divide,
}

func add(left, right int) (int, bool) {
	return left + right, true
}

func subtract(left, right int) (int, bool) {
	return left - right, true
}

func multiply(left, right int) (int, bool) {
	return left * right, true
}

// divide performs an integer division, since the answer has to be an integer.
// Dividing by zero has no answer.
func divide(left, right int) (int, bool) {
	if right == 0 {
		return 0, false
	}
	return left / right, true
}

// Answer evaluates a simple math word problem such as "What is 5 plus 13?".
//
// The supported operators are "plus", "minus", "multiplied by" and
// "divided by", and the numbers may be negative. Operators are applied
// strictly from left to right, ignoring the usual order of operations, so
// "What is 3 plus 2 multiplied by 3?" is 15.
//
// The boolean result is false when the question is not a math question, uses
// an unsupported operation, has invalid syntax or cannot be evaluated.
func Answer(question string) (int, bool) {
	words, ok := tokenize(question)
	if !ok {
		return 0, false
	}

	// An expression always starts with a number...
	result, words, ok := number(words)
	if !ok {
		return 0, false
	}

	// ...which is followed by any number of "operator number" pairs.
	var (
		op      operation
		operand int
	)
	for len(words) > 0 {
		if op, words, ok = operator(words); !ok {
			return 0, false
		}
		if operand, words, ok = number(words); !ok {
			return 0, false
		}
		if result, ok = op(result, operand); !ok {
			return 0, false
		}
	}

	return result, true
}

// tokenize checks that question has the form "What is <expression>?" and
// returns the words that make up the expression.
func tokenize(question string) ([]string, bool) {
	question = strings.TrimSpace(question)
	if !strings.HasSuffix(question, "?") {
		return nil, false
	}

	words := strings.Fields(strings.TrimSuffix(question, "?"))
	if len(words) < 2 || words[0] != "What" || words[1] != "is" {
		return nil, false
	}

	return words[2:], true
}

// number reads the number at the start of words. It returns the number along
// with the words that follow it.
func number(words []string) (int, []string, bool) {
	if len(words) == 0 {
		return 0, nil, false
	}

	n, err := strconv.Atoi(words[0])
	if err != nil {
		return 0, nil, false
	}

	return n, words[1:], true
}

// operator reads the operator at the start of words. Operators are one or two
// words long ("plus", "multiplied by"), so both lengths are tried. It returns
// the operation along with the words that follow the operator.
func operator(words []string) (operation, []string, bool) {
	for length := 1; length <= 2 && length <= len(words); length++ {
		if op, ok := operations[strings.Join(words[:length], " ")]; ok {
			return op, words[length:], true
		}
	}

	return nil, nil, false
}
