#if !defined(BANK_ACCOUNT_H)
#define BANK_ACCOUNT_H

#include <mutex>

namespace Bankaccount {

// A bank account that can safely be used from several threads at once.
//
// Every public operation holds the account's mutex for its whole duration, so
// reading the balance and writing the new balance happen as a single atomic
// step. All failures are reported by throwing std::runtime_error.
class Bankaccount {
   public:
    Bankaccount() = default;

    // An account owns a mutex and has a single identity: it cannot be copied.
    Bankaccount(const Bankaccount&) = delete;
    Bankaccount& operator=(const Bankaccount&) = delete;

    // Opens the account with a balance of zero.
    // Throws if the account is already open.
    void open();

    // Closes the account, discarding its balance.
    // Throws if the account is not open.
    void close();

    // Adds a non-negative amount to the balance.
    // Throws if the account is not open, the amount is negative,
    // or the balance would overflow.
    void deposit(int amount);

    // Removes a non-negative amount from the balance.
    // Throws if the account is not open, the amount is negative,
    // or the amount exceeds the current balance.
    void withdraw(int amount);

    // Returns the current balance.
    // Throws if the account is not open.
    int balance() const;

   private:
    // Throws if the account is not open. The caller must hold mutex_.
    void ensure_open() const;

    mutable std::mutex mutex_;
    bool is_open_{false};
    int balance_{0};
};  // class Bankaccount

}  // namespace Bankaccount

#endif  // BANK_ACCOUNT_H
