// Errors which may occur when building a scale.
#[derive(Debug)]
pub struct Error;

const SHARPS: [&str; 12] = [
    "A", "A#", "B", "C", "C#", "D", "D#", "E", "F", "F#", "G", "G#",
];
const FLATS: [&str; 12] = [
    "A", "Bb", "B", "C", "Db", "D", "Eb", "E", "F", "Gb", "G", "Ab",
];

// Tonics (as given by the caller) which use flats.
const MAJOR_FLAT_TONICS: [&str; 6] = ["F", "Bb", "Eb", "Ab", "Db", "Gb"];
const MINOR_FLAT_TONICS: [&str; 6] = ["d", "g", "c", "f", "bb", "eb"];

pub struct Scale {
    notes: Vec<String>,
}

impl Scale {
    pub fn new(tonic: &str, intervals: &str) -> Result<Scale, Error> {
        let mut chars = tonic.chars();
        let first = chars.next().ok_or(Error)?;
        let is_minor = first.is_lowercase();

        let mut normalized: String = first.to_uppercase().collect();
        normalized.push_str(chars.as_str());

        let flat_list: &[&str] = if is_minor {
            &MINOR_FLAT_TONICS
        } else {
            &MAJOR_FLAT_TONICS
        };
        let use_flats = flat_list.contains(&tonic);

        let (primary, secondary): (&[&str; 12], &[&str; 12]) = if use_flats {
            (&FLATS, &SHARPS)
        } else {
            (&SHARPS, &FLATS)
        };

        let (chromatic, start) = if let Some(pos) = primary.iter().position(|&n| n == normalized) {
            (primary, pos)
        } else if let Some(pos) = secondary.iter().position(|&n| n == normalized) {
            (secondary, pos)
        } else {
            return Err(Error);
        };

        let mut notes = Vec::with_capacity(intervals.len());
        let mut index = start;
        for c in intervals.chars() {
            notes.push(chromatic[index].to_string());
            let step = match c {
                'm' => 1,
                'M' => 2,
                'A' => 3,
                _ => return Err(Error),
            };
            index = (index + step) % 12;
        }

        Ok(Scale { notes })
    }

    pub fn chromatic(tonic: &str) -> Result<Scale, Error> {
        Scale::new(tonic, "mmmmmmmmmmmm")
    }

    pub fn enumerate(&self) -> Vec<String> {
        self.notes.clone()
    }
}
