    let mut chars = tonic.chars();
    match chars.next() {
        Some(first) => first.to_uppercase().collect::<String>() + chars.as_str(),
        None => String::new(),
    }
}

fn index_of(table: &[&str; 12], note: &str) -> Option<usize> {
    table.iter().position(|&n| n == note)
}

impl Scale {
    pub fn new(tonic: &str, intervals: &str) -> Result<Scale, Error> {
        let table = if uses_flats(tonic) { &FLATS } else { &SHARPS };
        let name = normalize(tonic);
        let mut idx = index_of(table, &name).ok_or(Error)?;

        let mut notes = vec![table[idx].to_string()];
        let count = intervals.chars().count();
        for (i, c) in intervals.chars().enumerate() {
            let step = match c {
                'm' => 1,
                'M' => 2,
                'A' => 3,
                _ => return Err(Error),
