// Errors that can occur while constructing a scale.
#[derive(Debug)]
pub struct Error;

pub struct Scale {
    notes: Vec<String>,
    start: usize,
    steps: Vec<usize>,
    include_closing: bool,
}

const SHARPS: [&str; 12] = [
    "A", "A#", "B", "C", "C#", "D", "D#", "E", "F", "F#", "G", "G#",
];
const FLATS: [&str; 12] = [
    "A", "Bb", "B", "C", "Db", "D", "Eb", "E", "F", "Gb", "G", "Ab",
];

fn use_flats(tonic: &str) -> bool {
    matches!(
        tonic,
        "F" | "Bb" | "Eb" | "Ab" | "Db" | "Gb" | "d" | "g" | "c" | "f" | "bb" | "eb"
    )
}

fn normalize(tonic: &str) -> String {
    let mut chars = tonic.chars();
    match chars.next() {
        Some(first) => first.to_uppercase().collect::<String>() + chars.as_str(),
        None => String::new(),
    }
}

impl Scale {
    pub fn new(tonic: &str, intervals: &str) -> Result<Scale, Error> {
        let table: &[&str; 12] = if use_flats(tonic) { &FLATS } else { &SHARPS };
        let normalized = normalize(tonic);
        let start = table
            .iter()
            .position(|n| *n == normalized)
            .ok_or(Error)?;

        let mut steps = Vec::new();
        for c in intervals.chars() {
            match c {
                'm' => steps.push(1),
                'M' => steps.push(2),
                'A' => steps.push(3),
                _ => return Err(Error),
            }
        }

        Ok(Scale {
            notes: table.iter().map(|s| s.to_string()).collect(),
            start,
            steps,
            include_closing: true,
        })
    }

    pub fn chromatic(tonic: &str) -> Result<Scale, Error> {
        let mut scale = Scale::new(tonic, "mmmmmmmmmmmm")?;
        scale.include_closing = false;
        Ok(scale)
    }

    pub fn enumerate(&self) -> Vec<String> {
        let mut result = Vec::new();
        let mut idx = self.start;
        let count = if self.include_closing {
            self.steps.len() + 1
        } else {
            self.steps.len()
        };
        for i in 0..count {
            result.push(self.notes[idx % 12].clone());
            if i < self.steps.len() {
                idx += self.steps[i];
            }
        }
        result
    }
}
