use std::fmt;

/// Everything that can go wrong while building a [`Scale`].
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Error {
    /// The tonic is not one of the supported note names, such as `C`, `f#` or `Bb`.
    InvalidTonic(String),
    /// The interval pattern contains a character other than `m`, `M` or `A`.
    InvalidInterval(char),
}

impl fmt::Display for Error {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Error::InvalidTonic(tonic) => write!(f, "invalid tonic: {tonic:?}"),
            Error::InvalidInterval(interval) => {
                write!(f, "invalid interval: {interval:?} (expected 'm', 'M' or 'A')")
            }
        }
    }
}

impl std::error::Error for Error {}

/// The twelve pitches of the chromatic scale, in order, starting at A.
type Spelling = [&'static str; 12];

/// The chromatic scale spelled with sharps.
const SHARPS: Spelling = [
    "A", "A#", "B", "C", "C#", "D", "D#", "E", "F", "F#", "G", "G#",
];

/// The chromatic scale spelled with flats.
const FLATS: Spelling = [
    "A", "Bb", "B", "C", "Db", "D", "Eb", "E", "F", "Gb", "G", "Ab",
];

/// Tonics written without an accidental whose scales are nevertheless spelled
/// with flats: F major and the d, g, c and f minor scales (an uppercase tonic
/// means major, a lowercase one minor). Every other natural tonic, including
/// C major and a minor, is spelled with sharps.
const FLAT_NATURAL_TONICS: [&str; 5] = ["F", "d", "g", "c", "f"];

/// A musical scale: the notes reached by starting on a tonic and following a
/// pattern of intervals.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Scale {
    notes: Vec<&'static str>,
}

impl Scale {
    /// Builds the scale that starts on `tonic` and follows `intervals`.
    ///
    /// The tonic is a note name such as `C`, `Bb` or `f#`. An uppercase tonic
    /// denotes a major key and a lowercase one a minor key; together with any
    /// accidental this decides whether the scale is spelled with sharps or
    /// flats.
    ///
    /// Each character of `intervals` is a step away from the current note:
    /// `m` is a half step, `M` a whole step and `A` an augmented second (a
    /// whole step plus a half step). Every interval contributes the note it
    /// starts from, so a pattern spanning an octave yields one note per
    /// interval without repeating the tonic at the end.
    ///
    /// # Errors
    ///
    /// Returns [`Error::InvalidTonic`] if `tonic` is not a supported note name
    /// and [`Error::InvalidInterval`] if `intervals` contains a character other
    /// than `m`, `M` or `A`.
    pub fn new(tonic: &str, intervals: &str) -> Result<Scale, Error> {
        let (spelling, mut position) =
            locate_tonic(tonic).ok_or_else(|| Error::InvalidTonic(tonic.to_string()))?;

        let mut notes = Vec::with_capacity(intervals.len());
        for interval in intervals.chars() {
            notes.push(spelling[position]);
            position = (position + semitones(interval)?) % spelling.len();
        }

        Ok(Scale { notes })
    }

    /// Builds the chromatic scale, i.e. all twelve pitches, starting on `tonic`.
    ///
    /// # Errors
    ///
    /// Returns [`Error::InvalidTonic`] if `tonic` is not a supported note name.
    pub fn chromatic(tonic: &str) -> Result<Scale, Error> {
        // Twelve half steps take us once around the whole chromatic scale.
        Scale::new(tonic, &"m".repeat(SHARPS.len()))
    }

    /// Returns the names of the notes of the scale, starting with the tonic.
    pub fn enumerate(&self) -> Vec<String> {
        self.notes.iter().map(|&note| note.to_owned()).collect()
    }
}

/// The number of semitones covered by an interval.
fn semitones(interval: char) -> Result<usize, Error> {
    match interval {
        'm' => Ok(1),
        'M' => Ok(2),
        'A' => Ok(3),
        other => Err(Error::InvalidInterval(other)),
    }
}

/// Works out how a scale starting on `tonic` is spelled and where the tonic
/// sits within that spelling.
///
/// An explicit accidental decides between sharps and flats; for a natural
/// tonic the choice follows the usual key signatures (see
/// [`FLAT_NATURAL_TONICS`]). Returns `None` if `tonic` is not a note name.
fn locate_tonic(tonic: &str) -> Option<(&'static Spelling, usize)> {
    let mut chars = tonic.chars();
    let letter = chars.next()?.to_ascii_uppercase();
    let accidental = chars.as_str();

    let spelling = match accidental {
        "#" => &SHARPS,
        "b" => &FLATS,
        "" if FLAT_NATURAL_TONICS.contains(&tonic) => &FLATS,
        "" => &SHARPS,
        _ => return None,
    };

    let name = format!("{letter}{accidental}");
    let position = spelling.iter().position(|&candidate| candidate == name)?;
    Some((spelling, position))
}
