- **Validation:** `generate` throws `Error('min must be <= max')` when `minFactor > maxFactor`. `minFactor` defaults to `1`.
- **Result shape:** each result has the palindrome `value` and its `factors` as `[smaller, larger]` pairs sorted by the smaller factor, e.g. `[[1, 9], [3, 3]]`. If no palindrome exists in the range, the result is `{ value: null, factors: [] }`.
- **Search:** brute-forcing every pair would be far too slow for four-digit factors, so each search stops early.
  - **Smallest:** walk `a` upward with `b >= a`. Products only grow, so once a palindrome is found, stop when `b` pushes the product past it, and stop entirely once `a * a` exceeds it.
  - **Largest:** the mirror image, walking `a` downward, with `b` going from the maximum down to `a`.
  - **Ties:** comparisons are strict, so pairs that produce an equal palindrome are still collected.
- **Assumption:** factors are non-negative integers, which the early stopping relies on.

palindrome-products.js
```javascript
//
// Palindrome Products
//
// Finds the smallest and largest palindromes that are products of two
// factors taken from an inclusive range of (non-negative) integers.
//

const isPalindrome = (number) => {
  let remaining = number;
  let reversed = 0;

  while (remaining > 0) {
    reversed = reversed * 10 + (remaining % 10);
    remaining = Math.floor(remaining / 10);
  }

  return reversed === number;
};

// Walks the factor pairs (a, b) with a <= b. `a` grows from the minimum and,
// for a fixed `a`, the product grows with `b`. Once a palindrome is known,
// anything above it can no longer be the smallest, so we can stop early.
const findSmallest = (minFactor, maxFactor) => {
  let value = null;
  let factors = [];

  for (let a = minFactor; a <= maxFactor; a += 1) {
    // The smallest product reachable with this `a` (or any larger one).
    if (value !== null && a * a > value) break;

    for (let b = a; b <= maxFactor; b += 1) {
      const product = a * b;
      if (value !== null && product > value) break;

      if (isPalindrome(product)) {
        if (product !== value) {
          value = product;
          factors = [];
        }
        factors.push([a, b]);
      }
    }
  }

  return { value, factors };
};

// Mirror image of `findSmallest`: `a` shrinks from the maximum and, for a
// fixed `a`, the product shrinks as `b` goes down. Once a palindrome is known,
// anything below it can no longer be the largest, so we can stop early.
const findLargest = (minFactor, maxFactor) => {
  let value = null;
  let factors = [];

  for (let a = maxFactor; a >= minFactor; a -= 1) {
    // The largest product reachable with this `a` (or any smaller one).
    if (value !== null && a * maxFactor < value) break;

    for (let b = maxFactor; b >= a; b -= 1) {
      const product = a * b;
      if (value !== null && product < value) break;

      if (isPalindrome(product)) {
        if (product !== value) {
          value = product;
          factors = [];
        }
        // `a` is decreasing, so prepending keeps the pairs in ascending order.
        factors.unshift([a, b]);
      }
    }
  }

  return { value, factors };
};

export class Palindromes {
  constructor(minFactor, maxFactor) {
    this.minFactor = minFactor;
    this.maxFactor = maxFactor;
  }

  static generate({ minFactor = 1, maxFactor }) {
    if (minFactor > maxFactor) {
      throw new Error('min must be <= max');
    }

    return new Palindromes(minFactor, maxFactor);
  }

  get smallest() {
    return findSmallest(this.minFactor, this.maxFactor);
  }

  get largest() {
    return findLargest(this.minFactor, this.maxFactor);
  }
}
