promises.js
```javascript
//
// Promises exercise.
//
// `promisify` turns a function that uses the "callback pattern" into a function that
// returns a Promise. `all`, `allSettled`, `race` and `any` are re-implementations of
// the built-in `Promise.all`, `Promise.allSettled`, `Promise.race` and `Promise.any`
// (which are deliberately not used here).
//

/**
 * Turns a function that takes a Node-style callback as its last argument
 * (`callback(error, data)`) into a function that returns a Promise.
 *
 * The Promise rejects with `error` if the callback is called with an error and
 * resolves with `data` otherwise.
 *
 * @param {Function} fn function using the callback pattern
 * @returns {Function} function returning a Promise
 */
export const promisify = (fn) =>
  // A regular function (not an arrow function) so that `this` is preserved.
  function promisified(...args) {
    return new Promise((resolve, reject) => {
      fn.call(this, ...args, (error, data) => {
        if (error) {
          reject(error);
        } else {
          resolve(data);
        }
      });
    });
  };

/**
 * Creates a `store(index, value)` function. Once a value has been stored for each
 * of the `count` indexes, `done` is called with all the stored values, ordered by
 * their index.
 *
 * When `count` is 0 there is nothing to wait for, so `done` is called right away
 * with an empty array.
 *
 * @param {number} count
 * @param {Function} done
 * @returns {Function}
 */
const gather = (count, done) => {
  const values = new Array(count);
  let missing = count;

  if (missing === 0) {
    done(values);
  }

  return (index, value) => {
    values[index] = value;
    missing -= 1;

    if (missing === 0) {
      done(values);
    }
  };
};

/**
 * Takes promises and resolves, with the array of their values (in the order the
 * promises were passed in), when _all_ of them are resolved. Rejects as soon as
 * _one_ of them rejects.
 *
 * @param {Iterable} promises
 * @returns {Promise}
 */
export const all = (promises) => {
  // Called without anything to wait for, we simply resolve with `undefined`
  // (the built-ins would reject with a TypeError).
  if (promises === undefined) {
    return Promise.resolve(undefined);
  }

  return new Promise((resolve, reject) => {
    const items = Array.from(promises);
    const store = gather(items.length, resolve);

    items.forEach((item, index) => {
      Promise.resolve(item).then((value) => store(index, value), reject);
    });
  });
};

/**
 * Takes promises and resolves when _all_ of them either resolve or reject. The
 * result is an array (in the order the promises were passed in) describing the
 * outcome of each promise:
 *   - `{ status: 'fulfilled', value }` for a promise that resolved
 *   - `{ status: 'rejected', reason }` for a promise that rejected
 *
 * @param {Iterable} promises
 * @returns {Promise}
 */
export const allSettled = (promises) => {
  if (promises === undefined) {
    return Promise.resolve(undefined);
  }

  return new Promise((resolve) => {
    const items = Array.from(promises);
    const store = gather(items.length, resolve);

    items.forEach((item, index) => {
      Promise.resolve(item).then(
        (value) => store(index, { status: 'fulfilled', value }),
        (reason) => store(index, { status: 'rejected', reason })
      );
    });
  });
};

/**
 * Takes promises and resolves or rejects with the value (or reason) of the
 * _first_ promise that resolves or rejects.
 *
 * @param {Iterable} promises
 * @returns {Promise}
 */
export const race = (promises) => {
  if (promises === undefined) {
    return Promise.resolve(undefined);
  }

  return new Promise((resolve, reject) => {
    Array.from(promises).forEach((item) => {
      Promise.resolve(item).then(resolve, reject);
    });
  });
};

/**
 * Takes promises and resolves, with its value, as soon as _one_ of them resolves.
 * Rejects when _all_ of them reject, with an `AggregateError` whose `errors`
 * contain the rejection reasons (in the order the promises were passed in).
 *
 * @param {Iterable} promises
 * @returns {Promise}
 */
export const any = (promises) => {
  if (promises === undefined) {
    return Promise.resolve(undefined);
  }

  return new Promise((resolve, reject) => {
    const items = Array.from(promises);
    const store = gather(items.length, (errors) =>
      reject(new AggregateError(errors, 'All promises were rejected'))
    );

    items.forEach((item, index) => {
      Promise.resolve(item).then(resolve, (error) => store(index, error));
    });
  });
};
```

I implemented `promisify` and re-implemented `all`, `allSettled`, `race`, and `any` without using the built-in `Promise` combinators. I haven't run any tests against it.

- **`promisify`**: returns a function that calls the original with the given arguments plus a node-style callback, and resolves or rejects the promise from that callback. Synchronous throws also reject, because they happen inside the `Promise` executor.
- **`all`**: resolves with an array of results in input order once every promise has resolved, and rejects on the first rejection. An empty array resolves immediately to `[]`.
- **`allSettled`**: resolves with `{status: 'fulfilled', value}` or `{status: 'rejected', reason}` for each input, in order.
- **`race`**: settles with whichever input settles first.
- **`any`**: resolves with the first fulfillment, and rejects only after all inputs reject. It rejects with an `AggregateError` holding the reasons in input order, falling back to a plain `Error` with an `errors` property if `AggregateError` is unavailable. An empty array rejects immediately.

Non-promise values in the input are handled by wrapping each item in `Promise.resolve`.

promises.js
```javascript
//
// This is only a SKELETON file for the 'Promises' exercise. It's been provided as a
// convenience to get you started writing code faster.
//

export const promisify = (fn) => {
  return (...args) =>
    new Promise((resolve, reject) => {
      fn(...args, (error, data) => {
        if (error) {
          reject(error);
        } else {
          resolve(data);
        }
      });
    });
};

export const all = (promises) => {
  return new Promise((resolve, reject) => {
    if (!promises || promises.length === 0) {
      resolve([]);
      return;
    }

    const results = new Array(promises.length);
    let remaining = promises.length;

    promises.forEach((p, index) => {
      Promise.resolve(p).then(
        (value) => {
          results[index] = value;
          remaining -= 1;
          if (remaining === 0) {
            resolve(results);
          }
        },
        (error) => {
          reject(error);
        },
      );
    });
  });
};

export const allSettled = (promises) => {
  return new Promise((resolve) => {
    if (!promises || promises.length === 0) {
      resolve([]);
      return;
    }

    const results = new Array(promises.length);
    let remaining = promises.length;

    const settle = (index, result) => {
      results[index] = result;
      remaining -= 1;
      if (remaining === 0) {
        resolve(results);
      }
    };

    promises.forEach((p, index) => {
      Promise.resolve(p).then(
        (value) => settle(index, { status: 'fulfilled', value }),
        (reason) => settle(index, { status: 'rejected', reason }),
      );
    });
  });
};

export const race = (promises) => {
  return new Promise((resolve, reject) => {
    if (!promises) {
      return;
    }
    promises.forEach((p) => {
      Promise.resolve(p).then(resolve, reject);
    });
  });
};

export const any = (promises) => {
  return new Promise((resolve, reject) => {
    if (!promises || promises.length === 0) {
      reject(makeAggregateError([], 'All promises were rejected'));
      return;
    }

    const errors = new Array(promises.length);
    let remaining = promises.length;

    promises.forEach((p, index) => {
      Promise.resolve(p).then(
        (value) => {
          resolve(value);
        },
        (error) => {
          errors[index] = error;
          remaining -= 1;
          if (remaining === 0) {
            reject(makeAggregateError(errors, 'All promises were rejected'));
          }
        },
      );
    });
  });
};

const makeAggregateError = (errors, message) => {
  if (typeof AggregateError !== 'undefined') {
    return new AggregateError(errors, message);
  }
  const error = new Error(message);
  error.errors = errors;
  return error;
};
