// other than '0', '1' or '2', or a value that does not fit in an int64) yields
// the value 0 together with a non-nil error.
func ParseTrinary(arg string) (int64, error) {
	if arg == "" {
		return 0, errors.New("trinary: empty input")
	}

	var result int64
	for _, r := range arg {
		if r < '0' || r > '2' {
			return 0, fmt.Errorf("trinary: invalid digit %q in %q", r, arg)
		}

		digit := int64(r - '0')

