package beer

import (
	"fmt"
	"strings"
)

func Song() string {
	s, _ := Verses(99, 0)
	return s
}

func Verses(start, stop int) (string, error) {
	if start < 0 || start > 99 {
		return "", fmt.Errorf("start value %d is out of range", start)
	}
	if stop < 0 || stop > 99 {
		return "", fmt.Errorf("stop value %d is out of range", stop)
	}
	if start < stop {
		return "", fmt.Errorf("start %d is less than stop %d", start, stop)
	}
	var sb strings.Builder
	for i := start; i >= stop; i-- {
		v, err := Verse(i)
		if err != nil {
			return "", err
		}
		sb.WriteString(v)
		sb.WriteString("\n")
	}
	return sb.String(), nil
}

func bottles(n int) string {
	switch n {
	case 0:
		return "no more bottles"
	case 1:
		return "1 bottle"
	default:
		return fmt.Sprintf("%d bottles", n)
	}
}

func Verse(n int) (string, error) {
	if n < 0 || n > 99 {
		return "", fmt.Errorf("verse number %d is out of range", n)
	}
	switch n {
	case 0:
		return "No more bottles of beer on the wall, no more bottles of beer.\n" +
			"Go to the store and buy some more, 99 bottles of beer on the wall.\n", nil
	case 1:
		return "1 bottle of beer on the wall, 1 bottle of beer.\n" +
			"Take it down and pass it around, no more bottles of beer on the wall.\n", nil
	}
	return fmt.Sprintf("%s of beer on the wall, %s of beer.\nTake one down and pass it around, %s of beer on the wall.\n",
		bottles(n), bottles(n), bottles(n-1)), nil
}
