Three small helpers remove duplication: `bottlesOfBeer` handles "no more", singular and plural wording, `pronoun` chooses between "one" and "it", and `recite` builds the joined verses. Validation happens only in the exported functions.

beer_song.go
```go
package beer

import (
	"fmt"
	"strings"
)

// maxBottles is the number of bottles the song starts with, and the number
// bought at the store once every bottle has been taken down.
const maxBottles = 99

// Song returns the lyrics of the entire song, from 99 bottles down to none.
func Song() string {
	return recite(maxBottles, 0)
}

// Verses returns the verses from start down to stop (both inclusive), with a
// blank line between consecutive verses. It returns an error if either
// number is outside the range 0-99, or if start is less than stop.
func Verses(start, stop int) (string, error) {
	if err := checkVerseNumber(start); err != nil {
		return "", err
	}
	if err := checkVerseNumber(stop); err != nil {
		return "", err
	}
	if start < stop {
		return "", fmt.Errorf("start verse (%d) must not be less than stop verse (%d)", start, stop)
	}
	return recite(start, stop), nil
}

// Verse returns verse n of the song. It returns an error if n is outside the
// range 0-99.
func Verse(n int) (string, error) {
	if err := checkVerseNumber(n); err != nil {
		return "", err
	}
	return verseText(n), nil
}

// checkVerseNumber returns an error if n is not a valid verse number.
func checkVerseNumber(n int) error {
	if n < 0 || n > maxBottles {
		return fmt.Errorf("verse number %d is out of range: must be between 0 and %d", n, maxBottles)
	}
	return nil
}

// recite joins the verses from start down to stop (both inclusive) with a
// blank line in between. The arguments must already have been validated.
func recite(start, stop int) string {
	verses := make([]string, 0, start-stop+1)
	for n := start; n >= stop; n-- {
		verses = append(verses, verseText(n))
	}
	return strings.Join(verses, "\n")
}

// verseText builds the text of verse n, which must already have been
// validated. The returned text ends with a newline.
func verseText(n int) string {
	if n == 0 {
		return fmt.Sprintf(
			"No more bottles of beer on the wall, no more bottles of beer.\n"+
				"Go to the store and buy some more, %s on the wall.\n",
			bottlesOfBeer(maxBottles))
	}

	return fmt.Sprintf(
		"%s on the wall, %s.\n"+
			"Take %s down and pass it around, %s on the wall.\n",
		bottlesOfBeer(n), bottlesOfBeer(n), pronoun(n), bottlesOfBeer(n-1))
}

// bottlesOfBeer describes n bottles of beer, e.g. "2 bottles of beer".
func bottlesOfBeer(n int) string {
	switch n {
	case 0:
		return "no more bottles of beer"
	case 1:
		return "1 bottle of beer"
	default:
		return fmt.Sprintf("%d bottles of beer", n)
	}
}

// pronoun returns what gets taken down when n bottles are on the wall.
func pronoun(n int) string {
	if n == 1 {
		return "it"
	}
	return "one"
}
