- `Verse(n)` returns an error for `n` outside 0–99. It handles the special cases for 2, 1 and 0 bottles, and each verse ends with a newline.
- `Verses(start, stop)` returns an error if either number is outside 0–99 or if `start < stop`. Otherwise it joins the verses from `start` down to `stop`, with a blank line between them.
- `Song()` is `Verses(99, 0)`.

beer_song.go
```go
package beer

import (
	"errors"
	"fmt"
	"strings"
)

// Song returns the full lyrics of the song.
func Song() string {
	s, _ := Verses(99, 0)
	return s
}

// Verses returns the verses from start down to stop, inclusive,
// separated by blank lines.
func Verses(start, stop int) (string, error) {
	if start < 0 || start > 99 {
		return "", errors.New("start must be between 0 and 99")
	}
	if stop < 0 || stop > 99 {
		return "", errors.New("stop must be between 0 and 99")
	}
	if start < stop {
		return "", errors.New("start must not be less than stop")
	}
	parts := make([]string, 0, start-stop+1)
	for i := start; i >= stop; i-- {
		v, err := Verse(i)
		if err != nil {
			return "", err
		}
		parts = append(parts, v)
	}
	return strings.Join(parts, "\n"), nil
}

// Verse returns a single verse of the song.
func Verse(n int) (string, error) {
	switch {
	case n < 0 || n > 99:
		return "", errors.New("verse number must be between 0 and 99")
	case n == 0:
		return "No more bottles of beer on the wall, no more bottles of beer.\n" +
			"Go to the store and buy some more, 99 bottles of beer on the wall.\n", nil
	case n == 1:
		return "1 bottle of beer on the wall, 1 bottle of beer.\n" +
			"Take it down and pass it around, no more bottles of beer on the wall.\n", nil
	case n == 2:
		return "2 bottles of beer on the wall, 2 bottles of beer.\n" +
			"Take one down and pass it around, 1 bottle of beer on the wall.\n", nil
	default:
		return fmt.Sprintf("%d bottles of beer on the wall, %d bottles of beer.\n"+
			"Take one down and pass it around, %d bottles of beer on the wall.\n", n, n, n-1), nil
	}
}
