The stub needs a full builder-style graph DSL. I implemented it in `src/lib.rs` with:

- **`graph::graph_items::node::Node`**: built with `Node::new(name)`, then `with_attrs(&[(&str, &str)])` and `attr(name) -> Option<&str>`.
- **`graph::graph_items::edge::Edge`**: built with `Edge::new(src, dst)`, with the same `with_attrs` and `attr` methods.
- **`graph::Graph`**: `Graph::new()` creates an empty graph. `with_nodes`, `with_edges` and `with_attrs` are chainable builder methods, and `node(name)` looks a node up by name. `nodes`, `edges` and `attrs` are public fields, so they can be inspected directly.
- **Derives**: `Debug`, `Clone` and `PartialEq`/`Eq` (plus `Default` for `Graph`), so graphs, nodes and edges can be compared and cloned.

The builder methods append to existing content rather than replacing it, so repeated calls accumulate. Attributes are stored in a `HashMap<String, String>`, so their order doesn't matter for equality.

src/lib.rs
```
pub mod graph {
    use std::collections::HashMap;

    use self::graph_items::edge::Edge;
    use self::graph_items::node::Node;

    pub mod graph_items {
        pub mod edge {
            use std::collections::HashMap;

            /// An edge connecting two nodes (referenced by name), with optional attributes.
            #[derive(Debug, Clone, PartialEq, Eq)]
            pub struct Edge {
                pub src: String,
                pub dst: String,
                pub attrs: HashMap<String, String>,
            }

            impl Edge {
                /// Creates an edge between the nodes named `src` and `dst`.
                pub fn new(src: &str, dst: &str) -> Self {
                    Self {
                        src: src.to_string(),
                        dst: dst.to_string(),
                        attrs: HashMap::new(),
                    }
                }

                /// Adds the given attributes to the edge (builder style).
                pub fn with_attrs(mut self, attrs: &[(&str, &str)]) -> Self {
                    self.attrs.extend(
                        attrs
                            .iter()
                            .map(|&(key, value)| (key.to_string(), value.to_string())),
                    );
                    self
                }

                /// Looks up the value of an attribute by name.
                pub fn attr(&self, name: &str) -> Option<&str> {
                    self.attrs.get(name).map(String::as_str)
                }
            }
        }

        pub mod node {
            use std::collections::HashMap;

            /// A named graph node with optional attributes.
            #[derive(Debug, Clone, PartialEq, Eq)]
            pub struct Node {
                pub name: String,
                pub attrs: HashMap<String, String>,
            }

            impl Node {
                /// Creates a node with the given name and no attributes.
                pub fn new(name: &str) -> Self {
                    Self {
                        name: name.to_string(),
                        attrs: HashMap::new(),
                    }
                }

                /// Adds the given attributes to the node (builder style).
                pub fn with_attrs(mut self, attrs: &[(&str, &str)]) -> Self {
                    self.attrs.extend(
                        attrs
                            .iter()
                            .map(|&(key, value)| (key.to_string(), value.to_string())),
                    );
                    self
                }

                /// Looks up the value of an attribute by name.
                pub fn attr(&self, name: &str) -> Option<&str> {
                    self.attrs.get(name).map(String::as_str)
                }
            }
        }
    }

    /// A graph made of nodes, edges and graph-level attributes.
    #[derive(Debug, Clone, Default, PartialEq, Eq)]
    pub struct Graph {
        pub nodes: Vec<Node>,
        pub edges: Vec<Edge>,
        pub attrs: HashMap<String, String>,
    }

    impl Graph {
        /// Creates an empty graph.
        pub fn new() -> Self {
            Self::default()
        }

        /// Adds the given nodes to the graph (builder style).
        pub fn with_nodes(mut self, nodes: &[Node]) -> Self {
            self.nodes.extend_from_slice(nodes);
            self
        }

        /// Adds the given edges to the graph (builder style).
        pub fn with_edges(mut self, edges: &[Edge]) -> Self {
            self.edges.extend_from_slice(edges);
            self
        }

        /// Adds the given graph-level attributes (builder style).
        pub fn with_attrs(mut self, attrs: &[(&str, &str)]) -> Self {
            self.attrs.extend(
                attrs
                    .iter()
                    .map(|&(key, value)| (key.to_string(), value.to_string())),
            );
            self
        }

        /// Finds a node by its name.
        pub fn node(&self, name: &str) -> Option<&Node> {
            self.nodes.iter().find(|node| node.name == name)
        }
    }
}
