I implemented the `PythagoreanTriplet` class and its builder. The builder collects an optional sum and an optional maximum factor, then enumerates all triplets with a < b < c that satisfy a² + b² = c².

- If only a sum is given, `a` and `b` are enumerated and `c = sum - a - b`.
- If a max factor is given (with or without a sum), `c` is bounded by it.
- If neither is given, `build()` throws `IllegalStateException`, since the search would be unbounded.
- I added `equals`, `hashCode`, `toString`, and getters so tests can compare triplets.
- Enumeration order is by `a`, then `b`, which gives sorted results.

PythagoreanTriplet.java
```java
import java.util.ArrayList;
import java.util.List;
import java.util.Objects;

class PythagoreanTriplet {

    private final int a;
    private final int b;
    private final int c;

    PythagoreanTriplet(int a, int b, int c) {
        this.a = a;
        this.b = b;
        this.c = c;
    }

    int getA() {
        return a;
    }

    int getB() {
        return b;
    }

    int getC() {
        return c;
    }

    static TripletListBuilder makeTripletsList() {
        return new TripletListBuilder();
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) {
            return true;
        }
        if (!(o instanceof PythagoreanTriplet)) {
            return false;
        }
        PythagoreanTriplet other = (PythagoreanTriplet) o;
        return a == other.a && b == other.b && c == other.c;
    }

    @Override
    public int hashCode() {
        return Objects.hash(a, b, c);
    }

    @Override
    public String toString() {
        return "{" + a + ", " + b + ", " + c + "}";
    }

    static class TripletListBuilder {

        private Integer sum = null;
        private Integer maxFactor = null;

        TripletListBuilder thatSumTo(int sum) {
            this.sum = sum;
            return this;
        }

        TripletListBuilder withFactorsLessThanOrEqualTo(int maxFactor) {
            this.maxFactor = maxFactor;
            return this;
        }

        List<PythagoreanTriplet> build() {
            List<PythagoreanTriplet> result = new ArrayList<>();

            if (sum == null && maxFactor == null) {
                throw new IllegalStateException("Either a sum or a max factor must be specified.");
            }

            int limit;
            if (maxFactor != null) {
                limit = maxFactor;
            } else {
                limit = sum;
            }

            for (int a = 1; a <= limit; a++) {
                for (int b = a + 1; b <= limit; b++) {
                    int c;
                    if (sum != null) {
                        c = sum - a - b;
                        if (c <= b) {
                            break;
                        }
                        if (c > limit) {
                            continue;
                        }
                        if (a * a + b * b == c * c) {
                            result.add(new PythagoreanTriplet(a, b, c));
                        }
                    } else {
                        long cSquared = (long) a * a + (long) b * b;
                        c = (int) Math.round(Math.sqrt((double) cSquared));
                        if (c > limit) {
                            break;
                        }
                        if ((long) c * c == cSquared && c > b) {
                            result.add(new PythagoreanTriplet(a, b, c));
                        }
                    }
                }
            }

            return result;
        }

    }

}
