def proverb(*inputs, qualifier=None):
    if not inputs:
        return []

    lines = [
        f"For want of a {first} the {second} was lost."
        for first, second in zip(inputs, inputs[1:])
    ]

    if qualifier:
        lines.append(f"And all for the want of a {qualifier} {inputs[0]}.")
    else:
        lines.append(f"And all for the want of a {inputs[0]}.")

    return lines
