        let mut notes = Vec::new();
        let mut total = 0;
        notes.push(table[idx].to_string());
        for c in intervals.chars() {
            let step = match c {
                'm' => 1,
                'M' => 2,
                'A' => 3,
                _ => return Err(Error),
            };
            total += step;
            if total >= 12 {
                break;
            }
            idx = (idx + step) % 12;
            notes.push(table[idx].to_string());
        }
        Ok(Scale { notes })
