#[derive(Debug)]
pub struct Error;

pub struct Scale {
    notes: Vec<String>,
}

const SHARPS: [&str; 12] = [
    "A", "A#", "B", "C", "C#", "D", "D#", "E", "F", "F#", "G", "G#",
];
const FLATS: [&str; 12] = [
    "A", "Bb", "B", "C", "Db", "D", "Eb", "E", "F", "Gb", "G", "Ab",
];

fn use_flats(tonic: &str) -> Option<bool> {
    match tonic {
        "C" | "a" | "G" | "D" | "A" | "E" | "B" | "F#" | "e" | "b" | "f#" | "c#" | "g#"
        | "d#" => Some(false),
        "F" | "Bb" | "Eb" | "Ab" | "Db" | "Gb" | "d" | "g" | "c" | "f" | "bb" | "eb" => {
            Some(true)
        }
        _ => None,
    }
}

fn capitalize(s: &str) -> String {
    let mut chars = s.chars();
    match chars.next() {
        Some(c) => c.to_uppercase().collect::<String>() + chars.as_str(),
        None => String::new(),
    }
}

impl Scale {
    pub fn new(tonic: &str, intervals: &str) -> Result<Scale, Error> {
        let flats = use_flats(tonic).ok_or(Error)?;
        let table = if flats { &FLATS } else { &SHARPS };
        let name = capitalize(tonic);
        let start = table.iter().position(|&n| n == name).ok_or(Error)?;

        let mut notes = vec![table[start].to_string()];
        let mut idx = start;
        let mut steps = Vec::new();
        for c in intervals.chars() {
            steps.push(match c {
                'm' => 1,
                'M' => 2,
                'A' => 3,
                _ => return Err(Error),
            });
        }
        for (i, step) in steps.iter().enumerate() {
            idx = (idx + step) % 12;
            if i + 1 < steps.len() {
                notes.push(table[idx].to_string());
            }
        }
        Ok(Scale { notes })
    }

    pub fn chromatic(tonic: &str) -> Result<Scale, Error> {
        Scale::new(tonic, "mmmmmmmmmmmm")
    }

    pub fn enumerate(&self) -> Vec<String> {
        self.notes.clone()
    }
