#define BANK_ACCOUNT_H

#include <mutex>
#include <stdexcept>

namespace Bankaccount {

class Bankaccount {
   public:
    Bankaccount() = default;

    // An account owns a mutex, so it can be neither copied nor assigned.
    Bankaccount(const Bankaccount&) = delete;
    Bankaccount& operator=(const Bankaccount&) = delete;

    // Opens the account with a balance of zero.
    // Throws std::runtime_error if the account is already open.
    void open();

    // Closes the account.
    // Throws std::runtime_error if the account is not open.
    void close();

    // Adds `amount` to the balance.
    // Throws std::runtime_error if the account is not open, the amount is
    // negative, or the new balance would not fit into an int.
    void deposit(int amount);

    // Removes `amount` from the balance.
    // Throws std::runtime_error if the account is not open, the amount is
    // negative, or the amount is larger than the current balance.
    void withdraw(int amount);

    // Returns the current balance.
    // Throws std::runtime_error if the account is not open.
    int balance() const;

   private:
    // Throws std::runtime_error unless the account is open.
    // The caller must already hold `mutex_`.
    void ensure_open() const;

    // Serialises every access to the account state below. It is mutable so
    // that read-only operations such as balance() can be const.
    mutable std::mutex mutex_;
    bool is_open_{false};
    int balance_{0};
};  // class Bankaccount

}  // namespace Bankaccount

#endif  // BANK_ACCOUNT_H
