#include "bank_account.h"

#include <limits>
#include <stdexcept>

namespace Bankaccount {

void Bankaccount::open() {
    std::lock_guard<std::mutex> lock(mutex_);
    if (is_open_) {
        throw std::runtime_error("account already open");
    }
    is_open_ = true;
    balance_ = 0;
}

void Bankaccount::close() {
    std::lock_guard<std::mutex> lock(mutex_);
    ensure_open();
    is_open_ = false;
}

void Bankaccount::deposit(int amount) {
    std::lock_guard<std::mutex> lock(mutex_);
    ensure_open();
    if (amount < 0) {
        throw std::runtime_error("amount must not be negative");
    }
    // balance_ is never negative, so this subtraction cannot overflow.
    if (amount > std::numeric_limits<int>::max() - balance_) {
        throw std::runtime_error("deposit would exceed the maximum balance");
    }
    balance_ += amount;
}

void Bankaccount::withdraw(int amount) {
    std::lock_guard<std::mutex> lock(mutex_);
    ensure_open();
    if (amount < 0) {
        throw std::runtime_error("amount must not be negative");
    }
    if (amount > balance_) {
        throw std::runtime_error("insufficient funds");
    }
    balance_ -= amount;
}

int Bankaccount::balance() const {
    std::lock_guard<std::mutex> lock(mutex_);
    ensure_open();
    return balance_;
}

void Bankaccount::ensure_open() const {
    if (!is_open_) {
        throw std::runtime_error("account not open");
    }
}

}  // namespace Bankaccount
