        try:
            return int(token)
        except ValueError:
            return None

    # First token must be a number
    result = parse_number(tokens[0])
    if result is None:
        if tokens[0] in operations:
            raise ValueError("syntax error")
        raise ValueError("unknown operation")

    idx = 1
    while idx < len(tokens):
        op = tokens[idx]
        if op not in operations:
            if parse_number(op) is not None:
                raise ValueError("syntax error")
            raise ValueError("unknown operation")
        if idx + 1 >= len(tokens):
            raise ValueError("syntax error")
        operand = parse_number(tokens[idx + 1])
        if operand is None:
            if tokens[idx + 1] in operations:
                raise ValueError("syntax error")
            raise ValueError("unknown operation")
        if op == "divided" and operand == 0:
            raise ValueError("division by zero")
        result = operations[op](result, operand)
        idx += 2

    return result
