import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Deque;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

class Dominoes {

    private static final String NO_CHAIN_MESSAGE = "No domino chain found.";

    List<Domino> formChain(List<Domino> inputDominoes) throws ChainNotFoundException {
        if (inputDominoes.isEmpty()) {
            return new ArrayList<>();
        }

        // Model the problem as a graph: every number of dots is a vertex and every domino is an
        // undirected edge joining the numbers on its two halves. A valid chain is then an
        // Eulerian circuit, i.e. a closed walk that uses every edge exactly once.
        Map<Integer, Deque<Integer>> indicesByDots = indexByDots(inputDominoes);

        // A closed walk enters and leaves each vertex equally often,
        // so every vertex needs an even degree.
        for (Deque<Integer> indices : indicesByDots.values()) {
            if (indices.size() % 2 != 0) {
                throw new ChainNotFoundException(NO_CHAIN_MESSAGE);
            }
        }

        List<Domino> chain = buildChain(inputDominoes, indicesByDots);

        // The walk only reaches dominoes that are connected to the first one. If it missed some,
        // the input consists of several separate groups and cannot form a single chain.
        if (chain.size() != inputDominoes.size()) {
            throw new ChainNotFoundException(NO_CHAIN_MESSAGE);
        }

        return chain;
    }

    /**
     * Maps every number of dots to the positions (in the input) of the dominoes having a half with
     * that number. A double such as [3|3] is listed twice for its number, once per half, so the
     * size of each collection is exactly the degree of the corresponding vertex.
     */
    private static Map<Integer, Deque<Integer>> indexByDots(List<Domino> dominoes) {
        Map<Integer, Deque<Integer>> indicesByDots = new HashMap<>();
        for (int i = 0; i < dominoes.size(); i++) {
            Domino domino = dominoes.get(i);
            indicesByDots.computeIfAbsent(domino.getLeft(), dots -> new ArrayDeque<>()).add(i);
            indicesByDots.computeIfAbsent(domino.getRight(), dots -> new ArrayDeque<>()).add(i);
        }
        return indicesByDots;
    }

    /**
     * Builds a chain with an iterative version of Hierholzer's algorithm.
     *
     * The walk starts at the left half of the first domino and keeps appending unused dominoes.
     * When it gets stuck, the domino it arrived with is final and gets backtracked over; any
     * detours still possible further back are spliced in automatically. The dominoes are finalized
     * in reverse order, so the result is reversed at the end.
     *
     * The returned chain contains only the dominoes reachable from the starting point.
     */
    private static List<Domino> buildChain(List<Domino> dominoes, Map<Integer, Deque<Integer>> indicesByDots) {
        boolean[] used = new boolean[dominoes.size()];
        List<Domino> reversedChain = new ArrayList<>(dominoes.size());

        // The current walk: the numbers of dots visited, and the dominoes placed between them
        // (oriented in walking direction). There is always one more number than there are dominoes.
        Deque<Integer> dotsPath = new ArrayDeque<>();
        Deque<Domino> dominoPath = new ArrayDeque<>();
        dotsPath.push(dominoes.get(0).getLeft());

        while (!dotsPath.isEmpty()) {
            int dots = dotsPath.peek();
            Deque<Integer> candidates = indicesByDots.get(dots);

            // Skip dominoes that were already placed (e.g. from their other half).
            while (!candidates.isEmpty() && used[candidates.peekFirst()]) {
                candidates.removeFirst();
            }

            if (candidates.isEmpty()) {
                // Dead end: the domino that led here is final.
                dotsPath.pop();
                if (!dominoPath.isEmpty()) {
                    reversedChain.add(dominoPath.pop());
                }
            } else {
                int index = candidates.removeFirst();
                used[index] = true;
                Domino domino = dominoes.get(index);

                if (domino.getLeft() == dots) {
                    dotsPath.push(domino.getRight());
                    dominoPath.push(domino);
                } else {
                    // Walk through the domino from its right half to its left half: flip it.
                    dotsPath.push(domino.getLeft());
                    dominoPath.push(new Domino(domino.getRight(), domino.getLeft()));
                }
            }
        }

        Collections.reverse(reversedChain);
        return reversedChain;
    }

}
