- **Format:** the question must look like `What is ...?`. Anything else, such as "Who is the President...", is rejected.
- **Parsing:** the text is split into words. The first word must be a number, and `strconv.Atoi` handles negative and large values. After that come any number of `<operation> <number>` pairs, applied strictly left to right, so `3 plus 2 multiplied by 3` gives 15.
- **Operations:** a lookup table tries one-word and two-word names, so `plus`, `minus`, `multiplied by` and `divided by` all work. Unknown operations (`cubed`), two operations in a row, a missing operand, two numbers in a row, and prefix or postfix notation all return `(0, false)`.
- **Division:** it is integer division, and division by zero returns `(0, false)` instead of panicking.

wordy.go
```
// Package wordy evaluates simple math word problems such as "What is 5 plus 13?".
package wordy

import (
	"strconv"
	"strings"
)

// operation applies a binary operation to its two operands. The boolean result
// is false if the operation cannot be evaluated, e.g. when dividing by zero.
type operation func(a, b int) (int, bool)

// maxOperationWords is the number of words in the longest operation name.
const maxOperationWords = 2

// operations maps the name of each supported operation to its implementation.
// A name consists of up to maxOperationWords words separated by single spaces.
var operations = map[string]operation{
	"plus":          func(a, b int) (int, bool) { return a + b, true },
	"minus":         func(a, b int) (int, bool) { return a - b, true },
	"multiplied by": func(a, b int) (int, bool) { return a * b, true },
	"divided by": func(a, b int) (int, bool) {
		if b == 0 {
			return 0, false
		}
		return a / b, true
	},
}

// Answer evaluates a math word problem such as "What is 5 plus 13?".
//
// The supported operations are "plus", "minus", "multiplied by" and
// "divided by". They are evaluated strictly from left to right, ignoring the
// usual order of operations, and division is integer division.
//
// The boolean result is false if the question is not a valid math word problem:
// it is not of the form "What is ...?", it uses an unsupported operation, its
// syntax is invalid (e.g. "What is 1 plus plus 2?") or it divides by zero.
func Answer(question string) (int, bool) {
	question = strings.TrimSpace(question)
	if !strings.HasSuffix(question, "?") {
		return 0, false
	}
	words := strings.Fields(strings.TrimSuffix(question, "?"))

	// A problem is "What is" followed by an expression.
	if len(words) < 3 || words[0] != "What" || words[1] != "is" {
		return 0, false
	}
	words = words[2:]

	// The expression starts with a number...
	result, err := strconv.Atoi(words[0])
	if err != nil {
		return 0, false
	}
	words = words[1:]

	// ...followed by any number of "<operation> <number>" pairs.
	for len(words) > 0 {
		op, rest := nextOperation(words)
		if op == nil || len(rest) == 0 {
			return 0, false
		}
		operand, err := strconv.Atoi(rest[0])
		if err != nil {
			return 0, false
		}
		next, ok := op(result, operand)
		if !ok {
			return 0, false
		}
		result, words = next, rest[1:]
	}

	return result, true
}

// nextOperation looks for a supported operation at the start of words. It
// returns the operation together with the words following it, or a nil
// operation if words do not start with a supported operation.
func nextOperation(words []string) (operation, []string) {
	for n := 1; n <= maxOperationWords && n <= len(words); n++ {
		if op, ok := operations[strings.Join(words[:n], " ")]; ok {
			return op, words[n:]
		}
	}
	return nil, nil
}
```

