```rust
// this module adds some functionality based on the required implementations
// here like: `LinkedList::pop_back` or `Clone for LinkedList<T>`
// You are free to use anything in it, but it's mainly for the test framework.
mod pre_implemented;

use std::marker::PhantomData;
use std::ptr::NonNull;

// Safety invariants of the list:
// - Every node reachable from `front`/`back` was allocated via `Box` and is
//   exclusively owned by the list.
// - For every node `n` with `n.next == Some(m)`, `m.prev == Some(n)` and vice versa.
// - `front` is the node without `prev`, `back` is the node without `next`;
//   both are `None` iff the list is empty.
// - `len` equals the number of nodes.
struct Node<T> {
    element: T,
    prev: Option<NonNull<Node<T>>>,
    next: Option<NonNull<Node<T>>>,
}

pub struct LinkedList<T> {
    front: Option<NonNull<Node<T>>>,
    back: Option<NonNull<Node<T>>>,
    len: usize,
    // signals ownership of boxed nodes (drop check) and keeps covariance
    _marker: PhantomData<Box<Node<T>>>,
}

pub struct Cursor<'a, T> {
    list: &'a mut LinkedList<T>,
    // `None` only if the list is empty
    node: Option<NonNull<Node<T>>>,
}

pub struct Iter<'a, T> {
    next: Option<NonNull<Node<T>>>,
    _marker: PhantomData<&'a T>,
}

// SAFETY: the list owns its elements exclusively, like `Box<T>`/`Vec<T>`.
unsafe impl<T: Send> Send for LinkedList<T> {}
unsafe impl<T: Sync> Sync for LinkedList<T> {}

// SAFETY: a cursor is semantically a `&mut LinkedList<T>`.
unsafe impl<T: Send> Send for Cursor<'_, T> {}
unsafe impl<T: Sync> Sync for Cursor<'_, T> {}

// SAFETY: an iterator is semantically a `&LinkedList<T>`.
unsafe impl<T: Sync> Send for Iter<'_, T> {}
unsafe impl<T: Sync> Sync for Iter<'_, T> {}

impl<T> LinkedList<T> {
    pub fn new() -> Self {
        LinkedList {
            front: None,
            back: None,
            len: 0,
            _marker: PhantomData,
        }
    }

    // You may be wondering why it's necessary to have is_empty()
    // when it can easily be determined from len().
    // It's good custom to have both because len() can be expensive for some types,
    // whereas is_empty() is almost always cheap.
    // (Also ask yourself whether len() is expensive for LinkedList)
    pub fn is_empty(&self) -> bool {
        self.len == 0
    }

    pub fn len(&self) -> usize {
        self.len
    }

    /// Return a cursor positioned on the front element
    pub fn cursor_front(&mut self) -> Cursor<'_, T> {
        let node = self.front;
        Cursor { list: self, node }
    }

    /// Return a cursor positioned on the back element
    pub fn cursor_back(&mut self) -> Cursor<'_, T> {
        let node = self.back;
        Cursor { list: self, node }
    }

    /// Return an iterator that moves from front to back
    pub fn iter(&self) -> Iter<'_, T> {
        Iter {
            next: self.front,
            _marker: PhantomData,
        }
    }
}

impl<T> Drop for LinkedList<T> {
    fn drop(&mut self) {
        // Removing every element through the cursor frees all nodes.
        while self.cursor_front().take().is_some() {}
    }
}

// the cursor is expected to act as if it is at the position of an element
// and it also has to work with and be able to insert into an empty list.
impl<T> Cursor<'_, T> {
    /// Take a mutable reference to the current element
    pub fn peek_mut(&mut self) -> Option<&mut T> {
        // SAFETY: `node` points to a live node owned by the list, which we
        // borrow mutably for the lifetime of the cursor; the returned
        // reference is tied to `&mut self`, so it cannot alias.
        self.node.map(|n| unsafe { &mut (*n.as_ptr()).element })
    }

    /// Move one position forward (towards the back) and
    /// return a reference to the new position
    #[allow(clippy::should_implement_trait)]
    pub fn next(&mut self) -> Option<&mut T> {
        // SAFETY: `node` points to a live node owned by the list.
        let next = unsafe { (*self.node?.as_ptr()).next }?;
        self.node = Some(next);
        // SAFETY: `next` is a live node of the list; borrow tied to `&mut self`.
        Some(unsafe { &mut (*next.as_ptr()).element })
    }

    /// Move one position backward (towards the front) and
    /// return a reference to the new position
    pub fn prev(&mut self) -> Option<&mut T> {
        // SAFETY: `node` points to a live node owned by the list.
        let prev = unsafe { (*self.node?.as_ptr()).prev }?;
        self.node = Some(prev);
        // SAFETY: `prev` is a live node of the list; borrow tied to `&mut self`.
        Some(unsafe { &mut (*prev.as_ptr()).element })
    }

    /// Remove and return the element at the current position and move the cursor
    /// to the neighboring element that's closest to the back. This can be
    /// either the next or previous position.
    pub fn take(&mut self) -> Option<T> {
        let node = self.node?;
        // SAFETY: `node` was allocated by `Box` and is owned by the list. We
        // unlink it below so no other pointer to it remains, then free it once.
        let boxed = unsafe { Box::from_raw(node.as_ptr()) };
        let prev = boxed.prev;
        let next = boxed.next;

        match prev {
            // SAFETY: `p` is a live node of the list distinct from `node`.
            Some(p) => unsafe { (*p.as_ptr()).next = next },
            None => self.list.front = next,
        }
        match next {
            // SAFETY: `n` is a live node of the list distinct from `node`.
            Some(n) => unsafe { (*n.as_ptr()).prev = prev },
            None => self.list.back = prev,
        }

        self.list.len -= 1;
        self.node = next.or(prev);
        Some(boxed.element)
    }

    pub fn insert_after(&mut self, element: T) {
        let new = Self::alloc(element);
        match self.node {
            None => {
                self.list.front = Some(new);
                self.list.back = Some(new);
                self.node = Some(new);
            }
            Some(cur) => {
                // SAFETY: `cur` and `new` are live, distinct nodes; the
                // neighbor `next` (if any) is a live node of the list.
                unsafe {
                    let next = (*cur.as_ptr()).next;
                    (*new.as_ptr()).prev = Some(cur);
                    (*new.as_ptr()).next = next;
                    (*cur.as_ptr()).next = Some(new);
                    match next {
                        Some(n) => (*n.as_ptr()).prev = Some(new),
                        None => self.list.back = Some(new),
                    }
                }
            }
        }
        self.list.len += 1;
    }

    pub fn insert_before(&mut self, element: T) {
        let new = Self::alloc(element);
        match self.node {
            None => {
                self.list.front = Some(new);
                self.list.back = Some(new);
                self.node = Some(new);
            }
            Some(cur) => {
                // SAFETY: `cur` and `new` are live, distinct nodes; the
                // neighbor `prev` (if any) is a live node of the list.
                unsafe {
                    let prev = (*cur.as_ptr()).prev;
                    (*new.as_ptr()).next = Some(cur);
                    (*new.as_ptr()).prev = prev;
                    (*cur.as_ptr()).prev = Some(new);
                    match prev {
                        Some(p) => (*p.as_ptr()).next = Some(new),
                        None => self.list.front = Some(new),
                    }
                }
            }
        }
        self.list.len += 1;
    }

    /// Allocate an unlinked node; ownership is transferred to the list when linked.
    fn alloc(element: T) -> NonNull<Node<T>> {
        let boxed = Box::new(Node {
            element,
            prev: None,
            next: None,
        });
        NonNull::from(Box::leak(boxed))
    }
}

impl<'a, T> Iterator for Iter<'a, T> {
    type Item = &'a T;

    fn next(&mut self) -> Option<&'a T> {
        let node = self.next?;
        // SAFETY: the iterator borrows the list immutably for `'a`, so all
        // nodes stay alive and unmodified for `'a`.
        unsafe {
            let node_ref = &*node.as_ptr();
            self.next = node_ref.next;
            Some(&node_ref.element)
        }
    }
}
