// this module adds some functionality based on the required implementations
// here like: `LinkedList::pop_back` or `Clone for LinkedList<T>`
// You are free to use anything in it, but it's mainly for the test framework.
mod pre_implemented;

use std::marker::PhantomData;
use std::ptr::NonNull;

// # Design and safety invariants
//
// Every element lives in its own heap-allocated `Node`. A node is allocated with a `Box`, which is
// immediately turned into a raw pointer with `Box::leak` (see `alloc_node`). From then on the node
// is *owned by the list*: it is only reachable through the pointers stored in the list and in its
// neighbouring nodes, and it is turned back into a `Box` (see `LinkedList::unlink`) exactly once:
// when it is removed from the list. That way, every node is freed exactly once.
//
// The following invariants hold for every `LinkedList` whenever none of its methods is running:
//
// 1. Every `Some` pointer in `front`, in `back` and in the `prev`/`next` fields of the nodes points
//    to a live, initialized `Node<T>` that belongs to the same list.
// 2. An empty list has `front == back == None` and `len == 0`. Otherwise `front` points to the
//    first and `back` to the last node of the list.
// 3. Following the `next` pointers from `front` visits exactly `len` nodes and ends at `back`.
//    The `prev` pointer of the first node and the `next` pointer of the last node are `None`.
// 4. The links are consistent in both directions: `a.next == Some(b)` if and only if
//    `b.prev == Some(a)`.
// 5. Apart from the temporary pointers inside of a `Cursor` or an `Iter` (which borrow the list),
//    there are no other pointers to the nodes of the list.
//
// The safe API cannot break these invariants:
//
// - Nodes are only added or removed through a `Cursor` (that includes `Drop`, which uses
//   `pop_front`). A cursor holds a `&mut LinkedList`, so nothing else can access the list while
//   it exists.
// - An `Iter` only reads the nodes, and the list stays borrowed for as long as the iterator and
//   the references it handed out are alive.
//
// A `Cursor` upholds one more invariant: `current` is `None` if and only if the list is empty,
// otherwise it points to a node of the list. As the cursor has exclusive access to the list,
// nobody else can remove that node, so the pointer can never dangle.

/// A pointer to a node, or `None` if there is no such node.
type Link<T> = Option<NonNull<Node<T>>>;

/// A heap-allocated node holding one element of the list.
struct Node<T> {
    element: T,
    prev: Link<T>,
    next: Link<T>,
}

/// Moves `node` to the heap and returns a pointer to it.
///
/// The caller becomes the owner of the allocation and has to free it by turning the pointer
/// back into a `Box` (with `Box::from_raw`) exactly once.
fn alloc_node<T>(node: Node<T>) -> NonNull<Node<T>> {
    NonNull::from(Box::leak(Box::new(node)))
}

/// A doubly linked list.
///
/// Elements are added and removed through a [`Cursor`].
pub struct LinkedList<T> {
    // The first and the last node of the list. Both are `None` if the list is empty.
    front: Link<T>,
    back: Link<T>,
    // The number of nodes in the list.
    len: usize,
    // The list owns its nodes, and thereby its elements, like a collection of `Box<Node<T>>`
    // would. This tells the drop checker about it and keeps the list covariant over `T`.
    _marker: PhantomData<Box<Node<T>>>,
}

/// A cursor that can move back and forth through a [`LinkedList`] and insert or remove elements
/// at its position.
///
/// A cursor is always positioned on an element, unless the list is empty.
pub struct Cursor<'a, T> {
    // Exclusive access to the list: while the cursor exists, nothing else can touch the nodes.
    list: &'a mut LinkedList<T>,
    // The node the cursor is positioned on. It is `None` if and only if the list is empty.
    current: Link<T>,
}

/// An iterator over the elements of a [`LinkedList`], from front to back.
pub struct Iter<'a, T> {
    // The node holding the next element to yield, `None` once the end of the list is reached.
    next_node: Link<T>,
    // The iterator hands out `&'a T`s.
    _marker: PhantomData<&'a T>,
}

// SAFETY: A `LinkedList<T>` owns its elements exclusively, just like a `Vec<T>` does. The raw
// pointers in it only point to nodes of the very same list, so no state is shared with other
// lists. Sending the list to another thread therefore just sends its elements, which is fine if
// `T: Send`.
unsafe impl<T: Send> Send for LinkedList<T> {}

// SAFETY: Through a shared reference to the list, elements are only accessible as `&T` (via
// `iter`), and the list has no interior mutability: everything that modifies it needs `&mut`.
// Sharing the list across threads is therefore the same as sharing `&T`s, which is fine if
// `T: Sync`.
unsafe impl<T: Sync> Sync for LinkedList<T> {}

// SAFETY: A `Cursor<'_, T>` behaves like a `&mut LinkedList<T>`: it can move elements of type `T`
// into and out of the list, and it can hand out `&mut T`s. That's fine to do from another
// thread if `T: Send`.
unsafe impl<T: Send> Send for Cursor<'_, T> {}

// SAFETY: Like for `&mut LinkedList<T>`, a shared reference to a cursor can't do anything at all,
// as all of its methods need `&mut self`. Requiring `T: Sync` mirrors `&mut LinkedList<T>`.
unsafe impl<T: Sync> Sync for Cursor<'_, T> {}

// SAFETY: An `Iter<'_, T>` behaves like a `&LinkedList<T>`: it only hands out `&T`s, so it can be
// sent to another thread if `T: Sync`.
unsafe impl<T: Sync> Send for Iter<'_, T> {}

// SAFETY: An `Iter<'_, T>` only reads the list, and its state can only be changed through
// `&mut self`. Sharing it between threads therefore only shares `&T`s, which is fine if
// `T: Sync`.
unsafe impl<T: Sync> Sync for Iter<'_, T> {}

impl<T> LinkedList<T> {
    pub fn new() -> Self {
        LinkedList {
            front: None,
            back: None,
            len: 0,
            _marker: PhantomData,
        }
    }

    // You may be wondering why it's necessary to have is_empty()
    // when it can easily be determined from len().
    // It's good custom to have both because len() can be expensive for some types,
    // whereas is_empty() is almost always cheap.
    // (Also ask yourself whether len() is expensive for LinkedList)
    pub fn is_empty(&self) -> bool {
        self.len == 0
    }

    pub fn len(&self) -> usize {
        self.len
    }

    /// Return a cursor positioned on the front element
    pub fn cursor_front(&mut self) -> Cursor<'_, T> {
        let current = self.front;
        Cursor { list: self, current }
    }

    /// Return a cursor positioned on the back element
    pub fn cursor_back(&mut self) -> Cursor<'_, T> {
        let current = self.back;
        Cursor { list: self, current }
    }

    /// Return an iterator that moves from front to back
    pub fn iter(&self) -> Iter<'_, T> {
        Iter {
            next_node: self.front,
            _marker: PhantomData,
        }
    }

    /// Allocates a node holding `element` and links it into the list between `prev` and `next`.
    /// Returns a pointer to the new node.
    ///
    /// # Safety
    ///
    /// `prev` and `next` must be neighbours in this list, so that the new node fits between them:
    /// - if `prev` is `Some`, it points to a node of this list and `next` is the successor of
    ///   that node,
    /// - if `prev` is `None`, `next` is the front of the list,
    /// - if `next` is `Some`, it points to a node of this list and `prev` is the predecessor of
    ///   that node,
    /// - if `next` is `None`, `prev` is the back of the list.
    ///
    /// For an empty list this means that both have to be `None`.
    unsafe fn insert_between(
        &mut self,
        prev: Link<T>,
        next: Link<T>,
        element: T,
    ) -> NonNull<Node<T>> {
        // Allocate first: if that fails, the list has not been touched yet.
        let node = alloc_node(Node {
            element,
            prev,
            next,
        });

        match prev {
            // SAFETY: By the contract of this function `prev` points to a live node of this
            // list. We have exclusive access to the list and so to all of its nodes
            // (invariant 5), hence there is no reference that could be invalidated by this write.
            Some(prev) => unsafe { (*prev.as_ptr()).next = Some(node) },
            // The new node becomes the first one (`next` was the front of the list, or the list
            // was empty).
            None => self.front = Some(node),
        }
        match next {
            // SAFETY: Same as above, for `next`.
            Some(next) => unsafe { (*next.as_ptr()).prev = Some(node) },
            // The new node becomes the last one (`prev` was the back of the list, or the list
            // was empty).
            None => self.back = Some(node),
        }
        self.len += 1;

        node
    }

    /// Removes `node` from the list, frees its allocation and returns its contents.
    ///
    /// # Safety
    ///
    /// `node` must point to a node of this list.
    unsafe fn unlink(&mut self, node: NonNull<Node<T>>) -> Node<T> {
        // SAFETY: By the contract of this function `node` is a node of this list. Each node was
        // allocated by `alloc_node` (i.e. by `Box`) and is owned by the list, so it is valid to
        // take that ownership back here. It can't be freed twice, because the node is unlinked
        // below and nothing points to it afterwards.
        let boxed = unsafe { Box::from_raw(node.as_ptr()) };
        // Move the contents out of the allocation. The (now empty) allocation is freed when
        // `boxed` goes out of scope; the element is *not* dropped.
        let removed = *boxed;

        match removed.prev {
            // SAFETY: By invariant 1 the predecessor of a node of the list is a live node of the
            // list. We have exclusive access to all nodes, so nothing is invalidated by the write.
            Some(prev) => unsafe { (*prev.as_ptr()).next = removed.next },
            // The removed node was the front.
            None => self.front = removed.next,
        }
        match removed.next {
            // SAFETY: Same as above, for the successor.
            Some(next) => unsafe { (*next.as_ptr()).prev = removed.prev },
            // The removed node was the back.
            None => self.back = removed.prev,
        }
        self.len -= 1;

        removed
    }
}

impl<T> Drop for LinkedList<T> {
    fn drop(&mut self) {
        // The nodes are freed one by one. A `Node` only contains raw pointers, so dropping
        // one never drops its neighbours: there is no recursion that could overflow the stack,
        // no matter how long the list is.
        //
        // Dropping an element may panic. In that case the remaining elements must still be dropped
        // (and their nodes freed) instead of being leaked, which is what this guard takes care of
        // while the panic unwinds.
        struct DropGuard<'a, T>(&'a mut LinkedList<T>);

        impl<T> Drop for DropGuard<'_, T> {
            fn drop(&mut self) {
                // Only reached if dropping an element panicked. If dropping another element
                // panics now, the process aborts, as usual for a panic during unwinding.
                while self.0.pop_front().is_some() {}
            }
        }

        while let Some(element) = self.pop_front() {
            let guard = DropGuard(self);
            drop(element);
            // Dropping the element did not panic, so the guard is not needed.
            std::mem::forget(guard);
        }
    }
}

// the cursor is expected to act as if it is at the position of an element
// and it also has to work with and be able to insert into an empty list.
impl<T> Cursor<'_, T> {
    /// Take a mutable reference to the current element
    pub fn peek_mut(&mut self) -> Option<&mut T> {
        let node = self.current?;
        // SAFETY: `node` points to a live node of the list (cursor invariant). The cursor has
        // exclusive access to the list and the returned reference mutably borrows the cursor, so
        // nothing else can access this element while the reference is alive. Only the `element`
        // field is borrowed, not the whole node.
        Some(unsafe { &mut (*node.as_ptr()).element })
    }

    /// Move one position forward (towards the back) and
    /// return a reference to the new position
    ///
    /// If the cursor is already on the last element, it stays there and `None` is returned.
    #[allow(clippy::should_implement_trait)]
    pub fn next(&mut self) -> Option<&mut T> {
        let current = self.current?;
        // SAFETY: `current` points to a live node of the list (cursor invariant).
        let next = unsafe { (*current.as_ptr()).next }?;
        // `next` is a node of the list (invariant 1), so the cursor invariant still holds.
        self.current = Some(next);
        self.peek_mut()
    }

    /// Move one position backward (towards the front) and
    /// return a reference to the new position
    ///
    /// If the cursor is already on the first element, it stays there and `None` is returned.
    pub fn prev(&mut self) -> Option<&mut T> {
        let current = self.current?;
        // SAFETY: `current` points to a live node of the list (cursor invariant).
        let prev = unsafe { (*current.as_ptr()).prev }?;
        // `prev` is a node of the list (invariant 1), so the cursor invariant still holds.
        self.current = Some(prev);
        self.peek_mut()
    }

    /// Remove and return the element at the current position and move the cursor
    /// to the neighboring element that's closest to the back. This can be
    /// either the next or previous position.
    pub fn take(&mut self) -> Option<T> {
        let node = self.current?;
        // SAFETY: `node` is the current node of the cursor, which is a node of the list (cursor
        // invariant).
        let Node {
            element,
            prev,
            next,
        } = unsafe { self.list.unlink(node) };
        // The removed node must not be used any more. Move to a neighbour that is still in the
        // list: preferably the next one, otherwise the previous one. If there is no neighbour,
        // the list is empty now, and `current` is `None`, as required by the cursor invariant.
        self.current = next.or(prev);
        Some(element)
    }

    /// Insert a new element directly after the current one.
    ///
    /// The cursor stays on the current element. If the list is empty, the new element becomes
    /// its only element and the cursor moves onto it.
    pub fn insert_after(&mut self, element: T) {
        let next = match self.current {
            // SAFETY: `current` points to a live node of the list (cursor invariant).
            Some(current) => unsafe { (*current.as_ptr()).next },
            // The list is empty: the new node has no neighbours at all.
            None => None,
        };
        // SAFETY: `current` and its successor `next` are neighbours in the list. If the list is
        // empty, both are `None`, which is what `insert_between` requires for an empty list.
        let node = unsafe { self.list.insert_between(self.current, next, element) };
        if self.current.is_none() {
            // The list was empty before, so the new node is the only node.
            self.current = Some(node);
        }
    }

    /// Insert a new element directly before the current one.
    ///
    /// The cursor stays on the current element. If the list is empty, the new element becomes
    /// its only element and the cursor moves onto it.
    pub fn insert_before(&mut self, element: T) {
        let prev = match self.current {
            // SAFETY: `current` points to a live node of the list (cursor invariant).
            Some(current) => unsafe { (*current.as_ptr()).prev },
            // The list is empty: the new node has no neighbours at all.
            None => None,
        };
        // SAFETY: `current` and its predecessor `prev` are neighbours in the list. If the list is
        // empty, both are `None`, which is what `insert_between` requires for an empty list.
        let node = unsafe { self.list.insert_between(prev, self.current, element) };
        if self.current.is_none() {
            // The list was empty before, so the new node is the only node.
            self.current = Some(node);
        }
    }
}

impl<'a, T> Iterator for Iter<'a, T> {
    type Item = &'a T;

    fn next(&mut self) -> Option<&'a T> {
        let node = self.next_node?;
        // SAFETY: `node` points to a live node of the list (invariant 1). `LinkedList::iter`
        // borrows the list for `'a`, so no node can be modified or freed while the returned
        // reference is alive: all the code that does so needs `&mut LinkedList`.
        let node: &'a Node<T> = unsafe { &*node.as_ptr() };
        self.next_node = node.next;
        Some(&node.element)
    }
}
