            Some(p) => unsafe { (*p.as_ptr()).next = node.next },
            None => self.list.front = node.next,
        }
        match node.next {
            Some(n) => unsafe { (*n.as_ptr()).prev = node.prev },
            None => self.list.back = node.prev,
        }
        self.list.len -= 1;
        self.current = node.next.or(node.prev);
        Some(node.elem)
