        let new = unsafe { NonNull::new_unchecked(Box::into_raw(new)) };
        match self.current {
            None => {
                self.list.front = Some(new);
                self.list.back = Some(new);
                self.current = Some(new);
            }
            Some(cur) => unsafe {
                // SAFETY: cur and its next are live nodes in this list.
                let next = (*cur.as_ptr()).next;
                (*new.as_ptr()).next = next;
                (*cur.as_ptr()).next = Some(new);
                match next {
                    Some(n) => (*n.as_ptr()).prev = Some(new),
                    None => self.list.back = Some(new),
                }
            },
        }
        self.list.len += 1;
    }

    pub fn insert_before(&mut self, element: T) {
        let new = Box::new(Node {
            elem: element,
            prev: None,
            next: self.current,
        });
        // SAFETY: Box::into_raw never returns null.
        let new = unsafe { NonNull::new_unchecked(Box::into_raw(new)) };
        match self.current {
            None => {
                self.list.front = Some(new);
                self.list.back = Some(new);
                self.current = Some(new);
            }
            Some(cur) => unsafe {
