                    Some(p) => (*p.as_ptr()).next = Some(new),
                    None => self.list.front = Some(new),
                }
            },
        }
        self.list.len += 1;
    }
}

impl<'a, T> Iterator for Iter<'a, T> {
    type Item = &'a T;

    fn next(&mut self) -> Option<&'a T> {
        let ptr = self.next?;
        // SAFETY: the list is borrowed for 'a, so the node stays alive and unmodified.
        let node = unsafe { &*ptr.as_ptr() };
        self.next = node.next;
