// - For every node `n`, `n.next.prev == n` and `n.prev.next == n` (when present).
// - `front.prev == None` and `back.next == None`.
// - `len` equals the number of nodes.
pub struct LinkedList<T> {
    front: Option<NonNull<Node<T>>>,
    back: Option<NonNull<Node<T>>>,
    len: usize,
    // Signals ownership of nodes to the drop checker and keeps covariance over T.
