        // from the removed node; we fix up their links to skip it.
        unsafe {
            match prev {
                Some(p) => (*p.as_ptr()).next = next,
                None => self.list.front = next,
            }
            match next {
                Some(n) => (*n.as_ptr()).prev = prev,
                None => self.list.back = prev,
            }
        }
        self.list.len -= 1;
        self.current = next.or(prev);
        Some(node.element)
