pub struct LinkedList<T> {
    front: Option<NonNull<Node<T>>>,
    back: Option<NonNull<Node<T>>>,
    len: usize,
    _marker: PhantomData<Box<Node<T>>>,
}

// Invariant: `node` is None or points to a live node of `list`.
pub struct Cursor<'a, T> {
    list: &'a mut LinkedList<T>,
    node: Option<NonNull<Node<T>>>,
}

pub struct Iter<'a, T> {
    node: Option<NonNull<Node<T>>>,
    _marker: PhantomData<&'a T>,
}

// SAFETY: the list owns its elements uniquely; it is like Box-based containers.
unsafe impl<T: Send> Send for LinkedList<T> {}
unsafe impl<T: Sync> Sync for LinkedList<T> {}
unsafe impl<T: Send> Send for Cursor<'_, T> {}
unsafe impl<T: Sync> Sync for Cursor<'_, T> {}
unsafe impl<T: Sync> Send for Iter<'_, T> {}
unsafe impl<T: Sync> Sync for Iter<'_, T> {}

impl<T> LinkedList<T> {
    pub fn new() -> Self {
        LinkedList {
            front: None,
            back: None,
            len: 0,
            _marker: PhantomData,
        }
    }

    // You may be wondering why it's necessary to have is_empty()
    // when it can easily be determined from len().
    // It's good custom to have both because len() can be expensive for some types,
    // whereas is_empty() is almost always cheap.
    // (Also ask yourself whether len() is expensive for LinkedList)
    pub fn is_empty(&self) -> bool {
        self.len == 0
    }

    pub fn len(&self) -> usize {
        self.len
    }

    /// Return a cursor positioned on the front element
    pub fn cursor_front(&mut self) -> Cursor<'_, T> {
        let node = self.front;
        Cursor { list: self, node }
    }

    /// Return a cursor positioned on the back element
    pub fn cursor_back(&mut self) -> Cursor<'_, T> {
        let node = self.back;
        Cursor { list: self, node }
    }

    /// Return an iterator that moves from front to back
    pub fn iter(&self) -> Iter<'_, T> {
        Iter {
            node: self.front,
            _marker: PhantomData,
        }
    }
}

impl<T> Drop for LinkedList<T> {
    fn drop(&mut self) {
        let mut cur = self.cursor_front();
        while cur.take().is_some() {}
    }
}

// the cursor is expected to act as if it is at the position of an element
// and it also has to work with and be able to insert into an empty list.
impl<T> Cursor<'_, T> {
    /// Take a mutable reference to the current element
    pub fn peek_mut(&mut self) -> Option<&mut T> {
        // SAFETY: node is a live node of the list, and we hold &mut self.
        self.node.map(|n| unsafe { &mut (*n.as_ptr()).element })
    }

    /// Move one position forward (towards the back) and
    /// return a reference to the new position
    #[allow(clippy::should_implement_trait)]
    pub fn next(&mut self) -> Option<&mut T> {
        // SAFETY: node is live.
        let next = unsafe { self.node?.as_ref().next }?;
        self.node = Some(next);
        self.peek_mut()
    }

    /// Move one position backward (towards the front) and
    /// return a reference to the new position
    pub fn prev(&mut self) -> Option<&mut T> {
        // SAFETY: node is live.
        let prev = unsafe { self.node?.as_ref().prev }?;
        self.node = Some(prev);
        self.peek_mut()
    }

    /// Remove and return the element at the current position and move the cursor
    /// to the neighboring element that's closest to the back. This can be
    /// either the next or previous position.
    pub fn take(&mut self) -> Option<T> {
        let node = self.node?;
        // SAFETY: node was created by Box::into_raw and is still live; after
        // unlinking it nothing else references it, so reclaiming the Box is sound.
        unsafe {
            let boxed = Box::from_raw(node.as_ptr());
            match boxed.prev {
                Some(p) => (*p.as_ptr()).next = boxed.next,
                None => self.list.front = boxed.next,
            }
            match boxed.next {
                Some(n) => (*n.as_ptr()).prev = boxed.prev,
                None => self.list.back = boxed.prev,
            }
            self.list.len -= 1;
            self.node = boxed.next.or(boxed.prev);
            Some(boxed.element)
        }
    }

    pub fn insert_after(&mut self, element: T) {
        let new = Box::new(Node {
            element,
            prev: self.node,
            next: None,
        });
        let new = NonNull::from(Box::leak(new));
        // SAFETY: all pointers touched are live nodes of this list.
        unsafe {
            match self.node {
                None => {
                    self.list.front = Some(new);
                    self.list.back = Some(new);
                    self.node = Some(new);
                }
                Some(cur) => {
                    let next = (*cur.as_ptr()).next;
                    (*new.as_ptr()).next = next;
                    (*cur.as_ptr()).next = Some(new);
                    match next {
                        Some(n) => (*n.as_ptr()).prev = Some(new),
                        None => self.list.back = Some(new),
                    }
                }
            }
        }
        self.list.len += 1;
    }

    pub fn insert_before(&mut self, element: T) {
        let new = Box::new(Node {
            element,
            prev: None,
            next: self.node,
        });
        let new = NonNull::from(Box::leak(new));
        // SAFETY: all pointers touched are live nodes of this list.
        unsafe {
            match self.node {
                None => {
                    self.list.front = Some(new);
                    self.list.back = Some(new);
                    self.node = Some(new);
                }
                Some(cur) => {
                    let prev = (*cur.as_ptr()).prev;
                    (*new.as_ptr()).prev = prev;
                    (*cur.as_ptr()).prev = Some(new);
                    match prev {
                        Some(p) => (*p.as_ptr()).next = Some(new),
                        None => self.list.front = Some(new),
                    }
                }
            }
        }
        self.list.len += 1;
    }
}

impl<'a, T> Iterator for Iter<'a, T> {
    type Item = &'a T;

    fn next(&mut self) -> Option<&'a T> {
        let node = self.node?;
        // SAFETY: the list is immutably borrowed for 'a, so nodes stay live.
        unsafe {
            let r = &*node.as_ptr();
            self.node = r.next;
            Some(&r.element)
        }
    }
}
```

I implemented the doubly linked list in `src/lib.rs`. The work covers all five steps.

- **Structure:** `LinkedList<T>` stores `front` and `back` as `Option<NonNull<Node<T>>>` plus a `len` counter. Each `Node` is heap-allocated through `Box` and linked in both directions. `PhantomData<Box<Node<T>>>` tells the drop checker the list owns its elements. Because `NonNull<T>` is covariant, `LinkedList<T>` is covariant over `T`.
- **Cursor:** `Cursor` holds `&'a mut LinkedList<T>` and the current node pointer. While the list is non-empty, the cursor always sits on an element, and `node` is `None` only for an empty list.
  - `next` and `prev` return `None` and stay put at the ends.
  - `take` removes the current node and moves to the next node, or to the previous one if there is no next.
  - `insert_after` and `insert_before` keep the cursor on the current element.
  - Inserting into an empty list places the cursor on the new element.
  - All modification goes through the cursor, so `push_*`/`pop_*` in `pre_implemented` work unchanged.
- **Iter:** holds a raw pointer to the next node and a `PhantomData<&'a T>`. It borrows the list immutably for `'a`, so nothing can modify the nodes while it exists.
- **Drop:** repeatedly takes the front element through a cursor, which frees every node.
- **Send/Sync:** implemented manually with `T: Send` / `T: Sync` bounds for `LinkedList`, `Cursor` and `Iter`. `Iter` needs `T: Sync` for both, like `&T`.
- **Safety:** the invariants are documented at the top of the file and each `unsafe` block has a `SAFETY` comment.

