// this module adds some functionality based on the required implementations
// here like: `LinkedList::pop_back` or `Clone for LinkedList<T>`
// You are free to use anything in it, but it's mainly for the test framework.
mod pre_implemented;

use std::marker::PhantomData;
use std::ptr::NonNull;

// # Safety-critical invariants
//
// 1. Every `NonNull<Node<T>>` stored in the list (`front`, `back`, and the `prev`/`next`
//    fields of nodes) points to a live node that was allocated with `Box` and leaked with
//    `Box::leak`. The list is the unique owner of all of its nodes.
// 2. For every node `n` in the list: `n.next == Some(m)` if and only if `m.prev == Some(n)`.
// 3. `front` is the node with `prev == None`, `back` is the node with `next == None`.
//    Both are `None` if and only if the list is empty.
// 4. `len` is exactly the number of nodes reachable from `front` via `next`.
// 5. A `Cursor` holds a unique borrow of the list, so nobody else can modify the list while
//    the cursor exists. `Cursor::node` is `Some` pointing at a node of that list, or `None`
//    if (and only if) the list is empty.
// 6. An `Iter` holds a shared borrow of the list (through its lifetime), so the nodes it
//    points to stay alive and unmodified for as long as the iterator exists.

struct Node<T> {
    element: T,
    prev: Option<NonNull<Node<T>>>,
    next: Option<NonNull<Node<T>>>,
}

/// Allocate a new node on the heap and return a pointer to it.
/// The caller becomes responsible for eventually freeing it with `Box::from_raw`.
fn new_node<T>(
    element: T,
    prev: Option<NonNull<Node<T>>>,
    next: Option<NonNull<Node<T>>>,
) -> NonNull<Node<T>> {
    NonNull::from(Box::leak(Box::new(Node {
        element,
        prev,
        next,
    })))
}

pub struct LinkedList<T> {
    front: Option<NonNull<Node<T>>>,
    back: Option<NonNull<Node<T>>>,
    len: usize,
    // Signals ownership of the elements (for drop check) and gives covariance over `T`.
    _marker: PhantomData<Box<Node<T>>>,
}

pub struct Cursor<'a, T> {
    list: &'a mut LinkedList<T>,
    node: Option<NonNull<Node<T>>>,
}

pub struct Iter<'a, T> {
    next: Option<NonNull<Node<T>>>,
    _marker: PhantomData<&'a T>,
}

// SAFETY: The list uniquely owns its elements (like `Vec<T>` or `Box<T>`), so sending the
// list to another thread is the same as sending the `T`s it owns.
