// SAFETY: A shared reference to the list only allows shared access to the `T`s (the only
// mutation possible goes through `&mut self`), so it's as safe as sharing `&T`.
unsafe impl<T: Sync> Sync for LinkedList<T> {}

// SAFETY: A cursor is semantically a `&mut LinkedList<T>`.
unsafe impl<T: Send> Send for Cursor<'_, T> {}

// SAFETY: A cursor is semantically a `&mut LinkedList<T>`; sharing `&Cursor` gives no
// access at all except what `&mut LinkedList<T>` would give through a shared reference.
unsafe impl<T: Sync> Sync for Cursor<'_, T> {}

// SAFETY: An iterator is semantically a `&'a T` (several of them, in fact).
unsafe impl<T: Sync> Send for Iter<'_, T> {}

// SAFETY: Same as above.
unsafe impl<T: Sync> Sync for Iter<'_, T> {}

