    }

    // You may be wondering why it's necessary to have is_empty()
    // when it can easily be determined from len().
    // It's good custom to have both because len() can be expensive for some types,
    // whereas is_empty() is almost always cheap.
    // (Also ask yourself whether len() is expensive for LinkedList)
    pub fn is_empty(&self) -> bool {
        self.len == 0
    }

    pub fn len(&self) -> usize {
        self.len
    }

    /// Return a cursor positioned on the front element
    pub fn cursor_front(&mut self) -> Cursor<'_, T> {
        let node = self.front;
        Cursor { list: self, node }
    }

    /// Return a cursor positioned on the back element
    pub fn cursor_back(&mut self) -> Cursor<'_, T> {
        let node = self.back;
        Cursor { list: self, node }
    }

    /// Return an iterator that moves from front to back
    pub fn iter(&self) -> Iter<'_, T> {
        Iter {
            next: self.front,
            _marker: PhantomData,
        }
    }
}

impl<T> Drop for LinkedList<T> {
    fn drop(&mut self) {
        // Removing every element through the cursor frees each node exactly once.
        let mut cursor = self.cursor_front();
        while cursor.take().is_some() {}
    }
}

impl<T> Cursor<'_, T> {
    /// Insert an element into an empty list and put the cursor on it.
    fn insert_into_empty(&mut self, element: T) {
        debug_assert!(self.node.is_none());
        debug_assert!(self.list.len == 0);
        let new = new_node(element, None, None);
        self.list.front = Some(new);
        self.list.back = Some(new);
        self.list.len = 1;
        self.node = Some(new);
    }
}

// the cursor is expected to act as if it is at the position of an element
// and it also has to work with and be able to insert into an empty list.
impl<T> Cursor<'_, T> {
    /// Take a mutable reference to the current element
    pub fn peek_mut(&mut self) -> Option<&mut T> {
        // SAFETY: `self.node` points to a live node of the list (invariants 1 and 5).
        // The returned reference borrows `self` mutably, and `self` holds a unique borrow
        // of the list, so no other reference to this element can exist.
        self.node
            .map(|node| unsafe { &mut (*node.as_ptr()).element })
    }

    /// Move one position forward (towards the back) and
    /// return a reference to the new position
    #[allow(clippy::should_implement_trait)]
    pub fn next(&mut self) -> Option<&mut T> {
        let node = self.node?;
        // SAFETY: `node` points to a live node of the list (invariants 1 and 5).
        let next = unsafe { (*node.as_ptr()).next }?;
        self.node = Some(next);
        self.peek_mut()
    }

    /// Move one position backward (towards the front) and
    /// return a reference to the new position
    pub fn prev(&mut self) -> Option<&mut T> {
        let node = self.node?;
        // SAFETY: `node` points to a live node of the list (invariants 1 and 5).
        let prev = unsafe { (*node.as_ptr()).prev }?;
        self.node = Some(prev);
        self.peek_mut()
    }

    /// Remove and return the element at the current position and move the cursor
    /// to the neighboring element that's closest to the back. This can be
    /// either the next or previous position.
    pub fn take(&mut self) -> Option<T> {
        let node = self.node?;
        // SAFETY: `node` points to a live node that was created via `Box::leak`
        // (invariant 1). We take back ownership of it here. Afterwards we unlink it from
        // its neighbours below, so no pointer to the freed node remains in the list.
        let boxed = unsafe { Box::from_raw(node.as_ptr()) };
        let Node {
            element,
            prev,
            next,
        } = *boxed;

        match prev {
            // SAFETY: `p` is a live node of the list (invariants 1 and 2), distinct from
            // the removed node.
            Some(p) => unsafe { (*p.as_ptr()).next = next },
            None => self.list.front = next,
        }
        match next {
            // SAFETY: `n` is a live node of the list (invariants 1 and 2), distinct from
            // the removed node.
            Some(n) => unsafe { (*n.as_ptr()).prev = prev },
            None => self.list.back = prev,
        }
        self.list.len -= 1;

        // Prefer the neighbour closer to the back; if there is none, use the other one.
        // This is `None` only if the list is now empty (invariant 5 is preserved).
        self.node = next.or(prev);

        Some(element)
    }

    pub fn insert_after(&mut self, element: T) {
        let current = match self.node {
            Some(current) => current,
            None => return self.insert_into_empty(element),
        };

        // SAFETY: `current` points to a live node of the list (invariants 1 and 5).
        let next = unsafe { (*current.as_ptr()).next };
        let new = new_node(element, Some(current), next);

        // SAFETY: `current` is live (see above).
        unsafe { (*current.as_ptr()).next = Some(new) };
        match next {
            // SAFETY: `n` is a live node of the list (invariants 1 and 2), distinct from `new`.
            Some(n) => unsafe { (*n.as_ptr()).prev = Some(new) },
            None => self.list.back = Some(new),
        }
        self.list.len += 1;
    }

    pub fn insert_before(&mut self, element: T) {
        let current = match self.node {
            Some(current) => current,
            None => return self.insert_into_empty(element),
        };

        // SAFETY: `current` points to a live node of the list (invariants 1 and 5).
        let prev = unsafe { (*current.as_ptr()).prev };
        let new = new_node(element, prev, Some(current));

        // SAFETY: `current` is live (see above).
        unsafe { (*current.as_ptr()).prev = Some(new) };
        match prev {
            // SAFETY: `p` is a live node of the list (invariants 1 and 2), distinct from `new`.
            Some(p) => unsafe { (*p.as_ptr()).next = Some(new) },
            None => self.list.front = Some(new),
        }
        self.list.len += 1;
    }
}

impl<'a, T> Iterator for Iter<'a, T> {
    type Item = &'a T;

    fn next(&mut self) -> Option<&'a T> {
        let node = self.next?;
        // SAFETY: `node` points to a live node of the list. The iterator borrows the list
        // immutably for `'a`, so the node stays alive and is not modified during `'a`
        // (invariant 6).
        let node: &'a Node<T> = unsafe { &*node.as_ptr() };
        self.next = node.next;
        Some(&node.element)
    }
}
