        // SAFETY: `node_ptr` was created by `Box::into_raw` and is still in the
        // list; after unlinking it below nobody else references it, so
        // reconstructing the Box takes back unique ownership exactly once.
        let node = unsafe { Box::from_raw(node_ptr.as_ptr()) };
        let prev = node.prev;
        let next = node.next;

        // SAFETY: neighbours are live nodes of the list (invariant).
