        // SAFETY: `cur` is a live node; `next` (if any) is a live node.
        unsafe {
            let next = cur.as_ref().next;
            let new = Self::alloc(Node {
                element,
                prev: Some(cur),
                next,
            });
            cur.as_mut().next = Some(new);
            match next {
                Some(mut n) => n.as_mut().prev = Some(new),
                None => self.list.back = Some(new),
            }
        }
        self.list.len += 1;
    }

    pub fn insert_before(&mut self, element: T) {
        let Some(mut cur) = self.current else {
            self.insert_into_empty(element);
            return;
        };
        // SAFETY: `cur` is a live node; `prev` (if any) is a live node.
        unsafe {
            let prev = cur.as_ref().prev;
            let new = Self::alloc(Node {
                element,
                prev,
                next: Some(cur),
            });
            cur.as_mut().prev = Some(new);
            match prev {
                Some(mut p) => p.as_mut().next = Some(new),
                None => self.list.front = Some(new),
            }
        }
        self.list.len += 1;
    }

    fn alloc(node: Node<T>) -> NonNull<Node<T>> {
        // SAFETY: `Box::into_raw` never returns null.
        unsafe { NonNull::new_unchecked(Box::into_raw(Box::new(node))) }
    }

    fn insert_into_empty(&mut self, element: T) {
        let new = Self::alloc(Node {
            element,
            prev: None,
            next: None,
        });
        self.list.front = Some(new);
        self.list.back = Some(new);
        self.list.len = 1;
        self.current = Some(new);
    }
}

impl<'a, T> Iterator for Iter<'a, T> {
    type Item = &'a T;

    fn next(&mut self) -> Option<&'a T> {
        let node = self.next?;
        // SAFETY: the iterator borrows the list immutably for `'a`, so the
        // node stays alive and unmodified for that lifetime.
        unsafe {
            let node_ref: &'a Node<T> = &*node.as_ptr();
            self.next = node_ref.next;
            Some(&node_ref.element)
        }
    }
}
