#include "perfect_numbers.h"

#include <stdexcept>

namespace perfect_numbers {

namespace {

// Sum of all positive divisors of `number`, not including `number` itself.
long long aliquot_sum(int number) {
    if (number == 1) {
        return 0;
    }

    long long sum = 1;  // 1 divides every number greater than 1
    for (long long divisor = 2; divisor * divisor <= number; ++divisor) {
        if (number % divisor == 0) {
            sum += divisor;
            const long long complement = number / divisor;
            if (complement != divisor) {
                sum += complement;
            }
        }
    }
    return sum;
}

}  // namespace

classification classify(int number) {
    if (number < 1) {
        throw std::domain_error(
            "Classification is only defined for positive integers");
    }

    const long long sum = aliquot_sum(number);

    if (sum == number) {
        return classification::perfect;
    }
    if (sum > number) {
        return classification::abundant;
    }
    return classification::deficient;
}

}  // namespace perfect_numbers
